window.__D("text/likkutei-sichot/c062",{"p":[[1300061137,"און קדושה — וואָס קומט אַרויס דורך דעם מקיים זיין „לא תעשה”<sup data-n=\"35\">35</sup>.\nאון דאָס איז מתאים צו זיין שיטה „רואין את הנשמע ושומעין את הנראה”: בעת מען האלט ביי דער מדריגה פון „שומעין את הנראה”, אַז די „נראה׳דיקע” גשמיות׳דיקע וועלט ווערט בלויז אייפ־גענומען מיטן ווייטן באַנעם פון „שמי־עה” — ד.ה. באמת איז די מציאות פון",[["35","35","ועפי״ז יובן מה שמסופר בברכות (סא, ב), שכשקיבל ר״ע עליו עול מלכות שמים [„קורא קריאת שמע” — רש״י שם] כשסרקו את בשרו במסרקות של ברזל „אמרו לו תלמידיו רבינו עד כאן” — דלכאורה תמוה: והרי דבר פשוט שגם תלמידי ר״ע היו בעלי מדריגה נעלית ביו־תר, ומה היתה תמיהתם שר״ע הבליג על יסוריו הגופניים וקיים מצות ק״ש — והביאור כי התוכן של ק״ש הוא אחדות הוי׳, וזהו מה שר״ע קרא ק״ש גם שהיו סורקים בשרו כו׳ על שעסק בתורה, והיינו שגם בזה ראה והרגיש את אחדותו ית׳ [וע״ד שאמרו (חולין ז, ב) „אין עוד מלבדו . . ואפילו כשפים . . שמכחישין פמליא של מעלה”, שהכוונה בזה היא (לא רק שאינם סותרים לאחדות ה׳ לפי שקליפות הן „העדר”, אלא) שגם על ידם גופא (— מצד ניצוצות הקדושה שבהם) מתגלה אחדות ה׳. ועד״ז שאמרו (ילקו״ש נחמיי׳ רמז תתרעא. וראה גם יומא סט, ב) „הן הן גבורותיו”. וראה לקו״ת לג״פ מד, ג. (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560216\" data-slug=\"or-hatorah-hb\" data-id=\"8316560216\">אור התורה בראשית כרך ג׳ ע׳ תקעד</a>, ב) הגהות לתניא ע׳ פב (נדפסו ב„קיצורים והערות”). ד״ה למען דעת תשי״ג]. ועל זה אמרו לו תלמידיו „עד כאן” (בתמי׳) — איך שייך ענין האחדות במאורע זה — כששלט אדם בליעל דקליפה לסרוק בשרו כו׳, וענה ר״ע „כל ימי הייתי מצטער כו׳” ומכיון שהי׳ כל ימיו בתנועה דמס״נ — יציאה מהמיצר דעולם, לכן מציאות העולם הי׳ אצלו רק בבחי׳ „שמיעה” (כנ״ל סעיף ח׳), ופנימיות העולם ותכלית בריאתו ודבר ה׳ המהוה אותו היו אצלו בבחי׳ „ראי׳” — ולכן גם בה„לאו” ראה את ה„הן”, כבפנים. וועלט אינגאַנצן אָפּגעפרעגט, און איר גאנצע פאַראַנענקייט ווערט דערהערט (שומעין) נאָר מחמת די ראיות וואָס תורה גיט דערויף — דאַן איז פאַרשטאַנ־דיק, אַז אין יעדער מציאות ווערט געזען בלויז דער תוכן אירער וואָס צו טאָן מיט אַן ענין פון תורה ומצות. ובמילא, ווען מען שטויסט זיך אָן אויף אַ „לאו”, אויף אַ זאַך וואָס איז מנגד צו קדושה — ביז צו אַזאַ „לאו” ווי „אלקים אחרים”, די גרעסטע התנגדות צו אחדות השם — דערפילט מען אפילו אין דעם, ניט אַזוי דעם „לאו”, די שלעכטע זייט, נאָר בעיקר דעם „הן”, די גוטע זייט, דאָס וואָס דורך דעם מנגד קען מען מקיים זיין דעם אויבערשטנס ציווי „לא יהי׳ לך” — „על לאו הן”. אַט־די שיטה פון ר״ע לגבי די ענינים פון „לאו”, שפיגלט זיך אויך אָפּ אין דעם סיפור וואָס די גמרא 36 דערציילט: בשעת ר״ע מיט נאָך תנאים האָבן געזען ווי „שועל יוצא מבית קדשי הקדשים”, איז בעת די אַנדערע תנאים האָבן דערויף געוויינט צוליב דעם וואָס „מקום שכתוב בו והזר הקרב יומת ועכשיו שועלים הלכו בו” — האָט דאָן ר״ע „געקוואָלן”. און אויף דער שאלה פון די תנאים „מפני מה אתה מצחק”? האָט ר״ע זיי געענטפערט און מסביר געווען, אַז זעענדיק ווי עס ווערט מקויים נבואת אורי׳ וועגן דעם חורבן ירושלים און ביהמ״ק, ברענגט עס צו דערוואַרטן מיט אַ זיכערקייט דעם קיום הנבואה פון זכרי׳ „עוד ישבו זקנים וזקנות ברחובות ירושלים”. דאָס מיינט, אַז אויך אין אַזאַ מין „לאו”־ענין ווי „שועל יוצא מבית קדשי הקדשים”, האָט ר״ע געזען (ניט דעם „לאו” — די ניט־ ---"],["36","36","סוף מס׳ מכות."]]],[1300061138,"גוטע זייט דערפון, נאָר) דעם „הן”, ווי דאָס זאָגט עדות אויף קיום נבואת זכרי׳.\nיא. אַט־די צוויי שיטות און אופני עבודה — ר״י (עבודת הצדיקים) און ר״ע (עבודת התשובה) — זיינען שייך ביי אַזאַ אידן וואָס האַלט שוין באמצע העבודה. אבער ביי אַ „בן חמש (למקרא)” [אַפילו אויב אין יארן איז ער שוין אַ „דער־וואַקסענער”, נאָר אין עבודת ה׳ האַלט ער ערשט ביי דער מדריגה פון אַ „בן חמש”], וואָס ער דאַרף ערשט אָנהייבן דינען דעם אויבערשטן, — און אויך דאָס, אין אַן אופן פון חינוך —\nפון אים פאַדערט זיך ניט מער ווי דער פרט פון „רואין את הנשמע”, אַז ער זאל זיך מרגיל זיין אין דער עבודה פון דעם אָנהויב<sup data-n=\"37\">37</sup> (און הקדמה) פון אַלע חלקי שו״ע — תחלת סימן א׳ פון חלק א׳ (או״ח): — „שויתי הוי׳ לנגדי תמיד”, אַז די התאמתות אין אלקות („נשמע”) זאל ביי אים זיין אין אַן אופן פון ראי׳ — אלקות בפשיטות.\nאבער פאַדערן פון אים ער זאל האַלטן אויך ביי דער דרגא פון „שומעין את הנראה” — ער זאל ניט „זען” די עניני העולם, אַז די מציאות פון וועלט זאל ער נעמען בלויז בדרך „שמיעה”, „מציאות בהתחדשות” — קען מען ניט דערוויל — וואָרום, אפילו ווען ער פועל׳ט שוין ביי זיך אַז די ענינים הרוחניים זאלן ביי אים זיך אָפּלייגן בפשיטות, זיינען אבער דאָן אויך די ענינ־ים הגשמיים ביי אים נאָך אַלץ תופס מקום, און אויך אים — בפשיטות.\nאין איינפאַכע אותיות מיינט עס: ביים",[["37","37","וראה התחלת סידורו של אדמו״ר הזקן — שכידוע שסידרו שיהי׳ שווה לכל נפש — קודם ההקדמה ואפילו קודם אמי־רת „מודה אני”: „יתאמץ לקום כו׳ ומיד כו׳ ירגיל א״ע להתבונן מיד לפני מי כו׳”. „בן חמש” איז טאַקע פשוט אַז ער דאַרף לערנען תורה און מקיים זיין מצות, און אַט־די פשיטות איז ביי אים אַזוי פיל, אַז ער דאַרף זיך גאר ניט כופה זיין אויף דעם; אבער אויך די ענינים הגש־מיים ווי אכילה ושתי׳ וכדומה, זיינען גלייכצייטיק בפשיטות ביי אים. ער איז נאָך ניט בגדר צו פועל׳ן ביי זיך, אַז זיינע צרכים הגשמיים זאלן כלל ניט תופס מקום זיין און ער זאל זיי טאָן בלויז לשם שמים *37). --- *37) ועפי״ז יובן גם מ״ש * „לו חפץ ה׳ להמיתנו גו׳ ולא הראנו את כל אלה וכעת לא השמיענו כזאת” — דלכאורה, מפשטות הלשון „השמיע־נו”, וגם ממה שנאמר ל„לא לקח גו׳ (לא הי׳ מקבלם ברצון — מצודות שם) ולא הראנו גו׳”. משמע שההוכחה מ„כעת לא השמיענו כזאת” שלא חפץ ה׳ להמיתנו הוא לא לפי שהבשורה אינה יכולה להתקיים אם ימותו (כפירוש המצודות שם), כי אם, מצד הענין שה׳ „השמיענו” (ופירוש „כזאת” — הוא כדלהלן), שזה מראה שהם חביבים בעיני ה׳ ואינו חפץ להמיתם**. ולפי״ז אינו מובן: מהי גודל ההפלאה כ״כ ב„השמיענו” יותר מב„הראנו” (שלאחרי שאמ־רה „לא לקח גו׳ ולא הראנו גו׳” הוסיפה „וכעת לא השמיענו גו׳”), והרי ראי׳ נעלה יותר משמיעה — כי „הראנו את כל אלה” הו״ע ראיית אלקות (בדוגמת „רואין את הנשמע”) ו„השמיענו *) שופטים יג, כג. ולהעיר שפסוק זה הוא בהפטרה דש״פ נשא שבסמיכות (לאחריו או לפניו) לחגה״ש, זמן מ״ת. **) ויש לומר, שזהו ג״כ דיוק לשון רש״י שם „לא הי׳ משמיענו בשורה זו אם ראויים אנו למות” (ולא „אם נמות”), כי ההוכחה משמיעת הבשורה היא (לא מזה שאין הבשורה יכולה להתקיים באם ימותו, שהרי אפשר שמנוח ימות לאחרי שתעבר וגם אשתו תמות לאחרי שתלד, כי אם), שמזה שהשמיע להם בשורה זו, מוכח שהם חביבים בעיני ה׳ ואינם ראויים למות. וראה בשוה״ג שלאח״ז."]]],[1300061139,"און דעריבער איז אין פירוש רש״י על התורה — און ווי דערמאָנט כמה פעמים, האָט רש״י זיין פירוש גע־שריבן (צום אַלעם ערשטן) על דרך הפשט און אין אַן אופן אַז אויך אַ „בן חמש” זאל עס קענען פאַרשטיין — ווערט געבראַכט בלויז דער ענין „רואין את הנשמע” און ניט „שומעין את הנראה”, ווייל אין התחלת העבודה, זיינען סיי דער „נשמע” (רוחניות) און סיי דער „נראה” (גשמיות) אין אַן אופן פון ראי׳ — בפשיטות\n— און דאָס גופא איז אויך דער הסבר אויף דעם וואָס רש״י בפירושו לערנט, אַז דער אופן פון „לאמר” איז געווען „על לאו לאו” — היות אַז דאָ רעדט זיך בשייכות צו אַזאַ וואָס האַלט ערשט בתחלת העבודה, בשעת וועלט האָט נאָך ביי אים אַ תפיסת מקום, זעט ער נאָך אין „אלקים אחרים” (ווי אויך אין די אַנדערע דברים האסורים) דעם „לאו” וואָס אין זיי.\nיב. דאָס וואָס רש״י לערנט אַז דער ענטפער איז געווען אין דעם סדר פון „על הן הן ועל לאו לאו”, און אַז אידן האָבן דערגרייכט בלויז צו „רואין את",[["","","כזאת” הוא שעניני העולם, היו אצלם או בבחי׳ שמיעה (בדוגמת „שומעין את הנראה”). ועוד — שהיו „כזאת” (כמו „הראנו את כל אלה”), שכל מציאותם הוי מצד אלקות***. וזהו מה שהוסיפה ב„השמיענו כזאת” על „הראנו את כל אלה”, כי בחי׳ „שומעין את הנראה” היא נעלה יותר מבחי׳ „רואין את הנשמע”, כבפנים. ***) ויש לתווך זה עם הפירוש ש„השמיענו” הוא שמיעת הבשורה (ראה הערה (שבשוה״ג) הקודמת), שגם בשמיעת הבשורה „הנך הרה ויולדת בן”, עם היות שהו״ע גשמי, הייתה בזה ההדגשה „נזיר אלקים יהי׳ גו׳ והוא יחל להושיע את יש־ראל גו׳”. הנשמע” — ווייל דאָס רעדט זיך ביי התחלת העבודה — איז עס בהתאם ניט בלויז מיט דעת ר״ע כנ״ל (וואָס לשיטתו באַשטייט דער תכלית העילוי אין „שומ־עין את הנראה”, ובמילא — „על לאו הן”), נאָר אויך מתאים לדעת ר׳ ישמעאל: לפי שיטת רש״י, איז דער תכלית העי־לוי אין „שומעין את הנשמע”, אַז די המשכת אלקות מלמעלה למטה זאל דער־גרייכן ביז צום נידעריקסטן תחתון „שאין תחתון למטה ממנו” 38). ד.ה. אַז אלקות זאל נמשך און נתגלה ווערן ניט בלויז דאָרט וואו דער עולם פון וועלט איז אין אופן פון „רואין את הנראה” (וואו מציאות העולם איז בפשיטות הראי׳. און עס זעט זיך ניט אָן ווי אַט־די גאַנצע מציאות ווערט שטענדיק נתחדש פון איבער־שטען וואָס איז איר מהוה תמיד מאין ואפס המוחלט 39), נאָר אויך דאָרט וואו דער הסתר איז אַזוי גרויס אַז ס׳איז ניט מער ווי „שומעין את הנשמע” — אַזאַ ארט וואָס איז פול מיט קליפות וסט״א וועלכע זאָגן „אני ואפסי עוד” 40), אַז זייער מציאות דריקט אויס דעם היפך, ח״ו ר״ל, פון אחדות ומציאות הבורא, און מען דאַרף דאָרט אַנקומען צו שכל׳־דיקע הוכחות (בבחינת „שומעין”) אויף מציאות האלקות („נשמע”), ---"],["38","38","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל״ו</a>. וראה לעיל ע׳ 17 ואילך."],["39","39","שער היחוד והאמונה בתחלתו."],["40","40","תניא שם. ויש לומר, שזהו מה שמוסיף בתניא שם „עד שהוא מלא קליפות וסט״א . . אני ואפסי עוד” — על מ״ש לפנ״ז „שאין תחתון למטה ממנו בענין הסתר אורו ית׳ והחשך כפול ומכופל”, כי ההסתר והחשך שבעוה״ז מצד עצמו הוא — שאין נרגש בו שהת־הוותו הוא מאלקות; אבל גם אינו מנגד כו׳. וע״ז מוסיף אח״כ „עד שהוא מלא קליפות וסט״א שהן נגד ה׳ ממש לומר אני ואפסי עוד”."]]],[1300061140,"איז דאָס אַלץ געזאָגט געווארן בשייכ־כות צו אַ אידן וואָס האַלט שוין דערביי, ער זאל קענען — מצד מדריגת „צדיק” שבו — פועל זיין המשכת אלקות אויך אין אַזאַ תחתון וואָס אלקות איז ביי אים באופן דשמיעה. בעת ער איז אבער ערשט אַ „בן חמש”, אין דער דרגא פון חינוך, איז ער ניט שייך צו דער דרגת העבודה אין דעם ארט און ענין וואָס דארט איז „שומעין את הנשמע”, דאָס איז נאָך דערווייל ניט לפי כחו — דאָס וועט אים שטערן צו לימוד התורה וקיום המצות. ביי אים דאַרף זיין דערווייל דער אופן פון „רואין את הנשמע”, אַז די ענינים פון אלקות זאלן ביי אים זיין בפשיטות.\nיג. המורם מכל האמור, אַז דער אופן העבודה ווו ס׳איז אַנגעוויזן אין פירש״י עה״ת — אַז די ענינים פון אלקות דאַרפן זיין בפשיטות „רואין את הנשמע”, בעת אויך די עניני העולם האָבן נאָך אַ תפיסת מקום, און דערפאַר: „על לאו לאו” — איז בלויז בתחלת העבודה. אבער נאָך דעם דאַרף מען שטייגן און צוקומען צו איינעם פון די צוויי אופני עבודה — צו דער עבודה פון המשכת אלקות למטה ביז צו דעם מטה וואָס ער איז בדרגת „שומעין את",[["","","נשמע”; אדער צו דער עבודה פון העלאה מלמטה למעלה, אַרויסהויבן (זיך און) די וועלט פון די טבע־גדרים, ביז (אַז ניט בלויז איז זי מער ניט מסתיר אויף אלקות און אדרבה: רואין את ה־נשמע, נאָר אויך) אַז די וועלט זעט זיך כלל ניט אָן ווי אַ מציאות לעצמה — „שומעין את הנראה” און „על לאו הן”. און ווייבאַלד אַז ביידע שיטות — שיטת ר״ע און שיטת ר״י — זיינען חלקים פון תורה (שבעל פה), וואָס זי איז אַ הוראה לכל אחד ואחד מישראל, דאַרפן דעריבער ביי יעדן אַט־די ביידע אופני עבודה: המשכה מלמעלה למטה און העלאה מלמטה למעלה, וואָס דאָס איז אַ הכנה און אַ כלי צום קיום היעוד „ושמתי כדכד שמשותיך — להיי כדין וכדין” 41), וואָס וועט זיך אויספירן אין דער גאולה האמיתית והש־שלימה, דורך משיח צדקנו, בקרוב ממש. (משיחות חגה״ש וש״פ נשא תשכ״ו) ---"],["41","41","ישעי׳ נד, יב. ב״ב עה, א. ובלקו״ת פ׳ ראה בהדרושים ד״ה ושמתי כדכד (ראה ד״ה תקעו תרס״א — לענין צדיקים ובע״ת) — שזהו ב׳ הקוין דהמשכה והעלאה. עיי״ש."]]],[1300061141,"<h3>משפטים</h3>\nא. אין היינטיקער סדרה, אין פיר באַזונדערע ערטער, זאָגט רש״י אַ כלל: „דיבר הכתוב בהוה״¹. דעם ערשטן מאָל זאָגט ער דעם כלל אין פסוק „וכי יגח שור״²: „אחד שור ואחד כל בהמה וחי׳ ועוף אלא שדיבר הכתוב בהוה״, און דערנאָך זאָגט ער עס אין נאָך דריי ווייטערדיקע פסוקים, כדלקמן סעיף ג׳.\nדאַרף מען פאַרשטיין: אויב פאַר דעם פסוק „וכי יגח שור״ און אין דער זעלבער³ סדרה זיינען דאָ פסוקים וואו מען דאַרף לערנען, לכאורה, אַז דער פסוק ברענגט די באַטרעפנדע דוגמא [ניט דערפאַר וואָס דער דין פון דעם פסוק איז דוקא ביים דערמאָנטן אופן, נאָר] מחמת דעם וואָס „דיבר הכתוב בהוה״ —\nלמשל, אין פסוק „וכי יכה איש את עבדו גו׳ בשבט גו׳״⁴, וואָס דער דין פון „נקום ינקם, אך אם יום או יומים יעמוד לא יוקם גו׳״⁵ איז (אין פשטות⁶) אויך ווען ער שלאָגט דעם עבד ניט דוקא מיט אַ שבט, נאָר מיט עפּעס אַנדערש⁷, און דער וואָרט „בשבט״ אין פסוק איז בלויז מחמת דעם וואָס „דבר הכתוב בהוה״;\nדאָס זעלבע געפינט מען אין נאָך אַ פריערדיקן פסוק: „וכי יריבון אנשים והכה איש את רעהו גו׳״⁸ — וואָס דאָרט איז דאָך אודאי נוגע נאָר דער ענין אַז „והכה איש את רעהו״, און די גאַנצע הקדמה „וכי יריבון אנשים״ קומט בלויז ווייל „דיבר הכתוב בהוה״ —\nאיז ניט מובן: פאַרוואָס וואָרט רש״י מיט זיין פירוש „דיבר הכתוב בהוה״ ביז צום פסוק „וכי יגח שור״, און ער זאָגט עס ניט גלייך ביים ערשטן מאָל (עכ״פ — פון דער סדרה)?\nאויך דאַרף מען פאַרשטיין פאַרוואָס חזר׳ט רש״י איבער דעם זעלבן כלל פיר מאָל ובסמיכות מקום זה לזה (וכדלקמן באריכות)?\nב. דער מקור פון אָט דעם כלל איז לכאורה גענומען פון דער משנה⁹: „אחד שור ואחד כל בהמה . . וכן חי׳",[["1","1","וכ״ה בפרש״י ראה יג, ז. טו, יט. תצא כג, יא. כה, ד."],["2","2","כא, כח."],["3","3","ועד״ז בסדרות שלפני זה ולדוגמא ביתרו: יט, יג. בבשלח טו, כג. וכו׳."],["4","4","כא, כ."],["5","5","שם, כ־כא."],["6","6","ברמב״ם הל׳ רוצח פ״ב הי״ד: לכך נאמר בשבט, שלא נתנה תורה רשות להכותו אלא בשבט ומקל ורצועה וכיוצא בהן. וראה אוה״ת כאן. אבל: (א) בפרש״י לא נזכר זה כלל. (ב) גם לפ״ז צ״ל שהלשון „בשבט״ הוא מחמת „דבר הכתוב בהוה״, שהרי השלילה ד״הכאת רציחה״ (שברמב״ם שם), הוא גם ב„מקל ורצועה וכיו״ב״."],["7","7","ואדרבה: אלולא הטעם „דבר הכתוב בהוה״, הי׳ צ״ל נאמר (ע״ד הפשט) דוקא דוגמא אחרת, כי תיבת „שבט״ כוללת גם שבט שאין בו כדי להמית (משא״כ „כלי ברזל״ — ראה פרש״י מטות לה, טז), והדין שנאמר בכתוב הוא דוקא כשהכהו בדבר שיש בו כדי להמית (ראה רש״י עה״פ)."],["8","8","כא, יח."],["9","9","ב״ק נג, ב. ובפרש״י סנה׳ ב, א ד״ה הזאב, הובאה משנה זו לענין „וכי יגח שור״. ועיין בתוי״ט סנה׳ פ״א מ״ד. (ולהעיר מטור חו״מ רסשפ״ט ובדרישה שם). ואכ״מ."]]],[1300061142,"ועוף כיוצא בהן, א״כ למה נאמר שור או חמור אלא שדיבר הכתוב בהוה״.\nאָבער בנוגע די אַלע פסוקים וואָס די משנה איז מפרש — אַז דער פרט וואָס שטייט אין פסוק („שור״ וכיו״ב) איז בלויז מחמת „דיבר הכתוב בהוה״ — ברענגט די גמרא¹⁰ הוכחות וראיות צו באַווייזן אַז די דינים זיינען ניט דוקא ביים פרט המפורש בכתוב:\nמשא״כ רש״י זאָגט עס ווי אַ כלל אַז „דיבר הכתוב בהוה״, און ער ברענגט ניט דערביי קיין שום ראי׳ אַז אַזוי איז דער דין אויך ביי אַנדערע פרטים. ולדוגמא, ביי „וכי יגח שור״ ברענגט רש״י ניט קיין באַווייז אַז „שור״ לאו דוקא¹¹. און אַזוי אויך אין די אַנדערע פסוקים זאָגט רש״י דעם כלל, ניט אָנגעבנדיק דערצו קיין הוכחה¹².\nדי שוועריקייט ווערט נאָך גרעסער: מיט עטלעכע פסוקים ווייטער¹³ — ביי „ונפל שמה שור או חמור״, וואָס אויך דאָרט איז רש״י מפרש אַז „הוא הדין לכל בהמה וחי׳״, ברענגט ער יאָ אַ הוכחה דערצו „שבכל מקום שנאמר שור וחמור אנו למדין אותו שור שור משבת כו׳״.\nולכאורה: אַז שור וחמור זאָלן אַריינפאַלן אין בור איז דאָך מער מצוי ווי „כל בהמה וחי׳״ — ווי ער זאָגט דאָרט אין משנה, אַז דער טעם וואָס ס׳שטייט „שור או חמור״ ביי „נפילת הבור״ איז עס מחמת „דיבר הכתוב בהוה״ (און אין אַ „מציאות״ — הוה — איז דאָך ניט שייך צו מחלק זיין צווישן דרך הפשט און דרך ההלכה וכו׳) — היינט וויבאַלד אַז רש״י נעמט אָן דעם ענין פון „דיבר הכתוב בהוה״ ווי אַ כלל, צוליב וואָס דאַרף ער אָנקומען צום לימוד „שור שור משבת״?\nאפילו את״ל אַז ביי נפילה בבור איז דאָ אַ סברא צו זאָגן אַז „בעל הבור ישלם״ איז דוקא ווען „ונפל שמה שור או חמור״, וואָרום דערפאַר גופא וואָס זייער אַריינפאַלן אין אַ בור איז מער מצוי, איז די כריית אָדער פתיחת הבור לגבי זיי דוקא אַ פשיעה¹⁴; און דעריבער דאַרף דאָ רש״י אָנקומען צום לימוד „שור שור משבת״, ווייל, כמובן, איז דער כלל „דיבר הכתוב בהוה״ נאָר אין אַ פאַל וואו ס׳איז ניטאָ קיין סברא צו אָפּטיילן צווישן דעם פרט שבכתוב און אַנדערע פרטים¹⁵",[["10","10","ב״ק שם. וברש״י ברכות כז, א ד״ה שנסקל, דגמרינן בגז״ש שור שור משבת לענין השור יסקל. בתוי״ט שם, דליכא למגמר משבת אלא תלת. אבל ראה מכילתא כאן. ב״ת בחו״מ שם. ואכ״מ."],["11","11","בש״ח כאן (וראה גם רא״ם וגו״א כאן): „ילפינן שור שור משבת כו׳ ש־פרש״י על פסוק (כא, לג) שור או חמור״. אבל בלאה״כ בפשטות, אין מקום לומר שרש״י יסמוך א״ע על מ״ש לאחרי זה."],["12","12","ראה לקמן הערות 17, 22."],["13","13","כא, לג."],["14","14","ואף שכריית הבור היא פשיעה (לענין שור וחמור), מ״מ אפשר לומר שיהי׳ פטור על נפילת בהמה אחרת. ולהעיר מב״ק נב, סע״א ואילך."],["15","15","ושני ענינים בזה: א) מכיון שיש סברא לחלק בין הדוגמא שנאמרה בכתוב לדוגמאות אחרות, א״א לחדש (בלי שום הוכחה) שהדין שנאמר בכתוב הוא גם בדוגמאות אחרות ושה־דוגמא באה בכתוב רק מחמת זה שדבר הכתוב בהוה (משא״כ כשאין סברא לחלק, דוחק לומר שזהו גזה״כ). ב) (יתירה מזו:) באם הדין שבכתוב הי׳ גם בדוגמאות אחרות, לא הי׳ נאמר בכתוב דוגמא כזו שיש בה סברא שבאה בדוקא — רק מצד זה שהיא רגילה יותר — מכיון שעפ״ז יש מקום לטעות (וראה"]]],[1300061143,"— איז אָבער ניט מובן, וואָס לאחרי ווי רש״י ברענגט שוין אַ ראי׳ אַז „הוא הדין לכל בהמה וחי׳״, איז ער מסיים „ולא נאמר שור וחמור אלא שור ולא אדם חמור ולא כלים״. דלכאורה דאַרף מען לערנען (ע״ד הפשט, וואָס דאָס איז דרך רש״י עה״ת) — „ולא נאמר שור או חמור — אלא מפני שדיבר הכתוב בהוה״ — איז פון וואַנעט נעמט מען אַז דאָס קומט צו ממעט זיין אדם וכלים?\nג. דעם כלל „דבר הכתוב בהוה״, זאָגט רש״י, כנ״ל, נאָך דריי מאָל אין אונדזער סדרה:\nביי „מכשפה לא תחי׳״¹⁶ איז רש״י מפרש: „אחד זכרים ואחד נקבות¹⁷ אלא שדיבר הכתוב בהוה, שהנשים מצויות מכשפות״¹⁸; נאָך אַ מאָל זאָגט עס רש״י ווייטער אויפן פסוק „כל אלמנה ויתום לא תענון״¹⁹: „הוא הדין לכל אדם אלא שדבר הכתוב בהוה לפי שהם תשושי כח ודבר מצוי²⁰ לענותם״; און דערנאָך, ביים פסוק „ובשר בשדה טריפה״²¹, זאָגט ער ווידעראַמאָל: „אף בבית כן אלא שדבר הכתוב בהוה מקום שדרך בהמות ליטרף״²².",[["","","אוה״ח קדושים יט, יט: כי לא ידבר בהוה מקום שיש לטעות). וא״כ ה״ז זה עצמו מוכיח שהדין הוא דוקא בדוגמא זו."],["16","16","כב, יז."],["17","17","בפרש״י לסנה׳ סז, א: „דהא גבי אוב וידעוני דמכשפים הם לא חלק בין איש לאשה דכתיב איש או אשה״. אבל, מזה שבפירושו עה״ת אינו מביא הוכחה זו [ובפרט שהתלמיד לא למד עדיין הפסוק שנאמר גבי אוב וידעוני], מוכח שראייתו ל„אחד זכרים ואחד נקבות״ ע״פ דרך ה־פשט היא מפסוק זה עצמו (ודלא כבש״ח כאן). כי מכיון שאין סברא לומר שהדין „לא תחי׳״ [שפירושו הוא „תומת בב״ד״ *)] הוא רק במכשפה ולא במכשף, צ״ל שזה שנאמר מכשפה הוא לפי שדבר הכתוב בה־וה, כנ״ל ס״ב והערה 15. *) עפ״ז אפשר לבאר גם ההמשך בר־ש״י „אחד זכרים כו׳״ ל„אלא תומת בב״ד״, ששני הענינים כתבם בדיבור א׳, ועד שכותב „ואחד זכרים כו׳״ — בוא״ו המוסיף: באנשים יש סברא לומר שעונשם חמור יותר (שלכן הוצרך הכתוב להשוות אשה לאיש לכל עונשין וכו׳ שבתורה (קידושין לה, א (עיי״ש). וש״נ). והאשה ה״ה עזר כנגדו (בראשית ב, כ) ונאמר בה: והוא ימשל בך (שם ג, טז), וראה גם רש״י"],["18","18","כ״ה גם בסנה׳ שם. אלא ששם ליתא „דבר הכתוב בהוה״. וראה לקמן הערה 34. עוד שינוי בפרש״י לגבי לשון הגמרא שם: בסנה׳ שם „שרוב נשים כו׳״ ורש״י משמיט תיבת „רוב״ — כי ע״ד הפשט והמציאות הנראה לעין בשר — אין רוב נשים כו׳, ובפרט שהכתוב מדבר במכשפה בפועל. — ובש״ס יל״פ שהעונש ימנעם מעשי׳ בפועל. יותר נ״ל שהוא ע״ד הביאור בפרש״י בנוגע לדם (ראה יב, כג. כה) שהביא ב׳ דעות הפוכות במציאות „שטופים״ „קצה״. עיי״ש (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141047\" data-slug=\"likkutei-sichot\" data-id=\"1300141047\">לקו״ש חי״ד ע׳ 47</a> ואילך)."],["19","19","כב, כא."],["20","20","ראה גם מכילתא כאן (בדברי ר״ע). וראה גו״א לפרש״י כאן."],["21","21","כב, ל."],["22","22","מכילתא עה״פ. ושם ילפינן ש״ה״ה בבית״ מהיקש. אבל ממה שרש״י אינו לעיל כא, טז: אין לי אלא איש . . אשה . . מנין). ולכן באם פי׳ „לא תחי׳״ הי׳ (רק) שלא להחיותה (היינו לא לספק לה מים ומזון — ראה רש״י לעיל (שמות א, יז) בפירוש ותחיין) לא הי׳ קשה להתלמיד מה שנאמר „מכשפה״ (ל׳ נקבה), כי הי׳ אומר, אולי יבוא לאח״ז פסוק במכשף שעונשו גדול יותר — מיתה בב״ד. אבל לאחרי שרש״י מפרש „אלא תומת בב״ד״, מקשה התלמיד בפשטות: מדוע רק מכשפה מחוייבת מיתה ולא מכשף — והרי אדרבה: אנשים צ״ל עונשם חמור יותר? — ולכן ממשיך רש״י „ואחד זכרים כו׳״."]]],[1300061144,"איז אין דעם ניט מובן: צוליב וואָס דאַרף רש״י זאָגן דעם זעלבן כלל פיר מאָל; ביי די אַנדערע דריי פסוקים קען מען דאָך דאָס לכאורה שוין וויסן פון רש״י׳ס פירוש אין „וכי יגח שור״?²³\nבנוגע צו „מכשפה לא תחי׳״ קען מען פאַרענטפערן, אַז דער „בן חמש (למקרא)״ האָט ניט צו טאָן מיט כישוף²⁴ און ער וויס ניט אַז ביי נשים איז מער מצוי כישוף ווי ביי אנשים, קען ער במילא אַ טעות האָבן און מיינען אַז דער דין פון „לא תחי׳״ איז דוקא ביי אַ מכשפה, ניט ביי אַ מכשף. דאַרף דעריבער רש״י מחדש זיין, אַז אין פסוק שטייט „מכשפה״ בלויז ווייל „דבר הכתוב בהוה, שהנשים מצויות מכשפות״²⁵.\nאָבער ביי „כל אלמנה ויתום לא תענון״ און „ובשר בשדה טריפה״ וויס דאָך לכאורה דער תלמיד אַז די דוגמאות וואָס דער פסוק שרייבט זיינען מער מצוי — היינט פאַרוואָס זאָל ער אַ טעות האָבן און מיינען אַז „לא תענון״ איז דוקא ביי „אלמנה ויתום״ און „לא תאכלו״ איז דוקא ביי בשר הנטרף „בשדה״, ביז אַז רש״י דאַרף מחדש זיין אַז „הוא הדין לכל אדם״ און „אף בבית כן״?\nד. די תמי׳ איז נאָך גרעסער: ווען רש״י איז מפרש (צום פערטן מאָל —) אין פסוק „ובשר בשדה טרפה״, אַז די דוגמא „בשדה״ קומט מחמת „דבר הכתוב בהוה״, זאָגט ער אין דעם אַן אריכות „וכן כו׳ וכן כו׳״ — און מען געפינט אין נאָך ערטער וואו „דבר הכתוב בהוה״ (כדלקמן ס״ה), צו באַווייזן אַז דאָס איז ניט קיין ענין פון „לא מצאתי לו חבר״; און דערנאָך ברענגט ער ערשט אַ צווייטן פירוש: „ואונקלוס תרגם כו׳״, אַז דער וואָרט „בשדה״ איז בדוקא און ניט מחמת „דבר הכתוב בהוה״.\nוואָס דאָס איז אינגאַנצן ניט פאַרשטאַנדיק: מיט וואָס איז דער „דבר הכתוב בהוה״ אין פסוק „ובשר בשדה טרפה״ שווערער ווי אין די אַלע פריערדיקע פסוקים, ביז אַז מצד דעם: א) דאַרף רש״י דאָ ברענגען ראיות דערצו (כאָטש אין די פריערדיקע פסוקים נעמט ער עס אָן פאַר אַ גלאַטן פירוש וכלל וועלכער פאַדערט ניט קיין הוכחות), און — ב) אויך נאָך",[["","","מביא ההיקש, מוכח שבדרך הפשט כן הוא מצד הסברא — ראה לעיל ס״ב."],["23","23","יתירה מזה: מהו הטעם שבכל פסוקים אלו משנה רש״י ממקום אחד לחבירו: א) בב׳ פסוקים הראשונים — „אחד כו׳ ואחד כו׳״; ב„כל אלמנה ויתום״ (ו„במקרה לילה״ — שבפרש״י עה״פ ובשר גו׳) — „הוא הדין כו׳״; ב„ובשר בשדה טרפה״ — „אף [בבית] כן״. (ומשנה תומ״ר בראיתו ע״ז מ„מקרה לילה״ — „הוא הדין״, כנ״ל). ב) ב„וכי יגח שור״ כותב רק ש„דבר הכתוב בהוה״ (ואינו מוסיף ש„דרך לנגח״ וכיו״ב), ואילו בג׳ המקומות שלאח״ז מבאר איך שהדוגמא שבכתוב הוא „הוה״ *). וגם בג׳ מקומות אלו גופא — ב„כל אלמנה ויתום״ משנה מ„מכשפה״ ומ„ובשר בשדה טרפה״: (א) מוסיף „לפי״. (ב) מבאר גם הטעם לזה ש„דבר מצוי לענותם״ — „תשושי כח״."],["24","24","ולהעיר מפרש״י שופטים יח, ט."],["25","25","אבל — דוחק, כי לפ״ז הי׳ מספיק שיכתוב רק „שהנשים מצויות מכשפות״ (כבסנה׳ שם). ומזה שמוסיף „שדבר הכתוב בהוה״ (אף שפירש זה כבר לעיל כא, כח), משמע שהחידוש כאן הוא [לא רק הכישוף בנשים הוא „הוה״, אלא גם] עצם הענין של „דבר הכתוב בהוה״, כדלקמן הערה 34. *) בנוגע ל„מכשפה״ — י״ל לכאורה, שזהו לפי שהתלמיד אינו יודע בעניני כישוף, כדלקמן בפנים. אבל דוחק, כי בשביל זה מספיק מה שרש״י כותב „שדבר הכתוב בהוה״."]]],[1300061145,"די ראיות, דאַרף ער דאָ ערשט אָנקומען צו אַ צווייטן פירוש?!\nה. די ראיות (אין פסוק „ובשר בשדה טרפה״) וועלכע רש״י ברענגט צום פירוש „דבר הכתוב בהוה״, זיינען פון צוויי פסוקים אין פ׳ תצא: (א) „כי בשדה מצאה״²⁶ — וואָס דער זעלבער דין איז אויך אין יעדן אָרט וואו „אין מושיע לה״²⁷, און דער פסוק זאָגט „בשדה״ ווייל „דבר הכתוב בהוה״; און (ב) „אשר לא יהי׳ טהור מקרה לילה״²⁸ — „הוא הדין למקרה יום אלא שדבר הכתוב בהוה״.\nבפשטות מוז מען זאָגן, אַז דאָס וואָס רש״י דאַרף אָנקומען צו פסוקים וואָס שטייען שפּעטער אין פ׳ תצא און ער ברענגט ניט קיין ראי׳ פון די פריערדיקע פסוקים הנ״ל אין אונדזער סדרה גופא (און אויך ניט פון כמה וכמה שפּעטערדיקע פסוקים וואָס פאַר „כי בשדה מצאה״²⁹), איז עס דערפאַר וואָס דער פירוש „דבר הכתוב בהוה״ אין דעם פסוק איז (מצד איזה טעם) אַנדערש און שווערער ווי דער פירוש אין רוב ערטער (כנ״ל ס״ד), און דעריבער מוז רש״י ברענגען די פסוקים „כי בשדה מצאה״ און „אשר לא יהי׳ טהור מקרה לילה״, וואו דער „דבר הכתוב בהוה״ איז יע בדומה צום „דבר הכתוב בהוה״ פון אונדזער פסוק.\nס׳איז אָבער ניט מובן:\nא) וויבאַלד אַז דער „דבר הכתוב בהוה״ וואָס אין די צוויי פסוקים שבפ׳ תצא איז יע ענלעך צום „דבר הכתוב בהוה״ פון „ובשר בשדה טרפה״ — פאַרוואָס דאַרף רש״י ברענגען ביידע פסוקים, און באַגנוגנט זיך ניט מיט בלויז איינעם פון זיי?\nב) אויב דער „דבר הכתוב בהוה״ ביי „ובשר בשדה טרפה״ האָט צו זיך אַ „חבר״ אין נאָך צוויי ערטער, מצד איזה טעם דאַרף רש״י אָנקומען צו „ואונקלוס תרגם״?\nו. לכאורה האָט מען געקענט מסביר זיין די שוועריקייט פון „דבר הכתוב בהוה״ אין פסוק „ובשר בשדה טרפה״, לגבי דעם זעלבן פירוש אין די פריערדיקע דריי פסוקים:\nאין פסוק „וכי יגח שור״, איז דורכן געבן די דוגמא המצוי׳ — שור — ווערט ניט צוגעלייגט קיין שום איבעריקער וואָרט: דער פסוק קען דאָך ניט זאָגן „וכי יגח״ סתם — ניט אָנגעבנדיק דערבי׳ ווער עס האָט געשטויסן³⁰ — און וויבאַלד אַזוי, דערמאָנט ער שוין „שור״, ווייל ביי אים איז מער מצוי דער ענין פון נגיחה.\nדאָס זעלבע איז אין פסוק „מכשפה לא תחי׳״: דער פסוק מוז דאָך אָנשטעלן אַ באַשטימטן וואָרט — מכשף",[["26","26","כב, כז."],["27","27","וכבמכילתא כאן ובספרי שם. ברמב״ם הל׳ נערה בתולה פ״א ה״ב: „כל הנבעלת בשדה הרי זו בחזקת אנוסה . . וכל הנבעלת בעיר הרי זו בחזקת מפותה״. ולפ״ז הי׳ אפשר לפרש, שמ״ש „כי בשדה מצאה״ הוא בדוקא. אבל בפשטות, עיקר החילוק הוא רק אם הי׳ זה במקום שיש לה מושיע או במקום שאין לה מושיע, וכבספרי שם. (ונראה שגם „שדה״ ו„עיר״ שברמב״ם שם הוא רק לדוגמא, לפי שע״פ רוב, שדה הוא מקום שאין לה מושיעים, משא״כ עיר (ונקט לישני׳ דקרא) דזיל בתר טעמא). וראה רמב״ן עה״ת תצא שם."],["28","28","כג, יא."],["29","29","ואפילו לא מ„ואם בשדה ימצא״ שבתחלת פרשה זו עצמה (תצא כב, כה). וראה לקמן הערה 44."],["30","30","ובפרט שהדין „סקול יסקל״ הוא על הנוגח, וראה לקמן סעיף ז׳."]]],[1300061146,"אָדער מכשפה — קלייבט ער דעריבער אויס דעם וואָרט „מכשפה״ (לשון נקבה) ווייל „הנשים מצויות מכשפות״.\nאון אַזוי אויך ביי „כל אלמנה ויתום לא תענון״, וואָס מיטן ביישפּיל „אלמנה ויתום״ ווערט דאָ ניט צוגעגעבן קיין איבעריקער אויסשפּראַך אין פסוק, וואָרום עס מוז דאָך דאָ עפּעס קומען בהמשך צו „לא תענון״.\nמשא״כ אין פסוק „ובשר בשדה טרפה״ — ווען ניט דער כלל „דבר הכתוב בהוה״ וואָלט געשטאַנען בלויז „ובשר טרפה (לא תאכלו)״, ובמילא איז שווער צו זאָגן אַז תורה זאָל צוגעבן אַן איבעריקן וואָרט מצד דעם כלל דבר הכתוב בהוה, אַז שדה איז „מקום שדרך בהמות ליטרף״. מוז דעריבער רש״י אָנקומען צו אַ הוכחה אַז מצד דעם כלל „דבר הכתוב בהוה״ איז שייך אויך אַז תורה זאָל שרייבן אַן איבעריקן וואָרט.\nאון דערפאַר ברענגט רש״י אַ ראי׳ דערצו פון „כי בשדה מצאה״ און „אשר לא יהי׳ טהור מקרה לילה״, וואָס אויך דאָרט קומען די דוגמאות פון „בשדה״ און „מקרה לילה״ דורך אי־בעריקע ווערטער (ראה לקמן סי״ב וי״ג).\nאָבער לויט דעם ביאור ווערט נאָך שטאַרקער די קשיא (דלעיל ס״א) פון די פסוקים „וכי יכה גו׳ בשבט גו׳״ און „וכי יריבון אנשים גו׳״; אויך דער וואָרט „בשבט״ איז לכאורה איבעריק³¹, און עאכו״כ אַז די ווערטער „וכי יריבון אנשים״ זיינען איבעריק, איז ווי קומט עס, אַז דאָרט נעמט אָן רש״י דעם כלל „דבר הכתוב בהוה״ פאַר אַזאַ דבר הפשוט וואָס ער דאַרף גאָרניט מפרש זיין;\nאון אין פסוק „ובשר בשדה טרפה״ נעמט ער עס אָן פאַר אַזאַ שווערן פירוש, אַז ער מוז דערצו ברענגען הוכחות, און ערשט נאָך די הוכחות דאַרף ער אָנקומען צו אַ צווייטן פירוש?\nאפילו אויב מען זאָל איינלערנען, אַז די ווערטער „וכי יריבון אנשים״ און „בשבט״ שטייען צוליב וועלכן ט׳איז אַנדערן טעם, און ניט מחמת „דבר הכתוב בהוה״ (און אויך אין אַלע אַנדערע פסוקים וואו עס קוקט אויס צו זיין אַ קרא יתירא מחמת דבר הכתוב בהוה, וועט מען דערצו געפינען אַן אַנדער טעם) — איז אָבער אין פסוק „כי יסיתך גו׳ בסתר לאמר״³² זאָגט רש״י גופא: „בסתר — דבר הכתוב בהוה כו׳״ — און ס׳איז מובן, אַז ווען ניט „דבר הכתוב בהוה״ וואָלט דאָרטן ניט געשטאַנען קיין אַנדער וואָרט. האָט דאָך רש״י (ביי „ובשר בשדה טרפה״) געדאַרפט ברענגען אַ ראי׳ פון „כי יסיתך גו׳ בסתר״ וואָס שטייט פאַר דעם פסוק „כי בשדה מצאה״?\nז. דער ביאור בכל זה:\nבשעת דער פסוק זאָגט אַ געוויסן דין אין אַן אופן פון „סיפור דברים להבא״, אַז אויב עס וועט פּאַסירן אַזוי און אַזוי זאָל זיין דער דין כך וכך, דאַן לייגט זיך צו זאָגן, אַז די פרטים וועלכע דער פסוק שרייבט אין דעם סיפור, ווערן זיי געבראַכט בכדי צו אויסמאָלן דעם מאורע אין דעם אופן היותר רגיל, הוה.\nאַנדערש איז אָבער ווען דער פסוק זאָגט אַ געוויסן פרט אין דעם דין — דאַן איז שוין מער סברא צו זאָגן, אַז דער דאָזיקער פרט איז בדוקא.",[["31","31","ראה לעיל הערה 6."],["32","32","ראה יג, ז."]]],[1300061147,"און דעריבער: אין פסוק „וכי יריבון אנשים וגו׳״ דאַרף רש״י ניט באַוואָרענען אַז דער זעלבער דין פון „והכה גו׳ ונקה גו׳ רק גו׳״ איז אויך אַן „וכי יריבון״ — וואָרום היות אַז דער פרט „וכי יריבון״ איז אַ פרט אין דעם סיפור (און נאָר אין דעם סיפור), איז פאַרשטאַנדיק (אויך ווען רש״י איז עס ניט מפרש) אַז דאָס איז בלויז בכדי צו אויסמאָלן דעם מאורע אין אַן אופן הרגיל.\nאַזוי אויך אין פסוק „וכי יכה גו׳ בשבט״ דאַרף רש״י ניט באַוואָרענען אַז דער זעלבער דין איז אויך ווען דער שלאָגן איז ניט בשבט, נאָר מיט עפּעס אַנדערש — היות אַז דער „בשבט״ איז אַ חלק פון דער באַשרייבונג פון דער פּאַסירונג (און נאָר פון דער פּאַסירונג).\nבעת עס קומט אָבער צו „וכי יגח שור״, וואָס דער דין האמור אין יענעם פסוק [ניט בלויז נוגע צום בעל השור, נאָר אויך (און בעיקר)] נוגע דעם שור גופא — „סקול יסקל השור גו׳״, קומט דאָך במילא אויס, אַז דער פרט „שור״ (הגם ס׳איז אין אַ סגנון פון „סיפור״) איז אַ פרט (אויך) אין דעם דין גופא, וכאילו ווי עס וואָלט געשטאַנען אין פסוק אַז אַ שור וואָס האָט געשטויסן כו׳ דינו סקילה — קען דאָרט שוין זיין אַ סברא אַז דער פסוק זאָגט דעם דין דוקא ביי אַ שור הנוגח, און ניט ביי אַן אַנדער בעל חי, דעריבער דאַרף דאָרט רש״י באַוואָרענען „אחד שור ואחד כל בהמה וחי׳ ועוף אלא שדיבר הכתוב בהוה״.\nח. ע״פ הנ״ל ווערט מען אויך פאַרשטיין דעם טעם וואָס אין פסוק „מכשפה לא תחי׳״ זאָגט רש״י נאָכאַמאָל דעם כלל „דבר הכתוב בהוה״ און פאַרלאָזט זיך ניט אויף דעם וואָס ער האָט עס שוין געזאָגט פריער אין פסוק „וכי יגח שור״³³:\nווען רש״י וואָלט געזאָגט דעם כלל „דבר הכתוב בהוה״ בלויז ביי „וכי יגח שור״, וואָלט מען געקענט מיינען, אַז דאָס איז דערפאַר וואָס אין יענעם פסוק רעדט זיך עכ״פ אין אַ סגנון של סיפור (הגם אַז דער פרט „שור״ איז נוגע אויך צום דין גופא). משא״כ אין פסוק „מכשפה לא תחי׳״, וויבאַלד אַז דאָ איז ניטאָ בכלל קיין סיפור המאורע, דאָ איז נאָר הודעת הדין אַז „מכשפה לא תחי׳״ — האָט מען געקענט לערנען אַז דער דין איז דוקא ביי מכשפה —\nדעריבער זאָגט רש״י „אחד זכרים ואחד נקבות אלא שדיבר הכתוב בה־הוה³⁴, שהנשים מצויות מכשפות״.",[["33","33","גם י״ל: דרך הכתובים בכל מקום [כשמדברים בענין שזכר ונקבה שוים בו] לכתוב בלשון זכר. ולכן הי׳ סברא לומר, שמחמת „דבר הכתוב בהוה״ לא הי׳ הפסוק משנה מדרך הכתובים בכ״מ, ולכן אין ללמוד גדו״ד מ„וכי יגח שור״, שהרי בה־לשון „שור״ אין הכתוב משנה מדרכו בכ״מ."],["34","34","ועפ״ז מובן גם מה שרש״י כותב ש„דבר הכתוב בהוה״ [ואינו מסתפק ב־ש„הנשים מצויות מכשפות״ — ראה לעיל הערה 25] — אף שכתב זה כבר לעיל (כא, כח) — כי כאן מחדש שגם בכגון דא דבר הכתוב בהוה. ועפ״ז יובן גם מה שהוזקק רש״י להוסיף „שהנשים מצויות מכשפות״ (ראה לעיל הערה 23) — וגם מ״ש „שהנשים מצויות מכשפות״ (ועד״ז בש״ס) ולא „שהכישוף מצוי בנשים״ — כי מכיון שתיבת „מכשפה״ כאן היא חלק מהדין כנ״ל, באם הנשים לא היו מצויות מכשפות וה„הוה״ ד„מכשפה״ הי׳ שמאורע הכישוף מצוי בנשים יותר, לא הי׳ נאמר (בלשון נקבה —) „מכשפה״ (ובפרט ע״פ המבואר בהערה הקודמת), ולכן מוסיף ומדגיש „שהנשים מצויות מכשפות״, היינו שזהו ענין בהנדון ולא בהמאורע."]]],[1300061148,"ט. דער טעם פאַרוואָס אין פסוק „כל אלמנה ויתום לא תענון״ דאַרף רש״י ווידער באַוואָרענען „הוא הדין לכל אדם אלא שדבר הכתוב בהוה״³⁵:\nדער כלל „דבר הכתוב בהוה״ (בדרך הפשט) פּאַסט בלויז ווען דער פסוק שרייבט אין דוגמא, אָבער ווען עס שטייען אין פסוק צוויי דוגמאות, קען מען ניט זאָגן אַז דער פסוק רעדט „בהוה״, וואָרום ווען ער וואָלט געשריבן בלויז אין דוגמא, די וועלכע איז מער מצוי (וואָרום אין פּשטות איז זייער זעלטן³⁶ אַז צוויי דוגמאות זאָלן זיין פּונקט גלייך מצוי); און אין אַזאַ פאַל דאַרף מען זאָגן אַז די דוגמאות אין פסוק זיינען (ניט מחמת „דבר הכתוב בהוה״, נאָר זיי זיינען בדוקא³⁷.\nאון דעריבער, בשעת עס קומט צום פסוק „כל אלמנה ויתום לא תענון״, ווערט ביי דעם „בן חמש למקרא״ אַ שאלה: וויבאַלד אַז דער פסוק זאָגט דאָ צוויי דוגמאות, איז דאָך דערפון געדרונגען, אַז די דוגמאות זיינען ניט מחמת „דבר הכתוב בהוה״, נאָר זיי זיינען בדוקא, איז דאָך תמוה: צי דען מעג מען אַנדערע מענטשן יע פּייניקן — פאַרוואָס זאָגט דער פסוק דוקא „כל אלמנה ויתום לא תענון״?\nאויף דעם זאָגט רש״י (ובשינוי לשון) „הוא הדין לכל אדם״³⁵, אַז אַ ודאי איז דער דין אַז מען טאָר טאַקע ניט פּייניקן קיין מענטשן, און דאָס וואָס דער פסוק זאָגט די אזהרה ספּעציעל ביי „אלמנה ויתום״ (און רעדט נאָר³⁸ וועגן אלמנה ויתום, נאָר אין זיי גופא: „כל אלמנה ויתום״) איז עס דערפאַר וואָס „דבר הכתוב בהוה",[["35","35","גם יש לומר (נוסף לב״ש לקמן בפנים): (א) הכלל „דבר הכתוב בהוה״ שייך לכאורה, כאשר ה„הוה״ הוא בה־מאורע (ולא בהציווי והדין שצ״ל בדיוק ביותר, כמובן). וכמו: „מכשפה (לא תחי׳)״, שה„הוה״ הוא בהענין ד„מכשפה״ — שה־נשים מצויות מכשפות (ולא בהציווי „לא תחי׳״), שאז מובן מה שכתוב (בנוגע לעושה הכישוף) „מכשפה״ — אף שהציווי הוא גם בנוגע למכשף. משא״כ בנדו״ד, דאף שאל־מנה ויתום דבר מצוי הוא לענותם, הרי בהכתוב „אלמנה ויתום לא תענון״ ה„הוה״ (תענון): הוא בענין הציווי, והציווי הוא בנוגע לעינוי דכל אדם, ולכן קס״ד שאין סברא לומר שהציווי „אלמנה ויתום לא תענון״ כוונתו — לא תענו דכל אדם. (ב) באם כוונת אזהרת הכתוב היא לכל אדם, אין פירוש לכאורה לתיבת „כל אלמנה ויתום״ (יעדער אלמנה און יעדער יתום), מכיון שהבנתה היא לכל אדם."],["36","36","להעיר מהפלוגתא האפשר לצמצם (בכורות יז, א). אבל בנדו״ד — הרי תורת אמת בודאי יכולה לצמצם. אלא שי״ל (עכ״פ בדוחק) שמשתנה מזמן לזמן ולכן בכתר־בים שאפ״ל באופן אחר — עכצ״ל דנקט ב׳ דוגמאות מפני השינוי כו׳."],["37","37","ועפ״ז מובן גם בפשטות מה ש־רש״י אינו מפרש (לעיל פסוק כו) שזה שנאמר שן ועין הוא לפי שדבר הכתוב בהוה (כבראב״ע שם). ונוסף לזה: מסגנון הכתוב „ואם שן כו׳״ (התחלת דין חדש, ובאריכות גדולה — בפסוק בפ״ע), מוכח שאי״ז מחמת „דבר הכתוב בהוה״ (אפילו באם היינו אומרים שגם בב׳ דוגמאות שייך כלל זה)."],["38","38","והיינו שרק הדין ד„לא תענון״ הוא בנוגע לכל אדם, אבל הכתוב מדבר רק באלמנה ויתום, וכדמוכח גם ממה שמסיים „והיו . . אלמנות . . יתומים״, שבפשטות הוא כעין מדה כנגד מדה (וכמ״ש החזקוני)."],["39","39","ולכן מוסיף רש״י „לפי״ (ראה לעיל הערה 23) — כי כוונתו ב„שהם תשושי כח כו׳״ הוא לבאר [לא רק איך שהדוגמא שבכתוב היא „הוה״ (כדלעיל כב, יז. לקמן כב, ל), אלא גם] הטעם על „דבר הכתוב כו׳״, כבפנים."]]],[1300061149,"לפי שהם תשושי כח ודבר מצוי לענותם״: ווייל זיי זיינען „תשושי כח״ און ס׳איז אַ „דבר מצוי לענותם״, דאַרף מען דעריבער ספּעציעל מזהיר זיין אַז מען זאָל זיי ניט פּייניקן.\nי. ע״פ הנ״ל וועט אויך זיין פאַרשטאַנדיק, וואָס אין פסוק „ונפל שמה שור או חמור״ דאַרף רש״י אָנקומען צו אַ „לימוד״ אַז „הוא הדין לכל בהמה וחי׳״ און מוז אויך מפרש זיין אַז „שור או חמור״ קומען בכדי צו ממעט זיין אדם וכלים: וואָרום וויבאַלד אַז אין פסוק שטייען צוויי דוגמאות — „שור״ און „חמור״ — איז אויב ניט דער לימוד „שור שור משבת״, וואָלט מען געזאָגט אַז „בעל הבור ישלם גו׳״ איז דוקא ביי שור וחמור, און ערשט דער „לימוד״ זאָגט אונז אַז „הוא הדין לכל בהמה וחי׳״; און די צוויי דוגמאות וואָס שטייען אין פסוק זיינען צוויי מיעוטים: „(שור) ולא אדם (חמור) ולא כלים״.\nועפ״ז י״ל, אַז אויך אין דעם פסוק געפינט מען דעם ענין פון „דבר הכתוב בהוה״. וואָרום צוליב דעם אַליין וואָס מען דאַרף האָבן צוויי מיעוטים, האָט געקענט שטיין „ונפלה שמה בהמה או חי׳״ (וכיו״ב), וואָס אויך דאַן וואָלט מען אָפּגעלערנט „בהמה ולא אדם חי׳ ולא כלים״⁴⁰. פאַרוואָס שטייט טאַקע „שור או חמור״ — איז עס דערפאַר וואָס זייער נפילה לבור איז מער מצוי, כנ״ל ס״ב⁴¹.\nיא. אע״פ אַז דער כלל „דבר הכתוב בהוה״ איז (ווי רש״י האָט מפרש געווען אין די פריערדיקע פסוקים) ניט בלויז ביי אַ דוגמא וואָס ווערט געזאָגט בדרך „סיפור״, נאָר",[["40","40","ועפ״ז מתורצת קושיית המפרשים (רבותינו בעה״ת, רא״ם וגו״א כאן): איך אפשר למעט אדם מ„שור״, והרי תיבת „שור״ אינה מיותרת כי אצטריך למילף שור שור משבת — כי הלימוד „ולא אדם . . ולא כלים״ הוא [לא מהדיוק „שור״ ו„חמור״, כ״א] מזה שיש בכתוב ב׳ דוגמאות, וגם אם הי׳ נאמר „בהמה או חי׳״ היינו ממעטים אדם וכלים, כבפנים."],["41","41","ומה שהוזקק רש״י להוכיח „הוא הדין לכל בהמה וכו׳״ מהלימוד „שור שור משבת״, ולא פירש „דבר הכתוב בהוה״ — אף שהצורך לב׳ דוגמאות יש טעם לזה — י״ל: א) לפי שיש סברא לומר שהדין „בעל הבור ישלם״ הוא דוקא בשור וחמור, כנ״ל סעיף ב׳. ב) אפילו באם נאמר שאין סברא לחלק בין שור וחמור לכל בהמה וחי׳ — הרי הטעם להפי׳ „דבר הכתוב בהוה״ (כשאין סברא לחלק בין הדוגמא שבכתוב לשאר דוגמאות) הוא, בכדי שלא נאמר שהוא גזה״כ (כדלעיל הערה 15). אבל בנדו״ד, שגם להפי׳ „ה״ה לכל בהמה וחי׳״ יש כאן — החילוק בין בהמה וחי׳ לאדם וכלים [כי באם הי׳ סברא לחלק ביניהם, לא הי׳ צריך למיעוט. וראה רש״י ב״ק נב, א ד״ה בן], וא״כ הי׳ אפ״ל (לולי הלימוד שור שור משבת) ששור וחמור שבכתוב הם בדוקא, בגזה״כ. ג) מכיון שברוב המקומות, כשישנן ב׳ דוגמאות, הם (לא מחמת „דבר הכתוב בהוה״, רק) בדוקא — ה״ז עצמו מוכיח (לולי הלימוד שור שור משבת) שגם ה־דוגמאות דשור וחמור שבכתוב הם בדוקא, כבכ״מ [כי באם הדין שבכתוב הי׳ בכל בהמה וחי׳, לא הי׳ נאמר „שור או חמור״ — מכיון שעפ״ז יש מקום לטעות (וע״ד מ״ש סוף הערה הנ״ל)], ולכן הוזקק רש״י להלימוד „שור שור משבת״. ועפ״ז יומתק מה שרש״י מדייק „שבכל מקום כו׳״ — דלכאורה, למאי נפק״מ — בכדי לבאר, שהתיבות „שור או חמור״ שבכתוב אין בהן נתינת מקום לטעות, מכיון שבכל מקום שנאמר שור או חמור אנו למדין משבת."]]],[1300061150,"אויך ווען די דוגמא קומט ווי אַ חלק פון דעם דין גופא\n[ווי למשל, ביי „מכשפה לא תחי׳״, איז דער וואָרט „מכשפה״ אַ חלק פון דעם דין גופא, און פונדעסטוועגן איז די דוגמא געזאָגט געוואָרן בלשון נקבה — מצד דעם וואָס „הנשים מצויות מכשפות״]\nאיז אָבער מסתבר צו זאָגן, אַז אין דעם כלל „דבר הכתוב בהוה״ בעת די דוגמא איז אַ חלק פון דעם דין, זיינען פאַראַן געוויסע הגבלות:\nווען די תורה רעדט בסגנון פון אַ סיפור מאורע, וואָס וועט פּאַסירן, מאָלט דער פסוק אויס דעם מאורע אין אַן אופן הכי מצוי, און אפילו אין אַ פאַל וואו ער דאַרף צוליב דעם מוסיף זיין איבעריקע ווערטער אַזוי ווי אין פסוק „וכי יריבון אנשים והכה איש את רעהו גו׳״, וויבאַלד אַז דער ענין ווערט דאָרטן געשריבן אין אַ סגנון פון אַ „סיפור״, מאָלט דער פסוק אויס אויך דעם אופן ווי דאָס וועט פּאַסירן — „וכי יריבון אנשים״, הגם אַז צוליב דעם איז ער מוסיף איבעריקע ווערטער.\nבעת דער פסוק זאָגט אָבער נאָר דעם דין (ניט „ובשר כי יטרף״, נאָר „ובשר טרפה״) און די דוגמא („בשדה טרפה״) איז אַ חלק פון דער הודעת דין גופא, איז מסתבר, אַז אויך די פרטים פון דער דוגמא זיינען אַ חלק פון דעם דין (אפילו ווען אויך ביי אַן אַנדער פאַל איז אַזוי דער דין און די דוגמא קומט מחמת „דבר הכתוב בהוה״). און דעריבער לייגט זיך ניט אין שכל אַז צוליב אויסמאָלן אַ דוגמא מצוי׳, זאָל דער פסוק מוסיף זיין איבעריקע ווערטער וואָס זיינען ניט נוגע צום עצם דין. און ס׳איז אויך מסתבר צו זאָגן, אַז אין פסוק וועט אין אַזאַ פאַל שטיין בלויז דער ענין גופא וועגן וועלכן עס האַנדלט זיך, אָבער ניט דעם אופן ווי דער ענין האָט פּאַסירט, אויב דאָס איז ניט נוגע צום דין אַליין (אפילו ווען דאָס וועט ניט מוסיף זיין קיין איבעריקע ווערטער).\nאון דעריבער האָט מען געדאַרפט לערנען אין פסוק „ובשר בשדה טרפה״, אַז דער צוגעקומענער וואָרט „בשדה״ איז (ווי די ווערטער „ובשר טרפה״) נוגע צום עצם דין, דאָס הייסט אַז דער איסור איז דוקא ביי בשר וואָס איז נטרף געוואָרן אין שדה — דערפאַר איז רש״י מחדש „אף בבית כן⁴² אלא שדיבר הכתוב בהוה מקום שדרך בהמות ליטרף״, אַז דער כלל „דיבר הכתוב בהוה״ איז אויך ווען צוליב דעם קומט צו אַן איבעריקער וואָרט, און אפילו ווען דער וואָרט איז ניט קיין פרט אין דעם ענין גופא, נאָר ער איז בלויז אַ „מקום שדרך בהמות ליטרף״.\nיב. ע״פ הנ״ל ווערט מען אויך פאַרשטיין וואָס רש״י דאַרף ברענגען צוויי פסוקים צו באַווייזן אַז אויך אין אונדזער פאַל איז דאָ דער כלל „דבר הכתוב בהוה״ — ווייל יעדער איינער פון די צוויי פסוקים איז מוכיח אַן אַנדער ענין⁴³:\nפון „כי בשדה מצאה״ באַווייזט רש״י, אַז צוליב אויסמאָלן דעם אופן",[["42","42","ועפ״ז מובן (ראה לעיל הערה 23) מה שכתוב „אף בבית כן״, בסגנון של חידוש יותר — ולא „אחד בבית ואחד בשדה״ (ע״ד מ״ש לעיל כא, כח. כב, יז)."],["43","43","ועפ״ז מובן מה שגבי פסוק השני כותב רש״י עוה״פ „וכן״ — כי ההוכחה מפסוק זה היא לענין אחר. וראה לקו״ש ח״ה ע׳ 253 הערה 20."]]],[1300061151,"המצוי קען דער פסוק מוסיף זיין ווערטער אויך ביי אַ דין; און פון „אשר לא יהי׳ טהור מקרה לילה״ ברענגט רש״י אַ ראי׳ אַז דער כלל „דבר הכתוב בהוה״ (אפילו ביי אַ דין) איז אויך בנוגע דעם אופן הענין אויף וועלכן דער דין קומט, כדלקמן.\nיג. דער פסוק „כי בשדה מצאה״ איז [ניט אַן ענין פון „סיפור דברים״, נאָר „כי״] אַ טעם אויף דעם דין (ובמילא — אַ חלק פון דעם דין) „ולנערה לא תעשה דבר״: פאַרוואָס קומט איר ניט קיין עונש — „כי בשדה מצאה״ ווייל ער האָט איר געפונען „בשדה״, אין אַן אָרט וואו „אין מושיע לה״.\nשטעלט זיך די פראַגע: דער זעלבער דין איז דאָך אויך ווען „בעיר מצאה״ אויב נאָר „אין מושיע לה״, היינט פאַרוואָס זאָגט דער פסוק (אַלס אַ טעם) „כי בשדה מצאה״?\nהן אמת אַז „בשדה״ איז מער מצוי דאָס וואָס „אין מושיע לה״ — איז דאָך אָבער גענוג עס זאָל שטיין „כי צעקה גו׳ ואין מושיע לה״. וואָס דאַרף דער פסוק צולייגן „בשדה מצאה״? איז דערפון געדרונגען, אַז מצד „דבר הכתוב בהוה״ איז דער פסוק מוסיף ווערטער אויך ביי אַ דין⁴⁴.\nאָבער מיט דעם פסוק אַליין קען זיך רש״י ניט באַגנוגענען. וואָרום היות אַז דער טעם אויף „ולנערה לא תעשה דבר״ איז — דער אָרט וואו „אין מושיע לה״, קומט דאָך במילא אויס אַז די דוגמא „בשדה״ — וואָס איז דער „הוה״ פון „אין מושיע לה״ — איז ניט בשייכות מיט אַ זייטיקן ענין, נאָר בשייכות מיטן דין אַליין.\nאיז דעריבער „כי בשדה מצאה״ (כאָטש אויך דאָרט זיינען די ווערטער איבעריק) נאָך ניט קיין „חבר״ ממש צום „בשדה״ פון אונדזער פסוק, וואו דער אָרט וואו די בהמה איז נטרף געוואָרן איז לגמרי אַ זייטיקער ענין וואָס איז ניט נוגע צום דין „ובשר טרפה (לא תאכלו)״.\nדערפאַר איז רש״י מוסיף „וכן אשר לא יהי׳ טהור מקרה לילה״, וואָס אויך דאָרט איז די דוגמא „לילה״ אַ זייטיקער ענין, און צום דין „מקרה״ איז כלל ניט נוגע דער זמן ווען דאָס האָט פּאַסירט.\nאָבער אויך מיט דעם פסוק אַליין קען זיך רש״י ניט מסתפק זיין. ווייל דער וואָרט „לילה״ איז ניט איבעריק⁴⁵, היות אַז פאַר דעם שטייט „ונשמרת מכל דבר רע״ און גלייך נאָך דעם (און אַ הקדמה „והי׳ אם לא תשמע״) שטייט „כי יהי׳ . . מקרה״ איז דאָך ניט גלאַטיק ווי קען דאָס זיין? איז דער פסוק מוסיף",[["44","44","ועפ״ז יומתק (א) מה שרש״י מעתיק גם תיבת „כי״ — לפי שע״י תיבה זו מודגש ש„בשדה מצאה״ אינו ענין של סיפור. (ב) מה שאינו מוכיח מ„ואם בשדה ימצא״ שבתחלת הפרשה (וכן מ„ומצאה איש בעיר״ שבפסוק כג) — כי שם הוא ענין של סיפור. ומה שאינו מוכיח מ„על דבר אשר לא צעקה בעיר״ (שם, כד) — אף שגם שם הוא טעם להדין „וסקלתם״ — כי „בעיר״ היא ההסברה דהתביעה „על דבר אשר לא צעקה״ [דלהיות ש„עיר״ הוא (ע״פ רוב) מקום שיש לה מושיעים, הוי לה לצעוק]. משא״כ „בשדה מצאה״ מיותר, שהרי נאמר „(צעקה גו׳) ואין מושיע לה״."],["45","45","שזה נקרא (גם) „מקרה״ (בלי הוספת תיבת „לילה״) — ש״א כ, כו. ולהעיר גם מבלק כג, ד ופרש״י שם."]]],[1300061152,"„לילה״ — וכדיוק רש״י „הוא הדין למקרה יום״ אָבער דער כתוב רעדט נאָר וועגן לילה (וכנ״ל באַ אלמנה ויתום).\nובמילא איז פון דאָרט קיין ראי׳ ניט צום „בשדה״ פון אונדזער פסוק, וואו דער וואָרט איז אינגאַנצן אַן איבעריקער און אויך אים פעלט גאָרניט אין דעם טייטש פון „ובשר טרפה״\n— דעריבער ברענגט רש״י אויך דעם פסוק „כי בשדה מצאה״, וואָס אויך דאָרט וואָלט גאָרניט געפעלט ווען עס שטייט נאָר „כי צעקה גו׳ ואין מושיע לה״, און די ווערטער „בשדה מצאה״ קומען בלויז צוליב „דבר הכתוב בהוה״.\nע״פ הנ״ל ווערט אויך פאַרשטאַנדיק וואָס רש״י דאַרף אָנקומען צו אַ צווייטן פירוש אפילו נאָך זיין ברענגען ביידע פסוקים פון פ׳ תצא — וואָרום די ביידע ראיות באַווייזן נאָך אַלץ ניט קלאָר אַז ביי אַ דין זאָל די תורה צולייגן אַן איבעריקן וואָרט בנוגע צו אַ לגמרי זייטיקן ענין.\nיד. פון די ענינים פון „יינה של תורה״ אין פירוש רש״י דידן:\nביי אַ פּאַסירונג פון אַ דבר בלתי רגיל, וועט זיך לייכטער אָפּלייגן ביי אַ מענטשן אַז דער מאורע איז געקומען מלמעלה, אָבער ביי דברים ומאורעות רגילים איז דער יצה״ר מפתה „עולם כמנהגו — זיין אייגענעם מנהג וטבע — נוהג״⁴⁶.\nאון אברהם׳ס תמי׳ גדולה⁴⁷ „תאמר שהעולם הזה בלא מנהיג?!״ — טענה׳ט ער אַז אף דערויף דאַרפן זיין „משוטט בדעתו״ און לחשוב ביום ובלילה⁴⁸ וכו׳; און דאָס וואָס מ׳האָט שוין אויסגעפונען דעם אמת און די וואָס האָבן לכתחילה ניט מודה געווען בזה איז „גבר עליהם בראיותיו״⁴⁹ — איז דער „זקן וכסיל״⁵⁰ מכניס רוח שטות⁵¹ אין דעם לב כסיל לשמאלו⁵² — איז דאָך בכלל ניטאָ קיין תמי׳ וקשיא און האמת נעדרת.\nאון אויף דעם ברענגט רש״י דעם כלל „דיבר הכתוב בהוה״ — אַז אויך אַ „הוה״, אַ דבר הכי מצוי, קומט (ניט מצד הטבע ח״ו, נאָר) ווייל „דבר הכתוב״⁵³, מצד די עשרה מאמרות שבכתוב וואָס זיינען מחי׳ און מהווה („הוה״ מלשון מהווה) די אַלע פרטי הנבראים בכל רגע ורגע⁵⁴.\nאון רש״י איז מודיע דעם כלל אפילו צו אַ בן חמש (למקרא) — וואָרום ער איז דאָך פון די אויף וועמען עס שטייט בל׳ הרמב״ם⁵⁴ „בחר ה׳ ישראל לנחלה״ — דאַמאָלס ווען „נתנבא משה רבנו״ — געמיינט בא מתן תורה — „והודיעם דרך עבודתו״.\nטו. אָט דעם ענין איז רש״י מפרש (און מגלה בפשטות) ערשט אין פ׳ משפטים, ווייל פאַר מ״ת, ווען ס׳איז געווען די „גזירה״ (דער שניט צווישן „עליונים״ און „תחתונים״)⁵⁵, האָט מען ניט געקענט אָנזען בגילוי ממש דעם „דיבר הכתוב״ — „עליונים״, אין די ענינים פון „הוה״, „תחת־",[["46","46","ע״ז נד, ב."],["47","47","ב״ר ר״פ לך לך."],["48","48","רמב״ם הל׳ ע״ז פ״א ה״ג."],["49","49","קהלת ד, יג. וקה״ר שם."],["50","50","ראה סוטה ג, א."],["51","51","קהלת י, ב."],["52","52","ראה לקו״ת דברים סו, א."],["53","53","ראה שעהיוה״א בתחלתו."],["54","54","רמב״ם שם ספ״א."],["55","55","שמו״ר פי״ב, ג. תנחומא וארא ט."]]],[1300061153,"תונים״ (בתכלית —) וואָס אין זיי איז פאַראַן מער דער נתינת מקום צום טעות אַז „עולם כמנהגו בלי מנהיג נוהג״; דוקא לאחרי מ״ת, ווען דער „כתוב״ (תורה) איז געקומען דאָ למטה און ס׳איז געוואָרן דער „חיבור עליונים ותחתונים״ — דאַן קען מען אויך אין דעם „הוה״ פון תחתונים אָנזען דעם „דיבר הכתוב״ בגילוי.\nאָבער אעפ״כ זאָגט רש״י דעם כלל „דיבר הכתוב בהוה״ ניט אין פ׳ יתרו נאָר אין פ׳ משפטים, וואָס קומט נאָך דער סדרה פון מ״ת — ווייל דער עיקר אויפטו פון „חיבור עליונים ותחתונים״ וואָס איז נתחדש געוואָרן ביי מ״ת איז, אַז אויך לאחרי מ״ת⁵⁶, נאָך „במשוך היובל״⁵⁷, זאָלן אידן דורך זייער עבודה, מחבר זיין עליונים ותחתונים — מגלה זיין אין „הוה״ דעם „דיבר הכתוב״.\nאון דעריבער זאָגט רש״י דעם כלל „דיבר הכתוב בהוה״ אין פ׳ משפטים, ווייל [נוסף לזה וואָס זי איז די ערשטע סדרה וואָס נאָך מ״ת] דער תוכן⁵⁸ פון דער סדרה איז — אַז אויך אין „משפטים״ וואָס זיינען מצות שכליות, דאַרף מען מגלה זיין אַז זיי זיינען „מסיני״⁵⁹.\nטז. קען מען דאָך מיינען אַז די השגחה העליונה איז נאָר אויפן ענין גופא, אָבער ניט אויף דעם אופן ווי דער ענין זאָל פּאַסירן; — אויף דעם זאָגט רש״י אין פסוק „ובשר בשדה טרפה״, אַז דער כלל „דבר הכתוב בהוה״ איז ניט נאָר בנוגע צום ענין גופא, נאָר אויך בנוגע צום מקום וזמן („שדה״ און „לילה״) וואו און ווען דער ענין זאָל פּאַסירן;\nוואָס פון דעם איז פאַרשטאַנדיק אויך בנוגע צו אַלע אַנדערע פרטים ואופנים פון אַ מאורע — וכמאמר הבעש״ט⁶⁰, אַז ניט נאָר דער אי־בערגיין ממקום למקום, אפילו פון אַ שטרויעלע, איז בהשגחה פרטית, נאָר אויך דער אופן ווי דאָס זאָל פאַרקומען, צי ברגלי אדם ובהמה אָדער דורך אַ רוח סערה וכדומה — אַלץ, יעדער קלענסטער פרט אין דעם, איז בהשגחה פרטית.\n(משיחות ש״פ משפטים, תשא, ויק״פ תשכ״ח)",[["56","56","משא״כ החיבור דבשעת מ״ת גופא — אינו חידוש כ״כ, מכיון שלא היו או ה„תחתונים״ במציאות דלפני זה או דלאחר זה, שהרי „לית אתר דלא מליל מיני׳ עמהון״ (תקו״ז — הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל״ו</a>. עיי״ש, וראה גם רבותינו בעה״ת עה״פ אנכי ה״א); „צפור לא צוחה וכו׳״ (שמו״ר ספכ״ט). ועוד. וראה גם לקו״ש ח״ד ע׳ 1027 ואילך, בטעם החביבות דמעל״ע הראשון שלאחרי מ״ת, כי אז הותחל ענין העבודה."],["57","57","יתרו יט, יג. ובפרש״י שם: הוא סימן סילוק שכינה. שו״ע אדה״ז הל׳ יוהכ״פ סו״ס תרכ״ג."],["58","58","להעיר, שעד״ז הוא גם בנוגע לה־חביבות דיום הב׳ דחה״ש (ראה לעיל הערה 56), דנוסף לזה שהוא יום הראשון שלאחרי מ״ת, גם הענין של יום זה עצמו מורה לענין העבודה, כמבואר בלקו״ש שם."],["59","59","פרש״י ר״פ משפטים. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081141\" data-slug=\"likkutei-sichot\" data-id=\"1300081141\">לקו״ש ח״ג ע׳ 899</a>. לקו״ש ח״ח ע׳ 130 ס״ט."],["60","60","ראה לקו״ד ח״א פג, ב (שיחת יט כסלו תרצ״ד אות ג׳)."]]],[1300061154,"א. אין פסוק „ראשית בכורי אדמתך גו׳ לא תבשל גדי בחלב אמו“ ¹ שטעלט זיך רש״י (אין צווייטן דיבור) אויף „לא תבשל גדי“ און איז מפרש: „אף עגל וכבש בכלל גדי שאין גדי אלא לשון ולד רך ממה שאתה מוצא בכמה מקו־מות שכתב גדי הוצרך לפרש אחריו עזים את גדי העזים ³ שני גדיי עזים ⁴ ללמדך שכל מקום שנאמר גדי סתם אף עגל וכבש במשמע ⁵. ובשלשה מקומות ⁶ נכתב בתורה אחד לאיסור אכילה ואחד לאיסור הנאה ואחד לאיסור בישול“ ⁷.\nאיז אין דעם ניט מובן: דער סיום פון רש״י׳ס פירוש „ובשלשה מקומות נכתב בתורה כו׳“ האט לכאורה קיין שייכות ניט צום אנהויב פון זיין פירוש „אף עגל וכבש בכלל גדי כו׳“. וואלט דאך מער געפאסט אז רש״י זאל שרייבן די צוויי ענינים („אף עגל וכבש כו׳“ און „ובשלשה מקומות כו׳“) אין צוויי באזונדערע דיבור־המתחיל׳ס, און פאר דעם ענין „ובשלשה מקומות כו׳“ זאל ער נאכאמאל מעתיק זיין די ווערטער „לא תבשל גדי“ — ווי דרכו של רש״י אין אנדערע ערטער ביי ענליכע פאלן?\nדי קשיא איז נאך שטארקער: די צוויי ענינים הנ״ל, איז ניט נאר וואס זיי טיילן זיך אויס אין זייער תוכן, נאר זיי באציען זיך אויף באזונדערע ווער־טער פון פסוק: דער טייל פון פירוש „אף עגל וכבש כו׳“ טייטשט אפ נאר דעם ווארט „גדי“, און ס׳איז לכאורה ניט נויטיק (צוליב דעם טייל פון זיין פירוש) צו מעתיק זיין אויך די ווער־טער „לא תבשל“; דאקעגן פארן צווייטן טייל פון זיין פירוש „ובשלשה מקומות כו׳“, וואו ער איז מפרש וואס די כללות האזהרה חזר׳ט זיך איבער דריי מאל, נויטיקט זיך צו מעתיק זיין בלויז „לא תבשל“. ובמילא ווערט דאך די קשיא (ניט נאר פארוואס ביידע ענינים זיינען אין זעלבן דיבור, נאר אויך —) פארוואס שרייבט רש״י ביידע ענינים אויף אלע דריי ווערטער „לא תבשל גדי“?\nאויך איז ניט מובן דער סדר ווי רש״י ברענגט די צוויי ענינים: ווי־באלד אז מיט זיין פירוש „ובשלשה מקומות כו׳“ באווארנט ער צוליב וואס",[["1","1","פרשתנו כג, יט."],["2","2","כ״ה בדפוס ראשון. ובכמה דפוסים: „כגון אנכי אשלח גדי עזים (וישב לח, יז) את גדי כו׳“. וכן ישנם עוד כמה שינויים."],["3","3","וישב לח, כ."],["4","4","תולדות כז, ט."],["5","5","וכ״ה בחולין קיג, ב. בחולין שם: „פרה ורחל“. וברש״י כאן „עגל וכבש“ — כי „גדי“ הוא „ולד רך“. אלא שממ״ש רש״י (חולין שם — ד״ה מחד קרא. ושם קיד, א — ד״ה בחלב אמו) „עגל וטלה“ מוכח שגם בדרך ההלכה המש־מעות ד„גדי“ היא כנ״ל *, ומה שלשון הגמרא היא „אפילו פרה ורחל במשמע“ — לפי שבדרך ההלכה אין חילוק בזה. או י״ל (כי לפי הנ״ל דוחק קצת הלשון „במשמע“) שהכוונה היא ל„ולד“ הפרה ור־חל. ועל פי זה יומתק ג״כ השינוי ל„פרה“ (ולא „פר“, או „שור“ — כרגיל ברוב המקומות כשכולל זכרים ונקבות — נקט ל׳ זכר). וראה גם רמב״ם הל׳ מאכלות אסורות פ״ט ה״ג: „גדי הוא כולל ולד השור ולד השה ולד העזי“."],["6","6","פרשתנו כאן; תשא לד, כו. ראה יד, כא."],["7","7","וכ״ה בחולין קטו, ב. *) בחינוך מצוה צב: „שאין גדי אלא לשון בהמה והוציא בלשון גדי לפי שהבשר הוא דבר רך כגדי“."]]],[1300061155,"עס דארף בכלל שטיין די אזהרה „לא תבשל גו׳“; דאקעגן מיט זיין זאגן „אף עגל וכבש כו׳“ איז ער בלויז מפרש דעם ווארט „גדי“, האט ער דאך גע־דארפט מקדים זיין „ובשלשה מקומות כו׳“ פאר „אף עגל וכבש כו׳“ ⁸ — פארוואס שטעלט רש״י די צוויי ענינים בסדר הפוך?\nב. בנוגע דעם סדר ווי רש״י שרייבט די צוויי ענינים — דעם פי׳ „ובשלשה מקומות כו׳“ נאך דעם פי׳ „אף עגל וכבש בכלל גדי כו׳“ — קען מען מב־אר זיין:\nלויט רש״י׳ס פירוש „אחד לאיסור אכילה וא׳ לאיסור הנאה וא׳ לאיסור בישול“ מוז מען זאגן, אז דאס וואס אויך אין די צוויי ערטער וואו די תורה אסר׳ט אכילה און הנאה שטייט דער לשון „לא תבשל“, איז עס מצד דעם וואס בישול איז די התחלה וועלכע ברענגט צו אכילה און הנאה: ווען א מענטש קאכט א דבר מאכל, טוט ער דאס בכדי צו עסן אים אדער צוליב הנאה האבן פון אים אויף אן אנדער וועג: געבן דאס עסן זיין קינד, פאר־קויפן א.א.וו. און דערפאר זאגט אן די תורה דעם איסור אכילה און הנ־אה מיטן לשון „לא תבשל“ — ווייל דאס איז בדוגמת * ווי דער „בן חמש (למקרא)“ ווייס, אז בשעת ער גייט טאן א ניט־גוטע זאך, שרייט אים דער מל־מד: גיי ניט — אעפ״י אז דעם מלמד ארט (ניט דער גיין, נאר) די פעולה וועלכע ער גרייט זיך צו טאן ⁹.\n(ע״ד ווי מען געפינט אין אן אנדער ארט ¹⁰, אז די אזהרה ניט צו עסן קיין קדשים, זאגט דער פסוק מיטן לשון „בכל קודש לא תגע“ — ווייל דאס אנרירן א דבר מאכל איז די התחלה וואס ברענגט צו אכילה).\nס׳איז דאך אבער מובן, אז אפטייטשן „תבשל“ — אכילה אדער הנאה, איז דאס ניט „פשוטו של מקרא“ אין דעם „מק־רא“ (פסוק) מצד עצמו, נאר ווייל ס׳איז ניטא קיין אנדער ברירה ¹¹ מחמת אן אנדער ענין. ובפרשתנו אויב דער פירוש פון „תבשל“ זאל זיין כפשוטו, וועט דער ציווי „לא תבשל גדי בחלב אמו“ אין צוויי ערטער זיין איבעריק ¹²; ווען מען זאל אבער קענען איינלערנען אן אנדער פירוש וועלכער זאל מסביר זיין וואס דער לאו דארף שטיין בג׳ מקומות,",[["8","8","וכדלעיל (כא, יד־יח), שבתחלה [מע־תיק הוא רק התחלת הכתוב ו]מפרש „למה נאמר“ הענין בכללותו ואח״כ מפרש פרטים. *8) אבל אין לומר שהוציא איסור אכילה בלשון בישול רק ללמדך שאינו אסור אלא דרך בישול (כבסנהדרין ד, סע״ב. טושו״ע יו״ד רספ״ז) — כי פשטות הלשון „לא תבשל“ מורה שהכתוב מזהיר על הבישול (ולא על האכילה, דרך בישול), ולכן מוכרח לומר כבפנים, שהוציא איסור אכילה בלשון בישול לפי שהבישול הוא הכנה להאכילה. אלא שמ״מ, ממה שנאמר „לא תבשל“ — ולא „לא תכין“ (ע״ד בשלח (טז, ה) „והכינו“) וכיו״ב — מוכח (גם עפ״י דרך הפשט) שאיסור האכילה (וההנאה) היא דרך בישול דוקא."],["9","9","ועפ״ז: א) יומתק פרש״י (בראשית ג, ג) „הוסיפה על הציווי“ (ולא סתם „הוסיפה“, או „על האיסור“ וכיו״ב). ב) יובן מה שראיית הנחש „כשם שאין מיתה בנגיעה כך אין מיתה באכילה“ (רש״י שם ג, ד) נתקבלה אצל חוה. ג) דאין סתירה לזה ממה שאברהם גזר „גזירות להרחקה על אזהרות שבתורה“ (רש״י תולדות כו, ה)."],["10","10","תזריע יב, ד. וברש״י שם."],["11","11","ולהעיר שבפ׳ תזריע שם, מוסיף רש״י „כמו ששנוי ביבמות“."],["12","12","לכאורה אפשר להקשות: הרי גם התחלת הכתוב „ראשית בכורי אדמתך גו׳“ [וכן הפסוקים שלפנ״ז] נכפלו בפ׳ תשא? אבל — החידוש שבפסוקים אלו, פירש רש״י בפ׳ תשא (כמבואר בארוכה בשיחת ש״פ ויקהל תשכ״ח)."]]],[1300061156,"וואלט מען געלערנט אז „תבשל“ אין אלע דריי ערטער איז כפשוטו.\nאון דעריבער שרייבט רש״י זיין פי׳ „ובשלשה מקומות כו׳ אחד לאיסור אכילה כו׳“ נאך זיין פירוש „אף עגל וכבש כו׳“ ובהמשך אחד:\nוואלט מען אנגענומען אז „גדי“ מיינט בלויז „גדי עזים“, קען מען דאן מסביר זיין די „שלשה מקומות“ א סך גלאטיקער: דער ערשטער „לא תבשל גדי גו׳“ אסר׳ט גדי עזים, דער צוויי־טער — עגל וכבש ¹³ (וועלכע זיינען אמנאענטסטן צו „גדי“ — דערמיט וואס אויך זיי זיינען א ולד רך פון מין הבהמה ¹⁴), און דער דריטער — ולד רך פון מין החי׳ ¹⁵.\nאון כאטש אז לויט דעם פירוש איז אין צוויי ערטער דער ווארט „גדי“ ניט כפשוטו ממש — איז אבער מובן, אז ס׳איז פיל גלאטיקער צו זאגן אז דער פסוק רופט אן „ולד רך“ פון אן עגל וכו׳ מיטן לשון „גדי“ דערפאר וואס ער האט די זעלבע תכונה (אייגענ־שאפט) ¹⁶ ווי דאס פלייש פון א גדי וואס צייכנט זיך אויס מיט דעם וואס ס׳איז ווייך, איידער צו זאגן, אז דער פסוק אסר׳ט אכילה און הנאה מיטן לשון „לא תבשל“ — דערפאר וואס דער צוועק פון בישול איז אכילה אדער הנאה.\nאבער — לאחרי ווי מיר ווייסן, ווי רש״י איז מפרש „אף עגל וכבש בכלל גדי“ און מען קען שוין ניט זאגן אז אין די אנדערע צוויי ערטער קומען צו נאך פרטים אין דעם ענין פון „גדי“ — ווארום „גדי“ מיינט שוין יעדן ולד רך פון מין הבהמה ¹⁷, בלייבט איצט צו מרבה זיין נאר איין זאך: ולד רך פון מין החי׳, און איבעריקע פסוקים זיינען",[["13","13","או ש„גדי“ השני מרבה רק „כבש“ שדומה יותר ל„גדי (עזים)“, כי שניהם הם בהמה דקה, ו„גדי“ השלישי — ולד רך של בהמה גסה (וראה עד״ז מכילתא כאן: „אחת לבהמה גסה ואחת לעזים ואחת לרח־לים“)."],["14","14","אבל ולד רך ממין החי׳ לא ילפינן מ„גדי“ שנאמר בפעם השני׳ (כ״א מפעם השלישית). וראה עד״ז מכילתא כאן: „אחת לבהמה (גסה ואחת לדקה) ואחת לחי׳“."],["15","15","וגם בדרך ההלכה הרי ישנה דיעה ש„גדי“ הוא דוקא גדי (העזים), ובשר חי׳ ושאר בהמות מ„גדי“ יתירה נפקא (ראה רש״י חולין קיד, א — ד״ה בחלב אמו)."],["16","16","ויתירה מזו — רגיל זה ביותר בתורה ובפרש״י: „חיות . . ור״ד . . שאינן צריכות מילדות“ כחיות (שמות א, יט). ולא רק ע״פ דרך הדרש (הקרוב לפשט) כבנדו״ד, אלא גם בפשוטו של מקרא, וכמו: גור ארי׳ יהודה (ולא נאמר — כבסיום הכתוב — „כגור ארי׳“) — ויחי מט, ט. ובכ״מ."],["17","17","אבל לא ממין החי׳. שלכן כותב רש״י „עגל וכבש“ דוקא (ראה רש״י ויקרא א, ב). ואין להקשות: מזה שהוצרך (חולין קיג, סע״א) למיעוט „פרט לחי׳“ מוכח לכאורה שאלולי המיעוט גם חי׳ היא בכלל „גדי“ (וראה רש״י חולין שם), אבל — נוסף על זה שאין ראי׳ מלימוד על דרך ההלכה ללימוד על דרך הפשט * — מלשון הגמ־רא (שם ריש ע״ב) „פרה ורחל“ משמע ש(גם בדרך ההלכה) רק בהמה הוא בכלל גדי. ומה שצריך קרא למעוטי חי׳ — כי עפ״י שיטת הגמרא שם אין כל סברא לחלק ביניהם (שלכן גם למעט עוף צריך קרא). וראה לח״מ לרמב״ם שם, שבשר בהמה הוא ממשמעות הכתוב ובשר חי׳ נלמד מפי השמועה. *) ברש״י ראה (יד, כא) „שלשה פעמים פרט לחי׳ כו׳“ — אבל זהו לאחרי שנאמר „לא תבשל גו׳“ פעם שני׳ (בפ׳ תשא) שמזה ילפינן כל בשר (כפרש״י שם „אזהרה לבשר בחלב“ — ראה בארוכה לקמן ע׳ 201 ואילך). ולכן צריכים מיעוט לעוף ולחי׳ (כדלקמן שם ע׳ 204). משא״כ „גדי“ דפרשת משפטים."]]],[1300061157,"דאך פאראן צוויי ¹⁸ — מוז מען לערנען, אז די דריי לאוין קומען אסר׳ן (ניט דריי פרטים אין „גדי“, נאר) דריי פר־טים אין „לא תבשל“: אכילה, הנאה און בישול.\nג. עס בלייבט נאך אבער אלץ שווער: אין פיל ערטער שרייבט רש״י זיין פי־רוש אויף א ווארט וואס שטייט שפע־טער אין פסוק פריער ווי ער איז מפרש א ווארט וואס שטייט אין פסוק פאר דעם. און דאס איז אין א פאל וואו דער פירוש אויפן פריערדיקן ווארט ווערט מוכרח (אדער פארשטאנדיק) ערשט נאך זיין פירוש אויפן שפעטערדיקן ווארט.\nאבער אויך אין אזא פאל, אויב נאר די צוויי פירושים זיינען פארשידענע ענינים (מער ניט וואס איינער איז מכריח דעם צווייטן), טיילט זיי רש״י אויס אין צוויי באזונדערע דיבורים. און אויב רש״י שרייבט יע צוויי ענינים אין איין און דעם זעלבן דיבור, איז עס א בא־ווייז אז די פארבינדונג צווישן זיי בא־שטייט (ניט בלויז אין דעם וואס איינער איז מכריח אדער ער איז א סיבה אויפן צווייטן, נאר) אויך אין זייער תוכן, ד. ה. אז דער אינהאלט (א טייל פון עם, אדער אינגאנצן) פון די ביידע ענינים איז דער זעלבער, און דעריבער קומען זיי אין איין המשך.\nאיז עפ״ז ניט מובן: וואס איז די נקודה המשותפת אין דעם תוכן פון די צוויי ענינים — „אף עגל וכבש בכלל גדי“ צו פארטייטשן דעם ווארט „גדי“, און „ובשלשה מקומות כו׳“ צו מפרש זיין דעם טעם וואס דער לאו שטייט דריי מאל — וואס צוליב זייער משותף׳־דיקן אינהאלט שרייבט זיי רש״י אין דעם זעלביקן דיבור (ובפרט אז דער ערשטער חלק איז נאר אויפן ווארט „גדי“ — ניט אויף „לא תבשל“)?\nד. נוסף אויף דער שוועריקייט הנ״ל (וואס איז די תוכן׳דיקע שייכות פון „ובשלשה מקומות נכתב בתורה כו׳“ צו התחלת הפירוש „אף עגל וכבש כו׳“), איז ניט מובן אויך דער גוף הפירוש „ובשלשה מקומות כו׳“:\nא) אין פאל ווען א קשיא אויף א פסוק קומט מצד אן אנדער פסוק, איז דרכו של רש״י צו באווארענען די קשיא ביים צווייטן פסוק — ניט ביים ערשטן. ווארום בעת׳ן לערנען דעם ערשטן פסוק ווערט נאך ביים תלמיד ניט געשאפן קיין קשיא, וועלכע מ׳זאל דארפן פארענט־פערן.\nעל אחת כמה וכמה דארטן וואו די קשיא איז (ניט מצד א סתירה פון איין פסוק אויפן צווייטן, נאר) מצד דעם וואס אין זאך שטייט צוויי אדער מערערע מאל — איז דאך מובן בפשטות, אז עס האט ניט קיין ארט צו מפרש זיין און דערציילן אין ערשטן פסוק דעם חידוש וואס ווערט אויפגעטאן נאר מצד דעם וואס א צווייטער פסוק, וואס קומט (א סך) שפעטער איז, לכאורה, איבעריג ¹⁹.",[["18","18","ואין לומר ש„גדי“ השלישי מרבה גם בשר שלא מ„ולד רך“ — כי זהו היפך משמעות הלשון „גדי“ (ראה לעיל הערה 5). וכן אין לומר שמרבה עוף (וכבמכילתא כאן: „אחת לבהמה ואחת לחי׳ ואחת לעוף“), כי עוף אין לו חלב אם, ואין שייך בו „לא תבשל בחלב אמו“."],["19","19","שלכן אין רש״י מפרש בפרשתנו — הטעם למה נכפל בפ׳ תשא הציווי „ראשית בכורי אדמתך גו׳“ וכן כו״כ ציוויים שלפנ״ז."]]],[1300061158,"איז דאך זייער שווער וואס רש״י שרייבט דא „ובג׳ מקומות כו׳“: וואס איז איצט אין אונזער פסוק נוגע צו מפרש זיין די חידושים וואס קומען ארויס נאר מצד די ווייטערדיקע צוויי פסוקים ²⁰?\nב) לויט דער פשטות פון לשון הפסוק „לא תבשל גו׳“ וואלט געדארפט אויס־קומען, אז ווען עס שטייט בלויז איין מאל וואלט עס געמיינט דעם איסור בישול, „לא תבשל“; ווען „לא תבשל“ שטייט נאך צוויי מאל, איז מען מרבה (אויסער בישול) אויך איסור אכילה — פון צווייטן מאל און איסור הנאה — פון דריטן מאל.\nאבער רש״י׳ס לשון איז „אחד לאיסור אכילה וא׳ לאיסור הנאה וא׳ לאיסור בישול“ ²¹ — וויסנדיק אז אין פרש״י איז אויך דער סדר בדיוק, קומט דער־פון ארויס, אז דער ערשטער „לא תב־של“ גייט אויף איסור אכילה, דער צוויי־טער — אויף איסור הנאה, און ערשט דער דריטער גייט אויף איסור בישול!\nאיז מוכח דערפון, אז דאס וואס „לא תבשל“ מיינט בישול כפשוטו — איז אזא חידוש גדול אז מען זאגט אים נאר נאכדעם ווי ס׳איז ניטא קיין שום אנדער ברירה (ווייל אכילה און הנאה ווייס מען שוין פון די פריערדיקע צוויי פסוקים)! פון וואנעט נעמט עס רש״י?\nדער פלא איז נאך גרעסער: דער רמב״ם אין ספר המצות שלו ²² און דער חינוך בספרו ²³ — וואס זיינען ביידע הלכה־ספרים — זיינען מפרש ²⁴ אז „לא תבשל“ פון פ׳ משפטים מיינט, כפשוטו, איסור בישול, און „לא תבשל“ פון פ׳ תשא און פ׳ ראה — וויבאלד זיי זיינען געזאגט געווארן „פעם שני׳“ — גיי־ען זיי אויף איסור אכילה און איסור הנאה, און רש״י, וואס איז מפרש פשוטו של מקרא, לערנט גאר אז די ערשטע צוויי אזהרות זיינען אויף איסור אכילה והנאה, און ערשט די דריטע — זאגט אן דעם איסור בישול!\nה. איז דער ביאור אין דעם: רש״י מיט זיין פירוש „ובג׳ מקומות כו׳“ איז אויסן צו פארענטפערן א דבר תמוה וואס שטעלט זיך באלד אין אונזער פסוק „לא תבשל גדי“:\nמען געפינט ניט אין ערגעץ בתורה (ופשיטא — לויט די ידיעות און וואס עס זעט א בן חמש למקרא) אז א זאך זאל זיין אסור בבישול: געוויסע זאכן זיינען אסור באכילה, אנדערע זאכן זיי־נען אסור בהנאה — אבער קיין שום אנדער זאך איז ניט אסור בבישול ²⁵. פארוואס זאל עפעס „גדי בחלב אמו“ זיין אסור בבישול ²⁶?",[["20","20","ולהעיר, שאפילו בחינוך (מצוה צב) אינו מפרש מאומה בפ׳ משפטים בנוגע להחידוש שבפ׳ תשא ופ׳ ראה. וראה גם ראב״ע כאן: „ועוד אדבר למה הזכיר . . פעם שנית . . במקום כל אחד מהם“."],["21","21","ואף שכ״ה לשון הגמרא (שם קטו, ב), הרי באם „לא תבשל“ הראשון הי׳ בא (לפרש״י) לאיסור בישול, הי׳ רש״י משנה מלשון הש״ס (כדרכו בכ״מ), בכדי שלא יאמרו שע״פ פשוטו של מקרא „לא תבשל“ הראשון בא לאיסור אכילה."],["22","22","מל״ת קפ״ו."],["23","23","מצוה צב. קיג."],["24","24","וכ״מ גם מהסדר שבטושו״ע יו״ד ר״ס פז."],["25","25","ומובן בפשטות, שאיסור בישול בשבת (ראה לעיל בשלח טז, כג) אינו שייך כלל לנדו״ד — כי שם האיסור הוא, ע״ד האיסור שלוקטי המן לא יצאו ללקטו (פרש״י שם טז, כט) — מפני (כהקדמה שבכתוב עצמו, שהיום הוא) שבתון שבת קודש להוי׳, אבל לא מצינו (בשום מקום) דבר האסור בבישול."],["26","26","ולהעיר, שגם בחינוך (מצוה צב) כתב [לאחרי שמבאר טעם על איסור בישול בשר"]]],[1300061159,"דערפאר איז רש״י מבאר גלייך דא „ובג׳ מקומות נכתב בתורה אחד לאיסור אכילה כו׳“, אז אונזער פסוק אסר׳ט טאקע ניט קיין בישול, נאר ער איז אן אזהרה אויף איסור אכילה ²⁷.\nנאר בכדי צו קענען איינלערנען אזא פי־רוש לפי דרך רש״י — פשוטו של מקרא, מוז רש״י מבאר זיין „ובג׳ מקומות כו׳“:\nווען „לא תבשל“ וואלט געשטאנען בלויז איין מאל, וואלט מען געמוזט לער־נען אז ער מיינט איסור בישול כפשוטו, טראץ דעם וואס מען געפינט ניט ער־געץ־וואו אן ענלעכן איסור, ווארום אע״פ אז עס איז א חידוש גדול — ווארום „לא מצאתי לו חבר“ — קיין שום זאך איז ניט אסור בבישול — מען קען אבער ניט טייטשן תבשל — אכילה.\nוויבאלד אבער אז „בג׳ מקומות נכ־תב בתורה“, וואס בפשטות — איז עס ניט „להרבות בלאוין“ נאר דאס זיינען דריי אזהרות אויף דריי באזונדערע עני־נים ²⁸, און היות ווי אין צוויי ערטער מוז מען ארויסנעמען דעם „לא תבשל“ פון זיין משמעות כפשוטו, און פאר־טייטשן אז ער מיינט (ניט תבשל ווי עס בלייבט ביים בישול, נאר דאס וואס עס קומט גלייך נאכדעם, וואס צוליב דעם קאכט ער) — אכילה און הנאה, און אלע דריי זאכן זיינען אסור — בישול, אכילה והנאה,\nאיז מסתבר צו זאגן, אז דער ערש־טער „לא תבשל“ מיינט אכילה, וואס אן איסור אכילה איז גאר ניט קיין חידוש — דער ערשטער איסור בתורה איז „לא תאכל ממנו (פון עץ הדעת)“ ²⁹,\n[און כאטש אז ביים איסור אכילה פון „גדי בחלב אמו“ איז אויך דא א חידוש מצד דעם וואס יעדערער פון זיי („גדי“ און „חלב“) פאר זיך איז דאך מותר באכילה ³⁰ — איז אבער דער חידוש קיין גרעס ניט אפילו ביי א בן חמש למקרא, ווארום ער ווייס שוין וועגן דעם איסור שעטנז ³¹];\nמיטן צווייטן „לא תבשל“ איז די תו־רה מוסיף נאך איסור אין „גדי בחלב אמו“ — איסור הנאה; און דער איסור בישול — וועלכער איז א חידוש גדול ביותר (א סוג איסור וואס איז פאראן נאר ביי „גדי בחלב אמו“) — לערנט מען אפ ערשט פון דריטן מאל.\nו. לכאורה קען מען דערויף פרעגן: סוף כל סוף איז דאך אויך לויט פירוש רש״י בפשוטו של מקרא — בשר בחלב אסור בבישול, היינט וואס קומט אונז ארויס (עס זאל זיין ווייניגער חידוש) דורכן מפרש זיין אז דער ערש־טער (און צווייטער) לא תבשל מיינט ניט איסור בישול? וואס מאכט עס אונז גרינגער אויב די גזירת הכתוב שטייט ניט אין פ׳ משפטים נאר אין פ׳ ראה?\nאין אמת׳ן איז עס אבער פארשטאנ־דיק: ווען מ׳לערנט אז „לא תבשל“ מיינט נאר בישול (עכ״פ — מען ווייס",[["","","בחלב] „ועדיין צריכים אנו למודעי המקו־בל“, וגם לאחרי שמביא טעם הרמב״ם: „וכל זה איננו שוה לי“."],["27","27","ועפ״ז מובן מה שתרגום אונקלוס — שהוא קרוב לפשוטו של מקרא (משא״כ תיב״ע) — מפרש (בכל ג׳ המקומות) „לא תיכלון“. אלא שאי״ז שיטת רש״י. וראה להלן בפנים."],["28","28","ראה גם פסחים כד, רע״ב: כל היכא דאיכא למידרש דרשינן ולא מוקמינן בלאוי יתירי."],["29","29","בראשית ב, יז."],["30","30","רש״י ד״ה מ״ט — חולין קח, א."],["31","31","פרש״י תולדות כו, ה. וראה פסחים מד, ב. נזיר לז, א. תוד״ה חידוש (חולין שם)."]]],[1300061160,"נאך ניט וועגן איסור אכילה והנאה) — איז עס טאקע דאן א חידוש גדול ביותר. אנדערש איז אבער ווען מיר ווייסן (שוין) אז בשר בחלב איז אסור באכילה ובהנאה; דאן קען מען שוין פארשטיין דעם איסור בישול אין דעם, די הסברה בפשטות: דער איסור בישול ביי בשר בחלב איז א תו־צאה פון איסור אכילה והנאה: דער אי־סור אכילה והנאה איז אזוי הארב (ביי בשר בחלב), ביז אז מצד אים האט די תורה גע׳אסר׳ט אויך דעם בישול פון בשר בחלב — ווייל ער קען ברענ־גען צו אכילה והנאה ³².\nדוגמא לדבר פון פריער שוין: אז חוה האט דערהערט אז „מפרי עץ הגן נאכל ומפרי העץ אשר בתוך הגן“ (און פונדעסטוועגן) אמר אלקים לא תאכלו ממנו — איז ביי איר געווען בפשיטות ³³ אז דער ציווי איז אויך (כולל) „ולא תגעו בו“ ³⁴.\nאון דאס איז א ביאור נוסף אויף דעם וואס רש״י לערנט דעם איסור בי־שול ביי בשר בחלב ערשט אין דעם דריטן „לא תבשל“ — הגם דאס איז ניט בהתאם צום פשוט׳ן טייטש — ווייל (אויסער דעם וואס די סברא איז מחייב צו אפשטופן אן איסור וואס אנטהאלט מער חידוש אויף אלץ שפעטער, כנ״ל סעיף ה׳) — דער איסור פון בישול ווערט פארשטאנדיק און האט אן ארט דוקא נאך דעם און מצד דעם וואס בשר בחלב איז אסור באכילה ובהנאה ³⁴*.\nז. עפ״י הנ״ל וועט מען אויך פאר־שטיין די שייכות פון סיום דברי רש״י „ובשלשה מקומות נכתב בתורה אחד לאיסור אכילה כו׳“ צו התחלת פירושו „אף עגל וכבש בכלל גדי כו׳“:\nמיטן פירוש „אף עגל וכבש בכלל גדי“ איז רש״י אויסן (ניט בלויז צו מפרש זיין דעם טייטש פון „גדי“ נאר) אויך צו באווארענען א שאלה וואס שטעלט זיך אין די ווערטער „לא תבשל גדי“ — אויף וועלכע ער שטעלט זיך: מיט וואס איז „גדי“ אויסגעטיילט פון אנ־דערע סארטן בהמות אז דוקא אויף אים איז דא דער איסור „לא תבשל בחלב אמו“?\nבכלל געפינט מען ניט בתורה חי־לוקים — בנוגע צו איסורים וכיוצא בו — פון איין בהמה צו א צווייטער, און אזוי פיל איז דאס פשוט, אז דערפאר איז רש״י מפרש (אן קיין שום ראיות אויף דעם) אז „יגח שור“ — מיינט „אחד שור ואחד כל בהמה וחי׳ ועוף“ ³⁵.\nאיז דאס באווארנט רש״י מיט זיין פירוש „אף עגל וכבש בכלל גדי“ ³⁵*,",[["32","32","ראה כס״מ הל׳ טומאת מת פ״א ה״ב. וראה לקח טוב (להר״י ענגיל — כלל ח׳), כו״כ דוגמאות דסייג בדאורייתא."],["33","33","שלכן נתקבלה אצלה ראיית הנחש „כשם שאין כו׳“ (ראה לעיל הערה 9)."],["34","34","בראשית ג, ב־ג. 34*) וגם לפי המבואר להלן סעיף ז׳ שטעם האיסור „גדי בחלב אמו“ הוא מצד אכזריות, אין לומר שהאיסור הבישול הוא מצד עצמו, כי גם הבישול הוא אכזריות — כי בלא״ה הול״ל לאסור (גם) השימה בחלב אמו (והרי א״א לבישול בלי שימה תחלה). ומזה מוכח שהאכזריות היא דוקא באכילה (ובהנאה) ולא בבישול. ואין סתירה לזה מ„אותו ואת בנו לא תשחטו“ — אף שהוא ג״כ מצד אכזריות, (ובפרט שלפי שיטת הרמב״ם (הל׳ שחיטה רפי״ב) אם עבר ושחטן מותר לאכלן) — כי האכזריות שבשחיטת אותו ואת בנו יש בה גם משום צער בע״ח (ראה להלן הערה 41), ולכן עיקר האכזריות הוא דוקא בשחיטה."],["35","35","פרשתנו כא, כח. וראה עד״ז פרש״י כא, לז. 35*) ולכן מקדים רש״י „אף עגל וכבש בכלל גדי“ ורק אח״כ מוסיף „שאין גדי"]]],[1300061161,"אז דער איסור „לא תבשל גו׳“ איז טא־קע אויך אויף עגל וכבש ³⁶.\n[און כאטש אז אויך לויט פירוש רש״י ווערט נכלל אין „גדי“ בלויז ולד רך ³⁷ (און נאר) פון בהמות (ניט פון חיות) ³⁸ — קען מען ניט פרעגן: מיט וואס איז ולד רך פון בהמות אנדערש פון אלע אנדערע סארטן — ווייל וויבאלד אז דער איסור לא תבשל (אין דעם פסוק) איז כפשוטו „בחלב אמו“ ³⁹, איז פאר־שטאנדיק אז דער טעם האיסור איז מצד אכזריות ⁴⁰ בבעלי חיים (וא״כ מכש״כ",[["","","אלא לשון ולד רך“ — ודלא כבפ׳ תשא שבתחלה מפרש „כל ולד רך במשמע“ ואח״כ כותב „ואף עגל וכבש“* — כי בפ׳ תשא שם מפרש לשון „גדי“ [שלכן אינו מעתיק „לא תבשל“], וראה לקמן שיחה ב׳ לפ׳ תשא (ס״ע 205 ואילך). משא״כ בפרשתנו מפרש ש„לא תבשל“ הוא גם על עגל וכבש, ובהמשך לזה הוא מפרש „שאין (פשוטו) גדי כו׳“ — לבאר מ״ש לפנ״ז."],["36","36","בראב״ע וברשב״ם כאן, שהוא לפי שדיבר הכתוב בהוה. אבל רש״י אינו מפרש כן, כי ס״ל שבדרך הפשט — גם עגל וכבש בכלל גדי."],["37","37","ראה לעיל הערה 5. ומה שרש״י אינו מפרש שהאיסור הוא בכל בשר** ומ״ש „גדי“ הוא לפי שדיבר הכתוב בהוה*** — כי הפירוש „דיבר הכתוב בהוה“ הוא דוקא כשאין סברא לחלק בין המובא בכתוב לשאר הענינים הדומים אליו, משא״כ בנדו״ד שיש סברא לומר שה־איסור הוא רק ב„גדי“ (כדלהלן בפנים)."],["38","38","ראה לעיל הערה 17."],["39","39","להלן בפ׳ תשא (לד, כו) מפרש רש״י: „בחלב אמו פרט לעוף שאין לו חלב אם“ ולפ״ז (דצריך לשלול עוף) מובן דה־איסור לא תבשל הוא גם בחלב אחר. אבל נוסף על מה שמובן בפשטות (וכמדובר כמה פעמים), שרש״י אינו סומך עצמו על מה שיפרש אח״כ — בנדו״ד, בפ׳ משפטים, מכיון שא״א לפרש פרט לעוף כו׳ שהרי „גדי“ (שבפרשתנו) הוא דוקא מין הבהמה (כנ״ל בפנים) ולא חי׳ ועוף — אין להוציא „בחלב אמו“ שבפרשתנו מפשוטו (שהאיסור „לא תבשל“ הוא רק „בחלב אמו“). — וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271042\" data-slug=\"likkutei-sichot\" data-id=\"1300271042\">לקו״ש חכ״ז ע׳ 42</a> הערה 35."],["40","40","ועפ״ז יובן בפשטות* הא ד„ויקח חמאה וחלב ובן הבקר (שהי׳ „רך“ כבפסוק שלפניו) אשר עשה ויתן (אברהם — שהי׳ היפך האכזריות בתכלית, נוסף על שקיים כל התורה) גו׳“ (וירא יח, ח)."],["41","41","רמב״ן בפ׳ ראה — יד, כא. וראה ראב״ע כאן. במו״נ ח״ג פמ״ח משמע, דאין בזה הענין דצער בע״ח. והטעם פשוט, כי „צער בע״ח“ שייך רק כשהוא חי׳ [אבל „אכזריות“ נפש האדם — שייך גם בבשר בחלב]. *) ועפ״י דפוס הראשון — „אף עגל וכבש“ הוא ב„דיבור“ שלאחריו. **) ואף שבפ׳ תשא מפרש רש״י „אזהרה לבשר כו׳“ (שכוונתו בזה היא לכל בשר ולא רק ל„גדי“ — ולד רך), הרי מזה שבפרשתנו אינו מפרש „אזהרה לבשר“ מוכח שהאזהרה שבפ׳ משפטים היא רק ל„גדי“. מובן שרש״י אינו סותר — במה שמוכרח בפשוטו של מקרא — שיפרש זה אח״כ. ההכרח של רש״י בפ׳ תשא לפרט „אזהרה לבשר“ — ראה להלן (ע׳ 201 ואילך). ***) ואין לומר שהפירוש שגדי כולל כל ולד רך, אין הדוגמא ד„גדי“ מצוי יותר משאר בשר — כי גם בהרמב״ם הל׳ מ״א שם ובטוש״ע שם מובא „דיבר הכתוב בהוה“ (וראה הביאור ע״ז ברבינו בחיי שם), ו„הוה“ — זה המציאות בפועל — ולכן אין לחלק בזה בין לימוד ע״ד הפשט, או ההלכה וכו׳. וראה להלן שם (ע׳ 206), שגם רש״י בפ׳ תשא מפרש כן. *) ולפירש״י בפ׳ תשא שם „לא תבשל גדי“ השני למדים שהאיסור הוא גם בחלב אחר (כבהערה 39) התירוץ הוא: (א) שאכלו בזה אחר זה (ובלאה״כ מוכח כן — פירש״י שם עה״פ: קמא קמא כו׳). (ב) מי שאכל זה לא אכל זה. ואף שנתן להם ג׳ לשונות אף שנתן חמאה — הוא בכדי שתהא הבחירה ביד כאו״א ואולי ירצו כולם רק בבן הבקר. וה״ז הכנסת אורחים בהידור. וק״ל."]]],[1300061162,"שאסור צער שלהם) ⁴², ובמילא איז שוין מובן פארוואס דער איסור גייט אן דוקא ביי „גדי“ — ווייל דער „בישול“ (כולל אלע דריי פרטים: אכילה, הנאה און בישול) פון א יונגן ולד אין זיין מוטערס מילך, איז מער אכזריות ווי פון אן עלטערן, און ביי א יונגן ולד גופא איז עס מער אין דעם מין „הבהמה“ ⁴³, וואס זיינען מער ברשות פון דעם מענטשן ווי חיות ⁴⁴, און — בכלל — שוואכער פון זיי א.ז.וו.].\nעפ״ז קומט אויס, אז ביידע ענינים וואס רש״י שרייבט אין זיין פירוש אויף „לא תבשל גדי“ — „אף עגל וכבש בכלל גדי“ אין וועלכן ער איז מסביר דעם טעם האיסור דוקא ביי „גדי“, און „ובשלשה מקומות כו׳ לאיסור אכילה כו׳“ וואו ער איז מסביר דעם טעם פון איסור לא תבשל — האבן אין זיך א נקודה משותפת: דורך די ביידע ענינים ברענגט ער ארויס אז דער איסור „לא תבשל גדי“ איז ניט קיין גזירת הכתוב וואס איז כלל וכלל ניט מובן, נאר עס האט א הסברה אויך אין שכל.\nח. אין פירוש רש״י איז דאך אויך פאראן „יינה של תורה“ ⁴⁵ — און איינע פון די הוראות וואס מען קען אפלערנען פון דער רש״י:\nדי איינציקע זאך וואס די תורה האט גע׳אסר׳ט בבישול — איז גדי בחלב אמו. ועפ״י האמור לעיל — איז דער טעם — לשלול אכזריות וצער פון בעלי חיים, וואס פון דעם זעט מען אויף וויפל ס׳איז חמור דער איסור פון צער בעלי חיים ⁴⁶: טראץ דעם וואס דער ענין פון צער בע״ח דירעקט, איז א טעם צו אסר׳ן גדי בחלב אמו נאר באכילה (אדער אויך בהנאה), האט עס די תורה גע׳אסר׳ט אויך בבישול, דערפאר וואס דערפון קען ארויסקומען אכילה ⁴⁷.\nאון פון דעם דארף מען זיך אפלער־נען אויך וויפל מען דארף זיין נזהר בכל המיני זהירות ניט גורם זיין ח״ו קיין צער צו א צווייטן איד. ווארום מה דאך ביי בעלי חיים האט די תורה מקפיד געווען אזוי פיל אויף זייער צער, היינט מכל שכן בנוגע צו מענטשן, ובשייכות צו אידן בפרט (דער עם הנב־חר — בחרתנו מכל העמים) — על אחת כמה וכמה.\n(משיחות ש״פ תשא תשכ״ח)",[["42","42","דאס אסור באכזריות — פשיטא דאסור בצער בע״ח. וראה שו״ע אדה״ז (ח״ו) הל׳ עו״ד וצער בע״ח ס״ד."],["43","43","ולהעיר, שהאיסור ד„אותו ואת בנו לא תשחטו ביום אחד“ [שהוא ג״כ מטעם אכזריות (חינוך מצוה רצד בטעם השני). וראה ראב״ע ורשב״ם כאן, שהאיסור דלא תבשל גדי בחלב אמו הוא דוגמת האיסור דאותו ואת בנו] — הוא רק בבהמה ולא בחי׳ (יו״ד סט״ז)."],["44","44","כמובן בפשטות. ועפ״י מ״ש בפנים, יובן דיוק לשון רש״י (בראשית א, כו) „בחיות ובהמות כו׳ ירדו לפניהם (ל׳ רבים) והחי׳ מושלת בו“ — כי „לפניהם“ (ל׳ רבים, שכולל גם הבהמות) הוא רק „ירדו“, והחי׳ (גם) מושלת בו."],["45","45","היום יום ע׳ כד."],["46","46","ראה ב״מ לב, ב. ובשו״ע אדה״ז (או״ח סי׳ שה סכ״ו. ח״ו שם) פסק כדעת הפוסקים (נסמן בשד״ח כללים מע׳ צער בע״ח) שהוא מן התורה."],["47","47","ויתירה מזו, שמטעם זה אסרה תורה כל בשר בחלב — וג״כ, לא רק באכילה והנאה אלא גם בבישול — כמבואר להלן שם (ע׳ 201; 204 ואילך)."]]],[1300061163,"<h3>תרומה</h3>\nא. אין דעם סוג הדומם וואָס איז באַנוצט געוואָרן (צווישן אַנדערע סו־גים) פאַר עשיית המשכן און זייַנע כלים, זיינען געווען דריי מינים: זהב, כסף און נחשת<sup data-n=\"1\">1</sup>.\nעס איז דאָך ידוע, אַז „משכן אקרי מקדש\" און „מקדש אקרי משכן\"<sup data-n=\"2\">2</sup>. דערפון איז מסתבר אַנצונעמען, אַז די מעלות און עניני חשיבות וואָס זיינען אין בית המקדש, זיינען זיי (אין אַן ענליכן אופן) געווען אויך אין משכן.\nדאַרף מען פארשטיין: מען געפינט דאָך, אַז אין ביהמ״ק איז יעדער זאַך געווען (אויף וויפל ס׳איז נאָר מעגליך) אין אַן אופן פון עשירות<sup data-n=\"3\">3</sup>; און דאָס — ביז צו אַזוי פארנעם, אַז „השקו את התמיד בכוס של זהב\"<sup data-n=\"4\">4</sup> — ווייל „אין עניות במקום עשירות\"<sup data-n=\"5\">5</sup>. דאָס מיינט: אפילו אַזא כלי, וואָס האָט בלויז גע־נוצט אויף צו אַנטרינקען די בהמה פאַר איר שחיטה אלס קרבן, איז אויך געווען פון זהב —\n[הגם אַז דער „כוס\" איז ניט גע־וועז פון די „כלי המקדש\", נאָר בלויז אַ כלי צוליב אַ בהמה וואָס מ׳האָט איר דערנאָך מקריב געווען; און נאָכ־מער: דער שימוש גופא האָט ניט געדענצט פאַר אַן עבודה, נאָר צוליב הפשט און אין הפשט — נאָר אַלס סיבה אַף אַ תועלת (ניט אַן עיקר) אין דער הפשט: דורך דער השקאה ווערט לייכטער די הפשטת העור פון קרבן<sup data-n=\"6\">6</sup>] —\nהיינט אויב אפילו אַזאַ ניט־עיקר׳־דיקער פרט אין ביהמ״ק האָט גע־דאַרפט זיין מיט דער עשירות פון זהב, האָט דאָך געדאַרפט לכאורה אויסקומען, אַז דער משכן און אלע זיינע כלים האָבן אוודאי געדאַרפט ווערן געבויט און אויסגעאַרבעט בלויז פון זהב. ווי קומט עס, אַז אין דעם זאָל האָבן אַ חלק דער מין פון כסף און אפילו נחשת?\nבנוגע „כסף\", קען מען נאָך פאַר־ענטפערן<sup data-n=\"7\">7</sup>: היות ווי אין אַ געוויסן פרט איז אין כסף דאָ אַ מעלה לגבי",[["1","1","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370498\" data-slug=\"torah-or\" data-id=\"3901370498\">תו״א קיא, ד</a>: במשכן הי׳ ג׳ דבריב כלליים זהב וכסף ונחושת. אבני שוהם ואבני מילואים — הרי: א) לא היו דבר כללי, ב) נשתמשו בהם כמו שהם בלי שינוי ועיבוד, ג) הנשיאים ה־ביאום. וראה מפרשי רש״י (כה, ב), אור־ה״ח (כה, ז) ועוד."],["2","2","עירובין ב, א."],["3","3","רמב״ם הל׳ ביהב״ח פ״א הי״א וי״ט."],["4","4","משנה תמיד פ״ג (ל, א)."],["5","5","שם כט, א. ושם, שמטעם זה הי׳ הכוס של זהב ממש (ולא „גוזמא\"). וכ״ה ההלכה: (רמב״ם הל׳ תמידין פ״א ה״ט. וראה לח״מ שם)."],["6","6","רמב״ם הל׳ תמידין שם ובפיה״מ תמיד פ״ג מ״ד (מהדורת הרב קאפח. ירו־שלים, תשכ״ז) ומסיים שם: כמשנ״ת בביצה. וכן פרש״י בגמרא (ביצה מ, סע״א) „משום סרכא דמשכא\" — „שתהא נוח להפשיטה כו׳\". והנה הרמב״ם עצמו בפיה״מ שם (סוף ביצה) מפרש „כי ההשקאה קודם ה־שחיטה יתיר ריאתה כו׳\" — אבל בפיה״מ מהדורת הרב הנ״ל: שההשקאה לפני ה־שחיטה מקלה את הפשטתה ואם הייתה שם סירכא קלה נפסקת. וראה שם בהערה. ועיין בש״ך יו״ד סל״ט סקל״ב. ואכ״מ."],["7","7","אבל — דוחק. שהרי ברמב״ם הל׳ ביהב״ח שם „אם יש כח בצבור עושין אותן של זהב\". ובמנחות (כח, ב ושו״ג): העשירו עשאום של כסף חזרו והעשירו עשאום של זהב. וראה הערה הבאה."]]],[1300061164,"זהב (ווי דער מדרש<sup data-n=\"8\">8</sup> זאָגט אין דער התחלה פון היינטיקער סדרה), דע־ריבער האָט אויך (מעלת ה)כסף גע־דאַרפט זיין אין משכן. עס בלייבט אבער די קשיא בנוגע צו נחשת?\nמען קען עס ניט פארענטפערן בפש־טות, אַז דעמאלט האָבן די אידן ניט געהאַט גענוג זהב (וכסף) און דער־פאַר האָט זיי דער אויבערשטער אַנ־געזאגט צו נוצן אויף נחשת — וואָ־רום דעמאלט איז דאָך ביי די אידן געווען (ווי די גמרא<sup data-n=\"9\">9</sup> זאָגט) „כל כסף וזהב שבעולם\" — און אַזאַ כמות פון זהב וכסף איז דאָך זיכער געווען גענוג אויף כל עניני המשכן<sup data-n=\"10\">10</sup>.\nב. וועט מען עס פארשטיין דורך מקדים זיין, אַז עס זיינען פאַראַן דריי דעות ווען מ׳איז נצטווה געווארן אויף עשיית המשכן און ווען עס איז גע־וען די נדבת המשכן:\nאין דיעה איז — אין זהר<sup data-n=\"11\">11</sup> — אַז ניט בלויז דער ציווי, נאָר אויך די פעולה פון נדבת המשכן, זיינען געווען (גלייך נאָך מתן תורה) פאַר דעם חטא העגל. און דערמיט איז דער זהר דארט מבאר וואָס עס שטייט אין פסוק (ביים חטא העגל) „ויתפרקו כל העם את נזמי הזהב אשר באזניהם\"<sup data-n=\"12\">12</sup>\n[דלכאורה: די אידן האָבן דאָך מיטגענומען פון מצרים אַ סך זהב, פארוואָס־זשע האָבן זיי געדאַרפט אָפּ־געבן צוליבן עגל די תכשיטי זהב וואָס זיי האָבן געטראָגן אויף זיך אליין — „נזמי הזהב אשר באזניהם\"?]\n— ווייל זיי האָבן שוין פריער, בעת נדבת המשכן, אפגעגעבן דאָס גאַנצע גאלד פאַרן משכן, ובמילא איז ביי זיי שפעטער, ביים חטא העגל, גע־בליבן נאָר דער זהב פון די תכשיטים וואָס זיי האָבן געטראָגן אויף זיך.\nאַ צווייטע דיעה איז פאַראַן — פארקערט: ניט בלויז נדבת המשכן בפועל ממש, נאָר אויך דעם אוי־בערשטנס ציווי „ועשו לי מקדש ושכנתי בתוכם\"<sup data-n=\"13\">13</sup>, איז געווען ביום הכפורים (ד.ה. נאָך חטא העגל), „כדי שידעו כל האומות שנתכפר להם מע־שה העגל\"<sup data-n=\"14\">14</sup>.\nאון ס׳איז דאָ אַ דריטע דיעה וואָס האַלט, אַז פון דעם אויבערשטן, איז דער ציווי „ועשו לי מקדש\" געזאָגט געווארן פאַרן חטא העגל, אָבער די אידן האָבן [געהערט דעם ציווי פון משה רבינו און] געבראַכט די נדבות המשכן ערשט נאָך יום הכפורים<sup data-n=\"15\">15</sup>.\nוויבאַלד אַז „אלו ואלו דברי אלקים חיים\"<sup data-n=\"16\">16</sup>, איז פארשטאַנדיק: הגם אַז",[["8","8","רבה. אבל י״ל שהמעלה ד„כסף\" (שבמדרש שם) הוא (כפי׳ המהרז״ו שם) שהוא „טוב ל־הוצאה\" (וראה לקמן סעיף ו). ולפ״ז אי״ז שייך לנדו״ד, כי מה שנוגע במקדש הוא מעלת העשירות. וראה הערה הקודמת."],["9","9","פסחים קיט, א."],["10","10","ואין לומר שהיו כאלו מישראל שלא הי׳ להם זהב וכסף, ובהיות שבנדבת המשכן הי׳ כל אחד צריך להשתתף, לכן עשאו כמה דברים מנחשת — — שהרי אמרו רז״ל (בכורות ה, ב. וכ״ה גם בתנחומא בשלח כה. הובא גם בפרש״י בא יג, יג) „שאין לך כל אחד ואחד מישראל שלא היו עמו תשעים חמורים לובים (מער־לים — פרש״י בבכורות) טעונים מכספה וזהבה של מצרים\"."],["11","11","ח״ב רכד, א."],["12","12","תשא לב, ג."],["13","13","פרשתנו כה, ח."],["14","14","תנחומא פרשתנו ח. וראה גם רש״י תשא לא, יח. לג, יא."],["15","15","זח״ב קצה, א. רמב״ן ר״פ ויקהל."],["16","16","עירובין יג, ב. וש״נ."]]],[1300061165,"ביים משכן גשמי איז פארגעקומען בלויז ווי איינע פון די דריי דיעות, זיינען אָבער אַלע דריי דיעות אמת („דברי אלקים חיים\") און זיי זיינען פאַראַן אין דעם עיקר און דעם פני־מיות פון משכן — אין דעם משכן רוחני, אין „ועשו לי מקדש ושכנתי בתוכם\" — וכדלקמן.\nג. לאחר מ״ת (פאַר דעם חטא ה־עגל) זיינען אַלע אידן געווען אין דער מדריגה פון צדיקים. וואָרום טראָץ דעם וואָס פריער — אין מצרים — זיינען זיי געווען אין אַ מצב וואָס „אלו עובדי ע״ז ואלו כו׳\"<sup data-n=\"17\">17</sup> — האָט אָבער יציאת מצרים און מ״ת אין זיי אויפגעטאָן דעם ענין פון גירות<sup data-n=\"18\">18</sup>. און ווי־באַלד אַז „גר שנתגייר כקטן שנולד\"<sup data-n=\"19\">19</sup> — איז ניט פאַרבליבן ביי זיי קיין שום רושם פון דעם ניט־גוטן עבר. [און נאָך מער: אפילו דער רו־שם לא טוב פון דעם גאָר ווייטן עבר, די זוהמא וואָס איז געווען באַ אַלע מענטשן פון זינט חטא עה״ד, איז באַ זיי נפסק געווארן בעת מתן תו־רה<sup data-n=\"20\">20</sup>].\nדערנאָך, זיינען זיי באַגאַנגען אַ חטא און נאָך אַ חטא חמור ביותר — דעם חטא העגל וואָס איז דער שרש<sup data-n=\"21\">21</sup> צו אַלע (שפעטערדיקע) חטאים.\nובכן קומט אויס, אַז נאָך יוהכ״פ (ווען דער אויבערשטער האָט געזאָגט\n„סלחתי כדברך\"<sup data-n=\"22\">22</sup>) זיינען זיי געווארן אין דער מדריגה פון בעלי תשובה.\nאון אין דעם באַשטייט דער חילוק צווישן די דריי דיעות הנ״ל:\nלויט דער דיעה, אַז אויך נדבת המשכן איז פארגעקומען פארן חטא העגל, קומט אויס, אַז עשיית המשכן ווערט דורכגעפירט דורך צדיקים;\nלויט דער דיעה וואָס זאָגט, אַז אויך דער ציווי איז געווען ערשט ביום הכפורים „כדי שידעו . . שנתכפר להם כו׳\", קומט אויס אַז דער גאַנ־צער ענין פון אויפמאַכן אַ משכן — איז פון אָנהייב ביזן סוף פאַרבונדן מיט בעלי תשובה;\nאון לויט דער דיעה אַז דער חטא העגל איז פארגעקומען צווישן דעם ציווי אויף עשיית המשכן און דעם דורכפירן עס בפועל — ד.ה. אַז דער ציווי איז געבליבן בתקפו אויך דעם גאַנצן משך הזמן וואָס צווישן דעם חטא און יוהכ״פ (וואָרום אויב דער ציווי וואָלט צוליבן חטא בטל געווארן, וואָלט שפעטער געמוזט קו־מען אַ נייער ציווי<sup data-n=\"23\">23</sup>) — קומט אויס אַז אויך רשעים האָבן אַ שייכות צו מאַכן אַ „מקדש\" און דורך דעם פועל זיין דעם ענין פון „ושכנתי בתוכם\".",[["17","17","זח״ב קע, ב. ילקוס ראובני בשלח יה, כז."],["18","18","יבמות מו, א־ב."],["19","19","שם כב, א. וש״נ."],["20","20","שבת קמו, רע״א. זח״א נב, ב. ועוד."],["21","21","שלכן וביום פקדי (על איזה חטא שיהי׳) ופקדתי גו׳ (תשא לב, לד), וכמרז״ל אין לך כל פורענות כו׳ של עגל (סנה׳ קב, א. וראה גם רש״י תשא שם)."],["22","22","רש״י תשא לג, יא."],["23","23","ראה רא״ם תשא לא, יח שהוכחת רש״י ש„מעשה העגל קודם לציווי מלאכת המשכן\", מזה ש„בי״ז בתמוז נשתברו הל־חות וביוהכ״פ נתרצה הקב״ה לישראל\" [אף שמצד סדר המאורעות אפ״ל שציווי הקב״ה למשה בנוגע למלאכת המשכן הי׳ לפני חטא העגל ורק ציווי משה לישראל עד״ז הי׳ לאחרי יוהכ״פ, והפרשיות נאמרו עפ״ז כסדרן] היא — כי באם ציווי הקב״ה הי׳ לפני חטא העגל, מנין ידע משה שהריצוי ביוהכ״פ הי׳ גם בנוגע להמשכן."]]],[1300061166,"ד. די הוראה אין עבודה, וואָס מ׳קען אַרויסלערנען פון יעדער אייַ־נע פון די דריי דיעות:\nווען אַ איד דערגרייכט צו דער מדריגה פון אַ צדיק, וואָס „אין לו יצה״ר\"<sup data-n=\"24\">24</sup> (בדוגמא ווי די אידן זיי־נען געווען בעת מ״ת, וואָס „פסקה זוהמתן\"), קען ער ביי זיך טראַכטן: וויבאַלד ער שטייט אין אַזא דרגא נעלית, וועט ער זיך בעסער פאַר־נעמען בלויז מיט ענינים רוחניים און זיך אָפזונדערן פון ענינים גשמיים —\nאָט די אידן וואָס זיינען נידעריקער פון זיין מדריגה (מדריגת צדיק), היות אַז זיי האָבן צו טאָן מיט עניני ה־עולם, דאַרף ביי זיי זיין די עבודה פון „ועשו לי מקדש\" — אויפמאַכן פון זייערע ענינים גשמיים אַ דירה צום אויבערשטן, דורך „בכל<sup data-n=\"25\">25</sup> דרכיך דעהו\". וואָרום ווען זיי זאָלן עס ניט טאָן, קענען זיי ח״ו איינגעזונקען ווערן אין די ענינים פון עוה״ז — פריער אין דברים המותרים — און פון זיי דערנאָך אראָפפאַלן אין ענייני איסור ח״ו<sup data-n=\"26\">26</sup>. ער אָבער איז אנדערש: ער איז דאָך אַ „צדיק\" — טאָ צוליב וואָס זאָל „ער\" זיך פארנעמען מיט דער עבודה פון „ועשו לי מקדש\" פון די דברים הגשמיים? — מה לו ולגש־מיות!\nאויף דעם איז די הוראה פון דער ערשטער דיעה, אַז אויך ווען אידן זיינען געשטאַנען אין דער מדריגה\nפון „פסקה זוהמתן\", האָט זיי דער אויבערשטער אַנגעזאָגט „ועשו לי מקדש\" — אַז מען זאָל זיך פארנע־מען מיט עניני עוה״ז בכדי צו שאַפן פון זיי אַ דירה לו ית׳.\nאון בעת מען זונדערט זיך אָפּ פון גשמיות, איז לבד זאת וואָס דערמיט פארפעלט מען צו מקיים זיין דעם ציווי פון „ועשו לי מקדש\" (און מען פירט במילא ניט אויס די כוונה פון „נתאווה הקב״ה להיות לו ית׳ דירה בתחתונים\"<sup data-n=\"27\">27</sup>) — קען עס אויך ברענ־גען צו נאָך ערגער:\nהיות אַז זיין נשמה איז פארט אַנ־געטאָן אין אַ גוף גשמי און ער מוז בעל־כרחו אַנקומען צו ענינים גשמיים — איז ווייבאַלד זיין גאַנצע אריין־געטאַנקענקייט איז נאָר אין „רוחניות\" און פארנעמט זיך אינגאַנצן ניט מיט בירור וזיכוך פון די דברים גשמיים — דאָן קען זיין גשמיות סוכ״ס ווערן אַ זאַך וואָס איז אויך היפך ח״ו פון תכלית הרצוי׳. אַזוי ווי מען געפינט ביים זהב וואָס מ׳האָט געגעבן פארן משכן, אַז ווען מ׳וואָלט עס ניט אַ־ווועקגעגעבן אין משכן — וואָלט מען אים ר״ל וח״ו גענוצט פארן עגל.\nקען מען דאָך מיינען, לאידך גיסא, אַז דוקא אַ צדיק מוז אַנקומען צו דער עבודה פון „ועשו לי מקדש\", בכדי צו באווארענען אַז זיינע ענ־ינים גשמיים זאלן ח״ו ניט ווערן דער היפך פון טוב וקדושה;\nמשא״כ אַ בעל תשובה, וויבאַלד ער שטייט אין אַ תנועה פון תשובה, פון דערוויטערן זיך פון רע, און ער זאָגט דערויף (אויף די דברים הא־",[["24","24","<a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא פ״א</a>. ובכ״מ."],["25","25","משלי ג, ו. וראה לקו״ש ח״ג ע׳ 907, שהחידוש שב„ועשו לי מקדש\", הו״ע „בכל דרכיך דעהו\" (שידיעת אלקות תהי׳ בדרכי האדם עצמם) שלמעלה מ„וכל מעשיך יהיו לשם שמים\"."],["26","26","ראה קונט׳ ומעין מ״ב פ״א. ד״ה למען דעת תר״ץ. ובכ״מ."],["27","27","תנחומא נשא טז. וראה לעיל ע׳ 17 הערה 42."]]],[1300061167,"סורים) „אי אפשי\"<sup data-n=\"28\">28</sup> — ער דאַרף קיין באווארענעניש ניט האָבן —\nאויף דעם קומט די הוראה פון דער צווייטער דיעה, אַז אדרבה: דו־קא ביוהכ״פ, אין דעם ערשטן זמן פון „סלחתי כדברך\" — ערשט דאָן איז געקומען דער ציווי פון עשיית המש־כן, וויל אין דעם איז תלוי די שלי־מות (התשובה ו)הכפרה.\nמען קען נאָך אָבער אַלץ טראַכטן, אַז בכדי צו אָנהויבן טאָן די עבודה פון „ועשו לי מקדש\". דאַרף מען פריער טאָן אַ תשובה שלימה און פועל׳ן דעם „סלחתי כדברך\"; אָבער ביז דאָן — איז „ולרשע<sup data-n=\"29\">29</sup> אמר אלקים מה לך לספר חוקי\".\nאויף דעם איז די הוראה פון דער דריטער דיעה, אַז דער ציווי „ועשו לי מקדש\" איז ניט נתבטל געווארן אויף קיין אין רגע ח״ו, און אויך קודם התשובה קען מען און מ׳דאַרף מקיים זיין דעם ציווי „ועשו לי מק־דש\" און דורכדעם פועל זיין סוכ״ס דעם קיום פון „ושכנתי בתוכם\". וכ־פסק אדמו״ר הזקן<sup data-n=\"30\">30</sup>, אַז אויך אַ רשע דאַרף לערנען תורה (און מקיים זיין מצות), וואָרום סוכ״ס איז „המאור<sup data-n=\"31\">31</sup> שבה מחזירו למוטב\".\nה. דער פנימיות׳דיגער פירוש פון „אלו ואלו דברי אלקים חיים\" מיינט ניט בלויז, אַז יעדער פון די (דריי)\nדיעות איז אמת, נאָר אויך, אַז בפני־מיות זיינען זיי אלע אין ענין — ווייל „נתנו מרועה אחד א״ל אחד נתנן כו׳\"<sup data-n=\"32\">32</sup>.\nאיז במילא פארשטאַנדיק, אַז די דריי דיעות הנ״ל זיינען ניט בלויז דריי באַזונדערע הוראות פאַר די דריי סוגים פון אידן — אַ באַזונדער הו־ראה פאַר צדיקים, וכו׳: נאָר נאָך מער: די אַלע דריי דיעות (און הו־ראות) זיינען אויך פאַראַן אין איין און דעם זעלבן משכן.\nדערפאַר זעט מען, אַז אין ארון — וואָס „עיקר החפץ במשכן הוא מקום מנוחת השכינה שהוא הארון\"<sup data-n=\"33\">33</sup> — האָבן זיך אויסגעדריקט אַט די אַלע דרײ׳ ענינים הנ״ל: אין ארון זיינען געווען די (שברי) לוחות הראשונות<sup data-n=\"34\">34</sup> — די דרגא פון אידן ווי זיי זיינען געווען קודם החטא (צדיקים). אָבער, פון דער צווייטער זייט, זיינען עס דאָך געווען שברי לוחות, וואָס שבירת הלוחות איז געקומען צוליב דער סיבה פון חטא העגל *34 — דעריבער ווייזט עס אַז אין ארון איז דאָ אַן אָרט אויך פאַר די אידן וואָס באַ זיי זיינען צו־בראָכענע לוחות, ווי אידן זיינען גע־ווען לאחרי החטא; און אין ארון זיי־נען געווען אויך די לוחות שניות 34 שניתנו ביוהכ״פ, די דרגא (פון בעלי",[["28","28","ראה לקו״ת ואתחנן ט, ד (בשם הה״מ)."],["29","29","תהלים נ, טז."],["30","30","הל׳ ת״ת לאדה״ז (פ״ד ה״ג). וראה שם בקו״א, שי״ל שגם הרב צריך ללמד אותו. עיי״ש."],["31","31","ירוש׳ חגיגה פ״א ה״ז (לגירסת קה״ע שם. ובמ״כ לאיכ״ר — שכן מצא בירוש׳ כתיבת יד). איכ״ר פתיחתא ב."],["32","32","חגיגה ג, ב."],["33","33","רמב״ן ר״פ תרומה."],["34","34","ב״ב יד, ב. *34) באופן אחר קצת: בלוחות ה־ראשונים שבארון היו ב׳ ענינים: 1) וה־לוחות מעשה אלקים המה (תשא לב, טז) — וזה לא נשתנה ע״י השבירה; 2) והמכתב מכתב אלקים הוא חרות גו׳ — והמכתב (התיבות וכו׳) בטל ע״י השבירה (בפרט ע״פ מרז״ל (תיב״ע לב, יט. ועוד) שהכתב פרח)."]]],[1300061168,"תשובה<sup data-n=\"35\">35</sup> ווי אידן זיינען געווען נאָך דעם זמן פון „סלחתי כדברך\".\nאון דאָס איז אויך דער ביאור וואָס דער משכן וכליו האָבן געמוזט זיין ניט אויסשליסלעך פון זהב, נאָר אויך פון כסף און אפילו פון נחשת — ווייל אָט די דריי מינים זיינען מרמז אויף די דריי סוגים הנ״ל פון אידן (כד־להלן ס״ט), און זיי אלע דאַרפן זיין און זיינען פארבונדן מיטן משכן, כנ״ל.\nו. דער חילוק צווישן אָט די דריי מינים: זהב, כסף און נחשת — ווי ער איז מוסבר בפנימיות הענינים — שפיגלט זיך אָפּ (ווי אלע ענינים פון פנימיות התורה) אויך אין נגלה דתורה, ביז אין אַ הלכה למעשה:\nבנוגע צו זהב און כסף זאָגט די גמרא<sup data-n=\"36\">36</sup>, אַז יעדערער פון זיי פאר־מאָגט אין זיך אַ מעלה לגבי דעם צווייטן: די מעלה פון זהב איז אין דעם וואָס ער איז מער „חשוב\" פון כסף; און די מעלה פון כסף איז וואָס ער איז „חריף\" — „יוצא<sup data-n=\"37\">37</sup> בהוצאה ועובר לסוחר\". און דעריבער זיינען פאַראַן צוויי דיעות, ווען מען שאַצט\nכסף וזהב איינער לגבי דעם צווייטן. ווער פון זיי (וועגט איבער און) איז „טבעא\", און ווער „פירא\": אין דיעה איז, אַז ווייל זהב איז „חשוב׳ער\" הייסט ער דערפאַר „טבעא\" — לגבי כסף; און אַ צווייטע דיעה האַלט (און אַזוי איז די הלכה<sup data-n=\"38\">38</sup>), אַז אויך לגבי זהב איז כסף טבעא דערפאַר וואָס ער איז „חריף\".\n[און אויסער דעם, וואָס די הלכה בלייבט ווי די צווייטע דיעה אַז כסף איז „טבעא\" לגבי זהב (ווייל צו „טב־עא\" איז בעיקר נוגע דער פרט פון „חריף\"), איז נוסף דערצו פאַראַן אַ לכל־הדיעות יקע צד־מעלה אין כסף לגבי זהב: וואָרום אפילו לויט דער דיעה אַז כסף איז „פירא\" לגבי זהב, איז אבער אַ דבר פשוט אַז לגבי (פירות ממש אדער לגבי) זיך אליין הייסט ער נאָך אַלץ „טבעא\"<sup data-n=\"39\">39</sup>; משא״כ בנוגע זהב, איז פאַראַן אַ דיעה<sup data-n=\"40\">40</sup> אַז ער איז „פירא\" אפילו (לגבי פירות ממש אדער) לגבי זיך אליין].\nאָט די צוויי דיעות זיינען בלויז בנוגע דעם יחס פון זהב און כסף צווישן זיך. בנוגע נחושת, אָבער, האַלטן אלע אַז נחושת איז „פירא\" לגבי כסף<sup data-n=\"41\">41</sup> און (לויט כמה שיטות<sup data-n=\"42\">42</sup>, און אַזוי איז אויך די הלכה<sup data-n=\"43\">43</sup> אויך",[["35","35","גם י״ל, שלאחרי יוהכ״פ היו במד־ריגת „בינונים\" ש„היא מדת כל אדם ואחרי׳ כל אדם ימשוך\" (<a class=\"ft-cite\" href=\"#/read/tanya/3401310019\" data-slug=\"tanya\" data-id=\"3401310019\">תניא</a> רפי״ד), שהרי גם אחר הסליחה דיוהכ״פ נשארה הזוהמא ד־חטא עה״ד — ובדוגמת בינוני שיש לו יצה״ר ורק שאינו עובר ח״ו במחדרומ״ע. ועפ״ז י״ל ענין ג׳ הדיעות שבמשכן (באו״א): בנדבת המשכן היו צריכים להש־תתף „כל עדת בני ישראל\" [ובאופן ד־„ויקהל\", שכולם יהיו לקהל וציבור אחד — ראה לקמן ע׳ 217־8 ובהנסמן שם], ומכיון שב„עדת בני ישראל\" ישנם כל ג׳ סוגים אלו [וכמדובר במ״א ש„צבור\" הוא ר״ת צדיקים בינונים ורשעים] — ע״כ צ״ל כל ג׳ הדיעות."],["36","36","ב״מ מד, סע״א ואילך."],["37","37","רש״י שם, ריש ע״ב."],["38","38","שו״ע חו״מ סר״ג ס״ד."],["39","39","ראה ב״מ שם, ב: אע״ג דכספא לגבי דהבא פירא הוי לגבי טבעא הוי. ושם מה, רע״א: לגבי נפשי׳ מי איכא למ״ד לאו טבעא הוי."],["40","40","שם מד, ב. מה, א."],["41","41","ראה שם מד, ריש ע״ב שגם לשיטת ילדותי׳ דרבי (שהכסף קונה את הזהב), הנחשת קונה את הכסף. וכ״ה בירוש׳ ב״מ רפ״ד."],["42","42","הדיעות בזה — ראה טור וב״י חו״מ שם."],["43","43","דיעה השני׳ בשו״ע שם ס״ה. וראה"]]],[1300061169,"לגבי זהב — נחושת איז נידעריקער אין מעלה פון זיי ביידע<sup data-n=\"44\">44</sup>. און הגם נחשת איז מער חריף פון זהב, פונ־דעסטוועגן קען די „חריפות\" פון נחשת ניט איבערוועגן די חשיבות פון זהב\n— וואָרום דאָס וואָס בנוגע דער הג־דרה פון „טבעא\" איז להלכה „חריף\" ויכטיקער ווי „חשיב\", כנ״ל — איז דאָס דוקא ביי כסף, וואָס אויסער די „חריפות\" פארמאָגט ער אויך אַ חשי־בות (הגם ניט אַזוי גרויסע ווי ביי זהב — אָבער צוזאַמען מיטן יתרון פון חריפות איז דאָס מכריע). משא״כ נחשת, וואָס האָט כלל ניט קיין חשי־בות (מיוחדת), איז דאָ בלויז „חרי־פות\" און דאָס איז ניט גענוג צו אי־בערווענן די „חשיבות\" פון זהב 45.\nז. אלע ענינים אין גשמיות נעמען זיך פון דעם וואָס זיי זיינען פאַראַן, אין אַ רוחניות׳דיקן אופן, אין זייער מקור — און ווי דער לשון פון אלטן רבי׳ן<sup data-n=\"46\">46</sup>: „שנשתלשלו מהן\". דערפון איז פארשטאַנדיק, אַז דער חילוק הנ״ל (בגשמיות) צווישן זהב און כסף (וואָס די מעלה פון זהב איז בלויז אין חשי־בות, ער איז אָבער ניט „עובר ל־סוחר\"; דאָקען איז כסף ניט אַזוי חשוב ווי זהב, אָבער ער האָט דער־פאַר די מעלה פון „עובר לסוחר\") שטאַמט דאָס פון דעם וואָס אין\nרוחניות הענינים איז בחינת „זהב\" חשוב׳ער, העכער פון וועלט [און ווי עס שטייט אין מדרש<sup data-n=\"47\">47</sup>: לא הי׳ העולם ראוי להשתמש בזהב כו׳], און דערפאַר איז ער ניט אַזוי „עובר לסוחר\"; און די בחינה פון „כסף\" איז ניט אַזוי חשוב, ד.ה. אַ מדריגה נעלית אבער ניט העכער פון עולמות — און ווייל די מעלה וחשיבות פון בחי׳ כסף האָט אַ שייכות צו וועלט, דערפאַר איז עס „עובר לסוחר\".\nדערפון איז פארשטאַנדיק, אַז בחי׳ נחושת, וואָס האָט אין זיך ניט קיין חשיבות, אויך ניט די חשיבות פון „כסף\", איז זי אין עולם גופא אַ ני־דעריגע מדריגה.\nאון דאָס איז אויך מתאים דערמיט וואָס „נחושת\" איז פון לשון „נחש\"<sup data-n=\"48\">48</sup>, וועלכער האָט געבראַכט דעם חטא עה״ד (דער שרש<sup data-n=\"49\">49</sup> פון אַלע חטאים) — ווייל דער ענין פון „נחושת\" ווייזט אַ נידעריקייט אין עניני העולם גופא<sup data-n=\"50\">50</sup>.\nח. מען דאַרף אָבער פארשטיין: לפי הנ״ל, אַז דאָס וואָס זהב איז ניט „חריף\" איז עס גאָר מצד זיין מעלה און חשיבות (וואָס ער איז אַ גאָר הויכע מדריגה — ביז אַז, כנ״ל, לא",[["","","יד מלאכי כללי השו״ע כלל יג: „כשכותב בש״ע יש אומרים ויש אומרים נקטינן כ־סברא שניי״. — הובא ב„מודעה רבה\" מארנ״ע — נדפס בסדור אדה״ז, בהוספות שכב, א. עיי״ש."],["44","44","ראה רא״ש ב״מ שם (הובא בב״י שם): דאחרון אחרון גרוע כו׳."],["45","45","רא״ש שם — הובא בב״י וסמ״ע (לשו״ע) שם."],["46","46","<a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא רפ״ג</a> (לענין עשר בחי׳ שב־נפש — שנשתלשלו מע״ס העליונות)."],["47","47","פרשתנו רפל״ה. ב״ר פט״ז, ב. וראה שם: ולמה נברא בשביל המשכן כו׳."],["48","48","ראה ב״ר פל״א, ח ורש״י חקת כא, ט (בענין „נחש נחשת\". ולהעיר מזח״ב (קמח, ב), שהנחשת דמשכן שייך לנחש נחשת), תקו״ז תס״ו — הובא באוה״ת תרומה ע׳ א׳תנג. ולהעיר גם מביאוה״ז להצ״צ ע׳ שב. וראה הערה 51 — בשוה״ג."],["49","49","ראה בהנסמן בהערה 20. ונתבאר בארוכה בד״ה ע״כ יאמרו המושלים תרצ״א (סה״מ קונטרסים ח״א קצב, א ואילך)."],["50","50","וי״ל שזהו גם הביאור בפנימיות הענינים לזה שהנחשת אינו חריף (כ״כ) — שזהו ע״ד מה ש„מקום ומשכן הקליפות נק׳ שם\" (לקו״ת ראה לב, רע״ב. עיי״ש)."]]],[1300061170,"הי׳ העולם (כולל אויך כסף) ראוי להשתמש בזהב) — פארוואָס ווערט ער גערעכנט בלויז ווי „פירא\" לגבי כסף וואָס איז אַזוי פיל נידע־ריגער פון אים?\nאיז דער ביאור אין דעם:\nדער חילוק צווישן זהב און כסף אין די „ספירות\" למעלה — און אין מדות הנפש: „זהב\" איז בחי׳ גבורה און „כסף\" בחי׳ חסד 51. און אין עבודת האדם, איז עס דער אונטערשייד צווישן עבודת הצדיקים און עבודת הבעלי תשובה: עבודת הצדיקים איז המשכה 52 מלמעלה למטה — חסד און כסף; און עבודת הבעלי תשובה איז העלאה 53 מלמטה למעלה — גבורה און זהב 54.\nוואָס דאָס איז אויך מתאים מיט דעם וואָס בחי׳ זהב איז העכער פון וועלט און בחי׳ כסף איז דער תכלית העילוי וואָס אין וועלט גופא: עבודת התשובה (העלאה מלמטה למעלה) איז ענינה בכללות — אַרויסגיין פון\nוועלט 55, אומקערן זיך צום מקור; און עבודת הצדיקים איז — צו ממ־שיך זיין (דורך תומ״צ) אלקות אין וועלט 56.\nאון היות אַז די כוונה עליונה ווערט אויסגעפירט דוקא אין המשכת אלקות למטה [וואָס דערפאַר שטייט „נשמ־תן 57 של צדיקים שבהם נמלך כו׳\"], דעריבער ווערט אפגע׳פסק׳נט אין תורה אַז די „חריפות\" פון כסף וועגט אריבער די „חשיבות\" פון זהב.\nונוסף לזה: די תנועה פון העלאה מלמטלמ״ע, וואָס אין תשובה, איז ניט אויסגעשטעלט אין אַן אופן קצוב, וואָרום [לבד זאת וואָס זי איז תלוי אין דעם הרגש פון יעדן אדם פרטי, איז אויך] ענינה איז — אַרויסצוגיין פון הגבלה; משא״כ עבודת הצדיקים, די עבודה פון תומ״צ, איז אין אַן אופן פון מדידה וכו׳ 58. און דערפאַר איז דין אַז „זהב\" איז „פירא\" און „כסף\" איז „טבעא\", ווייל 58 די",[["51","51","ראה זח״א רנ, א. ח״ב קמח, א־ב. רכה, ב. וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310055\" data-slug=\"tanya\" data-id=\"3401310055\">תניא פ״נ</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370498\" data-slug=\"torah-or\" data-id=\"3901370498\">תו״א קיא, ד</a>. ובכ״מ. (ולהעיר שבזח״ב ובתו״א שם, מדובר בענין זהב וכסף שבמשכן *)."],["52","52","ראה ד״ה תקעו תרס״א. ובכ״מ."],["53","53","להעיר מ<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450534\" data-slug=\"or-hatorah-hb\" data-id=\"8316450534\">אוה״ת עקב ע׳ תקלד</a> (וראה גם דרמ״צ לז, ב), שמה שזהב נק׳ „פירא\" וכסף „טבעא\" הוא — לפי שזהב הוא העלאה, מ״ן וכסף המשכת מ״ד. עיי״ש. *) בתו״א שם: זהב — עבודה, כסף — גמ״ח, נחשת — תורה. אבל אין מזה סתירה למש״כ בפנים — כי מה שתורה היא נחשת „היינו שהיא הבירור של נחשת\" (אוה״ת תשא ע׳ א׳תתמו. שם ע׳ תתפח — הגהות וכו׳ לתו״א הנ״ל), אבל נחשת עצמה מורה לקליפה, כמבואר באוה״ת שם. ולהעיר מאוה״ת תרומה שם, שגם בקליפות — בחי׳ נחשת היא למטה מזהב וכסף."],["54","54","בדוגמת האהבה ד„כמעלת הזהב על הכסף כו׳\" שעניינה הוא — „ליפרד מה־עצים והפתילה\" (תניא שם)."],["55","55","להעיר מהידוע (ד״ה שה תמים תרכ״ט (בסופו). מלכא ומלכתא תרצ״ז) בביאור פלוגתת מלכא ומלכתא אי אימרא יאי או גדיא יאי (פסחים נז, סע״א), ד„אימרא\" הוא עבודת הצדיקים ו„גדיא\" — עבודת הבע״ת. ולכן אמרה מלכתא אימרא יאי, כי „מלכתא\" היא בחי׳ המלכות שרש בי״ע, וההמשכה בבי״ע הוא ע״י עבודת הצדיקים דוקא. וע״פ המבואר בפנים שצדיקים ובע״ת הם בחי׳ כסף וזהב, קו הימין וקו השמאל — אולי י״ל שזהו״ע מה שאמר מלכא (שם, ריש ע״ב) „ניפסקו לימיני׳\" — כי קצף על מה שמשבח העבודה ד„אימרא\" שמקו הימין."],["56","56","רות רבה פ״ב, ג. ב״ר פ״ח, ז."],["57","57","ראה אגה״ק ס״י. ובכ״מ."],["58","58","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011194\" data-slug=\"likkutei-sichot\" data-id=\"1300011194\">לקו״ש ח״א ע׳ 180</a>, ש־"]]],[1300061171,"תכונה פון „טבעא\" באַשטייט אין דעם וואָס זיין וערט איז קצוב 59, באַ־שטימט, אומגעענדערט 60.\nט. און דאָס איז אויך דער ביאור פון דער שייכות צווישן די דריי סוגים — זהב כסף און נחשת — צו די דריי דרגות האדם פון אידן: ווי זיי זיינען געווען קודם חטא העגל, לאחרי החטא און לאחרי יוהכ״פ:\n„זהב\", וואָס איז מרמז אויף תשובה, איז די בחינה ווי אידן זיינען געווען נאָך יוהכ״פ; „כסף\", עבודת הצדיקים — דאָס איז די דרגא ווי זיי זיינען געווען קודם החטא; און נחשת, פון לשון „נחש\" — ווייזט אויפן מצב ווי זיי זיינען געווען אין דעם זמן וואָס צווישן חטא העגל און יוהכ״פ, ווייל דער חטא העגל איז בדוגמת חטא עה״ד 61 וואָס איז געקומען דורכן נחש הקדמוני.\nי. די הוראה דערפון בעבודתנו איז:\nעס זיינען פאַראַן אַזעלכע וואָס האַלטן (אָדער ס׳איז באמת אַזוי) אַז זיי זיינען אין דער דרגא פון „זהב\" און „כסף\", און דעריבער ווילן זיי זיך אָפּזונדערן פון אַנדערע אידן וועל־כע זיי האַלטן פאַר מדריגת „נחשת\".\nאיז לו יהא כדבריהם, אַז זיי זיי־נען דער „זהב\" און „כסף\", און די אַנדערע זיינען „נחשת\", דאַרפן זיי אבער וויסן אַז בכדי ביי זיי זאָל זיך אויפפירן דער ענין פון „ושכנתי ב־תוכם\", מוזן זיי זיך פארבינדן און פאראייניקן 62 מיט די אידן וועלכע זיינען אין דער בחינה פון „נחשת\"; פון זהב און כסף אליין קען מען קיין משכן ניט אויפשטעלן.\nולאידך גיסא, איז דאָ פאַראַן אַ הוראה פאַר די אידן וועלכע האַלטן זיך פאַר בחי׳ „נחשת\". זיי קענען דאָך טראַכטן: מי אני ומה אני לגשת אל הקודש? דארפן זיי וויסן, אַז אויך „נחשת\" איז געווען אַ טייל פון משכן, ואדרבה: ס׳איז נאָך פאַראַן אַ מעלה אין „נחשת\" לגבי „כסף\" און „זהב\":\nא) די אדנים וועלכע האָבן אופ־געהאלטן דעם חצר המשכן\n[וואָס דערמיט האָט זיך אָנגעהויבן און אויפגעטאָן די הבדלה בין קודש לחול 63 (משא״כ די חילוקי המדריגות",[["","","58 המשך) „מטבע\" הו״ע „שוב\" — המשכה למטה. ושם, שהשייכות ד„מטבע\" ל„שוב\" היא [לא רק מצד זה שמטבע אינה משתנית, כ״א] גם לפי שמטבע הוא מלשון „טבע\", וענין „שוב\" הוא ההמשכה למטה בלבושי הטבע."],["59","59","ראה ב״מ מד, ב: טבעא הוי משער תנא במידי דקיץ."],["60","60","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380635\" data-slug=\"likkutei-torah\" data-id=\"4001380635\">לקו״ת פנחס (עח, ד</a>), שמה שקרבן תמיד צ״ל כבש דוקא (המורה ל־עבודת הצדיקים — ראה גם לעיל הערה 55) הוא — כי „תשובה אינה אלא לפי שעה אבל בתמידות צ״ל בחי׳ צדיק\" — והרי גם „טבעא\" שאינה משתנית הוא כענין התמידות."],["61","61","שלכן חזרה אז הזוהמא דחטא עה״ד (ראה זח״א נב, ב. ועוד), ולכו״כ דעות הרי לולא חטא העגל היו בנ״י „חרות ממלאך המות\" (ע״ז ה, סע״א. שמו״ר פמ״א, ז. ובכ״מ. ובזו״ח רות (פג, ג) סתם כדעת אלו) — ע״ד חטא עה״ד בנוגע לכל העולם."],["62","62","להעיר מענין „ויקהל\" (ראה לעיל הערה 35), שההתכללות ד„קהל\" הוא [לא רק שכולם נאספים במקום אחד ולמטרה אחת, כ״א] שנעשים מציאות אחת (ראה בארוכה לקמן ע׳ 217 ואילך)."],["63","63","להעיר שהכיור וכנו, שתכליתם רחיצה קודם שיקרבו לשרת בקודש (ראה רמב״ן תשא ל, יט) נעשו נחשת, וראה לקמן ע׳ 196 ואילך."]]],[1300061172,"פון חצר און אינווייניג, ביז צום קדשי־קדשים, זיינען אלץ אין קדושה גופא) — און דער איבערגאַנג פון חול צו קודש איז דאָך אַ מעלה גדולה ביותר 64]\nזיינען געווען פון נחשת 65.\nב) אויך די יריעות המשכן האָבן זיך געהאַלטן דורך „יתדות\" פון נחשת 66, וואָס דוקא דורך זיי איז געווען דער משכן אין אַן אופן פון „אהל 67 בל יצען בל יסע יתדותיו לנצח\" 68.\n(משיחות ש״פ שמיני תשכ״ב, ש״פ ויקהל תש״ל)",[["64","64","ראה ד״ח צו, ריש ע״ב בענין יצי״מ, דאף שאז היתה כנס״י בבחי׳ קטנות שלמטה הרבה מימי הגדלות שלה בימי דוד ושלמה, מ״מ „זהו יותר גדול מכל לפי שכל מה שנגדלת כ״כ הכל הי׳ מכח זה החסד נעוריך דוקא\". ועיי״ש (צד, סע״ג) שזהו כבר שנתגייר, דהגם שעדיין אינו עובד ה׳ בשלימות, הרי תחלת יציאתו מן ההיפך להיפך מגיע בבחי׳ יחידה."],["65","65","פרשתנו כז, י ואילך."],["66","66","סוף פרשתנו. פרש״י שם."],["67","67","לשון הכתוב (ישעי׳ לג, כ) — הובא בפרש״י הנ״ל."],["68","68","פרש״י שם. וראה לקמן בשיחה שלאח״ז."]]],[1300061173,"<h3>תרומה ב</h3>\nא. ביים סיום פון דער סדרה, איז רש\"י מבאר וועגן יתדות¹ (א) ווי אזוי די יתדות זעען אויס — „כמין נגרי נחושת\", (ב) צו וואס זיי האבן גענוצט — „עשויין ליריעות האהל ולקלעי החצר קשורים במיתרים סביב סביב בשיפוליהן כדי שלא תהא הרוח מגביהתן\".\nדערנאך איז רש\"י ממשיך: „ואיני יודע¹* אם תחובין בארץ או קשורין ותלויין וכובדן מכביד שפולי היריעות שלא ינועו ברוח. ואומר אני ששמן מוכיח עליהם שהם תקועין בארץ לכך נקראו יתדות. ומקרא זה² מסייעני אהל בל יצען בל יסע יתדותיו לנצח\".\nאיז אין דעם ניט מובן:\nא) וואס רש\"י זאגט „ששמן מוכיח עליהם שהם תקועין בארץ\"; וואס איז די הוכחה פון דעם נאמען „יתדות\" אז זיי זיינען „תקועין בארץ\"³? און אויב רש\"י נעמט אן, אז פונעם נאמען „יתדות\" האט מען יא א קלארן באווייז אז זיי זיינען „תקועין בארץ\", ווי אזוי זאגט ער אליין פריער „ואיני יודע אם תחובין בארץ\", זאגענדיק בפירוש אז דאס איז ניט באוואוסט?\nלויט אייניקע נוסחאות איז אט דער גאנצער המשך — אנהויבענדיק פון „ואומר אני\" ביז צום סיום — ניט דער לשון פון רש\"י אליין, נאר א הוספה וואס איז צוגעגעבן געווארן דורך זיינעם א תלמיד⁴. אבער אויך לויט די נוסחאות קען מען ניט פארענטפערן, אז ביי רש\"י איז טאקע ניט באוואוסט⁴* צי די יתדות זיינען געווען תחוב בארץ, און ביי זיין תלמיד איז געווען ברור מיט א פשיטות אז דער יתד איז תקוע בארץ — ווארום וויבאלד אז מיט די צוגעגעבענע ווערטער „ואומר אני ששמן מוכיח עליהם כו'\" האט דער תלמיד געמיינט ארויסצוברענגען א בירור אין דעם וואס רש\"י זאגט „ואיני יודע כו'\", פאדערט זיך דאך ער זאל מבאר זיין ווי אזוי דאס איז מוכח פון „שמן\", און ניט בלויז זאגן סתם בפשיטות אז ס'איז דא אזא הוכחה.\nב) נאך דעם ווי רש\"י (אדער זיין",[["1","1","אין לומר כדעת הדפוסים שראיתי — שהדפיסו התיבה „יתדות\" באותיות ובאופן שמדפיסים התיבות שרש\"י מעתיקן מן הכתוב — שזהו ד\"ה חדש על תיבת „יתדות\" שבקרא — דא\"כ הו\"ל לרש\"י להעתיק „יתדותיו\" שקדמה ל„יתדות\". ולכן נ\"ל: א) שרש\"י מבאר דברי עצמו* באותו ד\"ה „לתקוע יתדות\". וכ\"מ בדפוס הא' דפרש\"י שבו תיבת יתדות אינה מובדלת בנקודה לא לפני' ולא לאחרי'** כבשאר תיבות שנעתקו מהכתוב. אלא שעפ\"ז יוקשה ההמשך „נחושת\" „בשיפוליהן\" — שהרי בפרש\"י קורא „יתדות\" גם ל„ווי\" העמודים שהיו מכסף, ולמע' לה. ולכן נ\"ל יותר לומר: ב) דבכת\"י הראשונים דפרש\"י הי' כתוב „יתדותי'\" (וכוונתו ל„יתדותיו\" דקרא — (וכרגילות מעתיקי כת\"י לקצר מלאכתם ע\"י ר\"ת, קו וכיו\"ב)), ואחד המעתיקים החליט שהקו מיותר, שהרי כתוב בקרא יתדות, ולא שם לבו ש„יתדותיו\" קדם לה, ושבשתא כיון דעל על. 1*) בבמדב\"ר (פי\"ב, יט) שהיו נועצים היתדות בארץ. וכנראה שגירסא אחרת הייתה לרש\"י. ובלאה\"כ צ\"ל כן, שהרי לרש\"י (נשא ד, לב) היו יתדות גם במשא בני גרשון, משא\"כ לגירסתנו בבמדב\"ר שהיא כדעת הרמב\"ן (נשא שם). *) עיין פרש\"י ואתחנן ו, ו. **) חח\"י, רק צילום — פאטאסטאט — מדפוס הראשון, ואפשר שאינו ברור כ\"כ, אבל מהריוח שבין התיבות נראה שלא היו בו הנקודות."],["2","2","ישעי' לג, כ."],["3","3","וגם אינו מובן: בשביל מה מסיים „לכך נקראו יתדות\", דלכאורה — מיותר?"],["4","4","יוסף בר שמעון. 4*) ראה ג\"כ לקמן ס\"ג."]]],[1300061174,"תלמיד) זאגט „ששמן מוכיח עליהם שהם תקועין בארץ\", איז ער נאך מוסיף: „ומקרא זה מסייעני כו'\". ולכאורה, אויב ער האט שוין יע דעם באווייז (פון „שמן\") אז יתד איז א זאך וואס ווערט אריינגעזעצט אין דער ערד, איז דאך ניטא קיין הכרח עס זאל זיין א סיוע⁵ פון פסוק⁶?\nג) פארוואס טאקע זאל מלכתחילה זיין א ספק ביי רש\"י צי די יתדות זיינען געווען „תחובין בארץ\" (ובפרט לויטן נוסח אז אט־די ווערטער „ואומר אני כו'\" שטאמען ניט פון רש\"י אליין — ביי אים איז דאס געבליבן בגדר ספק) — בשעת ס'איז פאראן אויף דעם א בפירוש'ע ראי' פון דעם געבראכטן פסוק „אהל בל יצען גו'\"?\nד) אז יתדות שטעלן מיט זיך פאר די זאך פון „תקועין\" (אריינגעזעצט, אריינגעפעסטיקט), זעט מען בפירוש אין כמה וכמה פסוקים „ותתקע את היתד\"⁷; „ותקעתיו יתד במקום נאמן\"⁸ — האט דאך לכאורה רש\"י (אדער תלמידו) געדארפט ברענגען די ראי' פון אט־די פסוקים, ערשטנס, ווייל זיי שטייען (אין תנ\"ך) פריער פון דעם געבראכטן פסוק „אהל בל יצען גו'\"; און, השנית, ווייל אין זיי שטייט בפירוש „ותתקע\"; „ותקעתיו\" אין צוזאמענהאנג מיט „יתד\" — בעת פון דעם פסוק „אהל גו' בל יסע יתדותיו לנצח\" ווערט געבראכט די ראי' (אז די יתדות זיינען „תקועין\") ניט מצד א פירוש'ן לשון, נאר מצד דער משמעות התוכן פון פסוק (וויבאלד עס ווערט געזאגט „בל יסע יתדותיו\", אז די יתדות ווערן ניט אפגערוקט פון ארט, איז מוכח אז זיי זיינען „תקועין\")?\nב. פון דעם וואס רש\"י (א) זאגט בפשיטות „ששמן מוכיח עליהם\" און (ב) ער ברענגט ניט קיין ראי' פון „ותתקע את היתד\" אדער „ותקעתיו יתד\", איז א הוכחה, אז בנוגע די אייגנשאפט פון יתדות אין אלגעמיין — איז ביי רש\"י'ן קיין ספק ניט. ד. ה. מען ווייס אז יתד בכלל איז א זאך וואס ווערט ערגעץ אריינגעשטעקט (אף צו גראבן), אדער אריינגעהאקט און אריינגעפעסטיקט⁹.\nאון דערפאר, איז אויך בנוגע צו די יתדות המשכן, זאגט ער בפשיטות (אויך לויטן פירוש אז די יתדות זיינען ניט געווען תחובין בארץ), אז זיי זיינען געווען „כמין נגרי נחושת\" וואס נגרים — אין לשון הקודש — זיינען אזוינע זאכן וועלכע מען איז ערגעץ־וואו תוקע¹⁰ — ווייל דאס איז דער פירוש פון יתדות,",[["5","5","וגם: הרי הוכחתו שיתדות הם תקו־עין הוא מהתיבות „בל יסע יתדותיו לנצח\", ולמה מעתיק גם „אהל בל יצען\"?"],["6","6","לכאורה אפשר לתרץ קושיות הנ\"ל, שמה שמביא את הפסוק „אהל בל יצען בל יסע יתדותיו לנצח\" הוא לבאר את כוונתו ב„שמן מוכיח עליהם\". אבל — אינו. כי (א) לפי\"ז הוצרך לכתוב „ואומר אני שתקועין הן בארץ ומקרא זה מסייעני כו'\", והתיבות „ששמן מוכיח עליהן\" מיו־תרים. (ב) באם „ומקרא זה מסייעני\" בא בהמשך ל„שמן מוכיח עליהם\", וכוונתו בזה להוכיח שיתדות בכלל הם תקועין, הו\"ל לכתוב „ומקרא זה מסייעני\" בסמיכות ל„ששמן מוכיח עליהם\" בכדי להוכיח שיתדות בכלל הם תקועין, ורק לאחרי זה לסיים „לכך נקראו (אלו שבמשכן בשם) יתדות\". ומזה שכותב „לכך נקראו יתדות\" לפני „ומקרא זה מסייעני\" משמע ש„ומקרא זה מסייעני\" הוא סיוע נוסף ל„ואומר אני\"."],["7","7","שופטים ד, כא."],["8","8","ישעי' כב, כג."],["9","9","כי מכיון שיתד הוא דבר חד — בפשטות לה\"ק (שלכן אין רש\"י מפרש זה בפרי' עה\"ת) — ממ\"ש (תצא כג, יד) „ויתד תהי' לך גו' וחפרת בה\" — והרי בדבר שאינו חד א\"א לחפור, הרי מובן שהוא עשוי (בנוגע לבנין) לתקוע."],["10","10","ראה רש\"י ד\"ה נגר (שבת קכו, א): יתד שתוקעין כו'. ד\"ה ובנגר (ב\"מ קא, ב): ותוחבין אותו כו'. ד\"ה עשאה כמין נגר (מנחות לג, א): שקבעה ותחבה בסף כנגר"]]],[1300061175,"דער ספק איז נאר, צי זיינען זיי — ביים משכן — אויך בפועל געווען תחובין בארץ אדער ניט. און זיין סברא צו זאגן אז זיי זיינען ניט געווען תחובין — כאטש אז ביי אים איז פשוט אז אויך די יתדות המשכן זיינען געווען כמין „נגרי\", ד. ה. זיי האבן אזא צורה (פארם) אז מען קען זיי תוקע זיין:\nהיות דער משכן איז (אין מדבר) ניט געשטאנען בקביעות אויף איין ארט¹¹ און מ'האט אים געדארפט פאנאנדערנעמען¹², איז מער מסתבר אז בכדי אויסצומיידן טרחא יתירה, זאל מען די יריעות און קלעים איינהאלטן דורך דער שווערקייט פון הענגענדיקע יתדות — אידער דורך אן אופן וואס די יתדות זיינען „תחובין בארץ\", און מ'זאל דארפן, ביי יעדער פאנאנדערנעמען, ארויסרייסן די יתדות פון דער ערד און זיי ווידער אמאל אריינזעצן ביים צווייטן מאל צוזאמשטעלן.\nס'איז אבער לויט דעם ניט פארשטאנדיק:\nא) אויב מ'נעמט אן, אז איינהאלטן די יריעות המשכן, האט דער כובד פון די יתדות, האט מען דאך צוליב דעם צוועק איבערהויפט ניט געדארפט נוצן קיין „יתדות\" וואס זייער זאך איז צו טאן אט־די פעולה דורך זיין תקוע בארץ — נאר דורך שווערע זאכן — וואס פאר א צורה זיי זאלן ניט האבן?\nב) וויבאלד אז דער ספק איז (ניט בנוגע די צורת היתדות, נאר) צי בפועל זיינען זיי געווען תחובין, היינט וואס העלפט דא די ראי' פון („שמן\", און עאכו\"כ פון) דעם פסוק „אהל בל יצען בל יסע יתדותיו לנצח\" וואו עס רעדט זיך כלל ניט וועגן משכן?\nג. וועט עס ווערן פארשטאנדיק בהקדים וואס רש\"י זאגט פאר דעם (אין פריערדיקן דיבור המתחיל אין אונזער פסוק)*¹²: „מקבות לתקוע יתדות ועמו־דים\". ולכאורה, ביי רש\"י איז עס דאך (נאך) ניט מוחלט צי די יתדות זיינען געווען תחובין אדער תלויין — ווי אזוי זאגט ער פריער מיט א פשיטות „לתקוע יתדות\"?\nמוז מען דאך זאגן, אז עס זיינען געווען במשכן¹³ צוויי מיני „יתדות\" — און ווי רש\"י אליין זאגט עס בפירוש אין פרשת נשא*¹³: „ויתדות ומיתרים היו ליריעות ולקלעים מלמטה כו' (וואס בא זיי איז דער ספק בפירש\"י דא) ויתדות ומיתרים היו לעמודים סביב לתלות בהם הקלעים בשפתם העליונה\" — און בנוגע אט־די לעצטע יתדות, איז ביי רש\"י קיין ספק ניט אז זיי זיינען געווען „תקועין\" — און צו אט־די יתדות איז עס רש\"י מכוון אין פריערדיקן דיבור. ווארום ס'איז פשוט אז די יתדות העמודים — וואס אויף זיי האט מען (באמצעות „הכלונסות וקונדסין\"¹⁴) אויפגעהאנגען דעם אויבערשטן",[["","","שתוחבין הנגרין בכותל. ועוד. וכן מוכרח מפירש\"י דידן גופא — שהרי הפירוש „כמין נגרי נחשת\" הוא גם להדיעה שהיתדות היו תחובין."],["11","11","ראה ס\"פ פקודי. במדבר א, נא ופרש\"י שם. ועוד. וגם בפסוק זה עצמו כותב רש\"י (ד\"ה לכל כלי המשכן) „שהיו צריכים להקמתו ולהורדתו\"."],["12","12","ראה בהעלותך ט, יז ואילך. 12*) ראה לעיל הערה 1."],["13","13","אבל בכלל — יש גם יתד לחפור, יתד דבמעשה שמשון ועוד. 13*) ד, לב. ברמב\"ן שם מקשה, שבברייתא דמלאכת המשכן (פ\"ה) „לא נשנה שיהיו יתדות לעמודים\" — אבל מפשטות לשון הכתוב (פשוטו של מקרא) „ועמודי גו' ויתדותם\" משמע שהיו יתדות לעמודים."],["14","14","במפרשי רש\"י שם ש„יתדות\" הכוונה ל„קונדסין\" שהיו תלויים באונקלי העמודים. אבל [נוסף שלפי\"ז אינו מובן מ\"ש רש\"י"]]],[1300061176,"ברעג פון די קלעים — זיינען זיי געווען „תקועין\" אין די עמודים און באופן כזה אויפגעהאלטן די הענגענדיקע קלעים. ופשוט אז דאס האט לחלוטין ניט צו טאן מיט כובד היתדות. און ווי רש\"י אליין איז עס מציין אין אונזער סדרה¹⁵ און פירט אויס אז די „אונקליות\" (וואס לפי משמעות הענין מוז מען זאגן אז דערמיט מיינט מען די יתדות¹⁶) וואס אויף זיי איז געווען תלוי דער „קונדס דרך טבעתו\", זיינען געווען תקוע אין דעם עמוד.\nועפ\"ז קען מען זאגן, אז די (אונטערשטע) יתדות פון די יריעות און קלעים (שבפרשתנו) זיינען טאקע ניט געווען תחוב בארץ, נאר זיי האבן איינגעהאלטן די יריעות וקלעים מיט זייער כובד (לויט ווי ס'איז מער מסתבר צו זאגן, כנ\"ל סעיף ב'): אי, פארוואס עפעס האט מען אויף דעם גענוצט יתדות און ניט אנדערע שווערע זאכן — איז עס מצד דעם ווייל היות אז צו די זעלבע קלעים בשפתם העליונה האט מען גענוצט יתדות (און דארט האט מען דאך געמוזט האבן יתדות, כנ\"ל), האט מען דעריבער אויך גענוצט יתדות צו די קלעים בשיפוליהן ובמילא אויך צו די יריעות בשיפוליהן¹⁷ כאטש אז מען האט געקענט נוצן אויך אנדערע זאכן.\nד. און נאך דעם ווי רש\"י טייטשט אויס, אז מצד הענין איז דא ניט ברור, פירט רש\"י אליין אויס: „ואומר אני\", אז זיי זיינען געווען תחובין בארץ, און ברענגט אויף דעם צוויי ראיות:\nא) „ששמן מוכיח עליהם שהם תקועין בארץ לכך נקראו יתדות\": וויבאלד דער פסוק רופט זיי דא פארט אן מיטן נאמען יתדות, איז דערפון גופא משמע, אז דאס איז ניט בלויז צוליב זייער ציור פון יתדות און דערביי האט זייער ציור קיין ראלע ניט געהאט — נאר דער כובד אליין, נאר אז זיי זיינען טאקע גענוצט געווארן בהתאם מיט זייער נאמען¹⁸.\nהיות אבער אז דאס איז דאך ניט קיין שטארקע ראי' (ווארום סוף־כל־סוף איז ניטא קיין קלארער באווייז אז דער פסוק רופט זיי אן יתדות מחמת זייער פועל'דיקן באנוץ אלס יתדות) — ובפרט נאך אז לויט ענין המשכן, איז פאראן קעגן דעם א סברא להיפך, כנ\"ל, אז זיי זיינען ניט געווען תקועין, וויבאלד מ'האט געקענט אויסקומען אן דעם — ברענגט דעריבער רש\"י נאך א ראי':\nב) „ומקרא זה מסייעני אהל בל יצען בל יסע יתדותיו לנצח\" — וואס פון דעם פסוק זעט מען אז דער שטייגער צו אויפהאלטן אן אהל (וואס ענינו איז דאך העתקה פון ארט צו ארט¹⁹) איז דורך יתדות וואס מ'קען ניט אוועקרוקן פון",[["","","„לתקוע יתדות\"], מלשון רש\"י „ויתדות כו' לתלות בהם כו' בכלונסות וקונדסין\" משמע שהיתדות אינם הקונדסין. וראה גם ברייתא דמלאכת המשכן שם: „הי' מחבר את הקונדסין . . בתוך יתדות\"."],["15","15","כז, י."],["16","16","ראה גם פרש\"י שם: „ווי העמודים — הם האונקליות\" ובפרש\"י סנהדרין כב, א: „ווי העמודים — יתדות כסף העשויין כמין אונקליות כו'\"."],["17","17","ואין להקשות דאפילו בתור סברת ספק אין לדמות אותם זל\"ז, כיון שווי העמודים (היתדות) היו של כסף, והיתדות של היריעות וקלעים בשיפוליהן — של נחשת — כי אדרבא: מסתבר לומר דכמו שעצמם הכתוב מספר מיני הכלים שבמקדש (ומשכן) — עיין מנחות רפ\"י ב' מדות כו' ז' מדות כו' — כך מצומצם מספר צורות הכלים וכיו\"ב. ועוד — הדפוס ליציקת ווי (יתדות) העמודים הרי אפשר להשתמש בו גם לצורך שיפולי הקלעים והיריעות, ולמה יעשו דפוס נוסף?!"],["18","18","ועפ\"ז מובן מה שרש\"י מסיים „לכך נקראו יתדות\" — דלכאורה מיותר — כי כל עיקר הוכחתו הוא ממה שנקראו (בכתוב זה) יתדות."],["19","19","עיין לך (יב, ח) „ויעתק משם\" ופירש\"י: אהלו."]]],[1300061177,"ארט, דאס מיינט אז זיי זיינען תחוב בארץ. ובמילא (ניט נאר פאלט אפ די סברא הנ\"ל אז מ'האט זיך באנוצט מיט יתדות תלויים, נאר אדרבה) — „ומקרא זה מסייעני\": דערפון וואס דער פסוק לערנט אונז, אז אן אוהל חשוב (אוהל בל יצען) איז דער סדר צו באפעסטיקן אים דורך יתדות התחובין בארץ²⁰, איז פאראן א סיוע צו הנחת רש\"י בנוגע צו אוהל המשכן, אן אוהל הכי חשוב, אז דארט זיינען זיי געווען תקועין בארץ.\nדאך איז אבער מובן, אז נאך דעם אלעם איז עס ניט קיין הוכחה גמורה, און סוכ\"ס איז ניט אויסגעשלאסן, אז ביים משכן בפרט (לויט מהותו ותנאיו המיוחדים²⁰*) איז געווען אנדערש — דערפאר זאגט רש\"י ביים צוטרעטן צום ענין (מלכתחילה): „ואיני יודע\"; און אויך זיין שפעטערדיקן בירור זאגט ער אין א לשון פון „ואומר אני\", און אזוי לייגט זיך אפ ביי אים, מיינענדיק דערמיט אז קיין בירור גמור איז עס ניט.\nה. מ'האט שוין פיל מאל גערעדט, אז אין פירוש רש\"י עה\"ת — אפילו דארט וואו ער איז אויסן צו מפרש זיך נאר דעם פשט און ניט קיין הלכות — זיינען פאראן אויך ענינים פון הלכה און (מכ\"ש²¹) ענינים פון פנימיות התורה, ובלשון רבותינו²² — „יינה של תורה\".\nדער דין ביי שבת איז, אז דאס וואס מלאכת בנין איז אסור מן התורה בשבת איז עס בלויז די מלאכה פון א בנין קבע, אבער די מלאכה פון א בנין ארעי, איז אסור נאר מדרבנן²³.\nוואס איז דער גדר פון א בנין קבוע? — איז דאס אויך שייך און תלוי אין דעם חילוק צווישן אט־די צוויי מעגליכע אופנים אינעם אפטייטשן „יתדות\" וואס רש\"י לאזט אונז הערן בפירושו לפרשתנו:\nאויב מ'זאל אננעמען, אז די יתדות האבן פעסטגעהאלטן די יריעות וקלעים דורך זייער כובד, פארשטייט מען דערפון — וויבאלד אלע מלאכות פון שבת לערנט מען אפ פון מלאכת המשכן²⁴ — אז אפילו ווען מ'בויט אן אוהל וואס איז ניט פארפעסטיקט אין אן אופן פון „תקועין\" (דורך יתדות וכדומה), אויב נאר ער איז גענוג פעסט ניט צו זיין „נע ונד ברוח מצוי'\"²⁵, הייסט עס שוין א בנין קבוע און איז אסור מה\"ת; אויב אבער מ'וועט אננעמען ווי דער פירוש אז די יתדות זיינען געווען תחובין, דארף אויסקומען, אז דער איסור פון בונה בשבת מה\"ת — איז דווקא ביים בויען אן אוהל אין אן אופן פון „תקועין\".\nו. כאמור לעיל, איז אין פירוש רש\"י פאראן „יינה של תורה\". פון די ענינים של פנימיות התורה וואס זיינען מרומז אין אונזער פירש\"י:\nס'איז מבואר אין חסידות²⁶, אז דער ביהמ\"ק איז געווען געבויט בעיקר פון דומם, און דער משכן — פון צומח און חי. און הגם ס'איז פשוט, אז די השראת השכינה — דער ענין פון „ושכנתי בתוכם\"²⁷ — האט זיך אויפגעטאן אויך אין",[["20","20","שלכן מביא רש\"י גם תחלת הכתוב „אהל בל יצען\". 20*) אוהל בכלל — הרי ביכולת בעל האוהל להיות במקום אחד כל משך ימי חייו, משא\"כ במשכן — שידעו שנוסעים ממקום למקום עד שיבואו לעבר הירדן מערבה."],["21","21","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051001\" data-slug=\"likkutei-sichot\" data-id=\"1300051001\">לקו\"ש ח\"ה ע' 1</a> הערה 3."],["22","22","היום יום ע' כד."],["23","23","ביצה לב, סע\"ב. ובכ\"מ. שו\"ע אדה\"ז ר\"ס שט\"ו."],["24","24","שבת מט, ב. שו\"ע אדה\"ז ר\"ס ש\"א."],["25","25","ראה שו\"ע אדה\"ז סשט\"ו סעיף ד'."],["26","26","תו\"א ר\"פ ויגש. לקו\"ת ברכה צט, ד' ואילך. וראה לעיל ע' 17, 20־21."],["27","27","פרשתנו כה, ח."]]],[1300061178,"דעם עפר (דומם) שבקרקע המשכן²⁸, איז אבער פארט ניט גלייך די קדושה פון קרקע המשכן צו דער קדושה פון די יריעות און די קרשים: די יריעות און קרשים זיינען געווען קדוש מצד עצמם, משא\"כ דער עפר פון קרקע המשכן — זיין קדושה איז געקומען בלויז מצד דעם משכן (די יריעות וקרשים) וואס איז געשטאנען אויף אים. און נאכדעם ווי מ'האט פון דעם ארט צוגענומען דעם משכן — איז אין דער קרקע, וואו דער משכן איז געשטאנען, ניט פארבליבן פון דער פריערדיקער קדושה²⁹.\nוואס דאס איז די מעלה אין ביהמ\"ק לגבי דעם משכן. אין ביהמ\"ק איז די קדושה וואס אין דעם דומם — אפילו אין דעם דומם פון קרקע ביהמ\"ק — א קדושה מצד עצמו. און אויך לאחרי החורבן — נאכן חורבן בית ראשון³⁰, אדער נאכן חורבן בית שני, וואס איז געווען אינעם אופן „ערו ערו עד היסוד בה\"³¹ — מען האט חרוב געמאכט ביז די יסודות³² אדער — אויך³³ די יסודות³⁴ — איז דאך לכמה דעות פארבליבן קדושה אין דעם מקום המקדש³⁵.\nז. די שאלה איז אבער: ווי שטארק און ווי טיף ס'איז געווען די קדושה פון קרקע המשכן אין דער צייט וואס דער משכן איז דארט געשטאנען — און דאס איז תלוי אין די צוויי אופני הפירוש פון „יתדות\" וואס רש\"י ברענגט דא ארויס:\nלויט דעם אופן אז די יתדות האבן אויפגעהאלטן דעם משכן בלויז דורך זייער כובד, דארף אויסקומען אז אט־די קדושה וואס ווערט נשפע פון משכן אין קרקע המשכן איז דאס נאר א מסובב, האט דורכגענומען דעם עפר נאר אין חיצוניות, עס איז ניט פארבונדן מיט דעם שטח הקרקע אלס פרט, נאר אלס קרקע סתם, היות אז אויך ווען ער איז געשטאנען איז דער משכן ניט געווען איינגעפעסטיקט דורך חיבור ותקיעה בקרקע,",[["28","28","וכדמוכח גם מהדין (נשא ה, יז) ומן העפר אשר יהי' בקרקע המשכן יקח הכהן גו'."],["29","29","ולהעיר מהר סיני דבתחלה „כל הנוגע בהר מות יומת\" ולאחר מ\"ת (שהגילוי הי' מלמעלה) (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380829\" data-slug=\"likkutei-torah\" data-id=\"4001380829\">לקו\"ת ראה כח, ב</a>)), „המה יעלו בהר\" (יתרו יט, יב־יג)."],["30","30","החריבו רק את התקרה — ירושלמי יומא פ\"א ה\"א. וראה גם גיטין נז, ב. שמו\"ר פל\"ה, ה."],["31","31","תהלים קלז, ז."],["32","32","לפי דיעה א' באיכ\"ר רפ\"ה."],["33","33","לפי דיעה הב' באיכ\"ר שם. שמו\"ר שם. זח\"ג פס, א. וראה גם ירושלמי שם (עפ\"י קה\"ע)."],["34","34","ועפ\"י מ\"ש בתוספתא ברכות ספ\"א: „שאין שכינה חוזרת עד שתעשה הר . . מאימתי משנקרו יסודותי' ממנה\", י\"ל — שאדרבה: דווקא ע\"י שהחורבן הי' באופן ד„ערו ערו עד היסוד בה\" — יותר מבבית ראשון — „נשאר המקום בקדושתו\" (צפנת פענח להרגוצובי — הובא ב„מפענח צפונות\" ע' קמא). ובזה יובן גם מה שאמר ר\"ע (סוף מס' מכות) „תלה הכתוב נבואתו של זכרי' בנבואתו של אורי', באורי' כתיב (מיכה ג, יב) לכן בגללכם ציון שדה תחרש וגו' בזכרי' כתיב כו'\" — דלכאורה, הרי כו\"כ פסוקים מדברים אודות החורבן, ולמה בחר בפסוק זה דוקא — כי ב„ציון שדה תחרש\" מרומזים ב' הענינים: (א) גודל החורבן ואופנו — שלא נשאר מאומה, וכמו שדה שאין בה שום בנין גם לא היסודות. (ב) שעי\"ז דוקא תהי' הגאולה, כי חרישת השדה היא הכנה להצמיחה (ראה חדא\"ג מהרש\"א שבת קלט, א), ולכן קיום הנבואה „ציון שדה תחרש\" מעידה על קיום היעוד (זכרי' ח, ד) „עוד ישבו זקנים וזקנות ברחובות ירושלים\" (משיחת יו\"ד שבט — יום ההילולא — תשכ\"ה. עיי\"ש בארוכה. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191072\" data-slug=\"likkutei-sichot\" data-id=\"1300191072\">לקו\"ש חי\"ט ע' 72</a> ואילך)."],["35","35","מגילה י, א. וש\"נ. רמב\"ם שם ספ\"ו."]]],[1300061179,"נאר זיך אויפגעהאלטן אויף דער קרקע דורך אן אנדער זאך — כובד היתדות³⁶.\nמשא\"כ לויטן פירוש אז די יתדות זיינען געווען „תחובין בארץ\", האט די קדושה פון משכן אריינגעדרונגען אין דעם שטח קרקע אין א פנימיות. נאכמער — דאס וואס דער משכן איז געווען קבוע במקומו, אהל בל יצען — איז דאס געקומען דורך דעם קרקע המשכן; דער שטח פרט'י, קרקע המשכן איז די סיבה פון קביעות המשכן (שאז קדושתו יותר — ווי ווען דער משכן איז פאנאנדערגענומען. און ס'איז נוגע לכמה דינים³⁷.\nח. ס'איז ידוע, אז די קדושה פון (משכן און) ביהמ\"ק האט מאיר געווען אויך בכל העולם³⁸. פון דעם איז מובן, אז דורך בנין ביהמ\"ק איז געגעבן געווארן יעדן אידן א כח (אין זייער „ועשו לי מקדש\" בנפש³⁹) צו ממשיך זיין קדושה בכל העולם כולו און אין אן אופן פנימי וקבוע — בדוגמא ווי די קדושה פון בית המקדש.\nאון דערפון קומט ארויס א הוראה, אז יעדער איד, וואו ער זאל ניט זיין — אפילו ווען ער געפינט זיך אין ארץ העמים וואס תורה פסק'נט אז אוירה און גושה זיינען טמא⁴⁰ — האט ער בכח צו מברר זיין חלקו בעולם און דארט ממשיך זיין קדושה באופן פנימי וקבוע, בדוגמת הקדושה דביהמ\"ק.\nוואס דאס איז דער ביאור אויפן מאמר רז\"ל⁴¹ אז די בתי כנסיות ובתי מדרשות שבחו\"ל זיינען „מקדש מעט\" און מען וועט זיי לע\"ל מיטנעמען קיין ארץ־ישראל — ווייל דורך זייער תפלה און תורה זיינען אידן ממשיך קדושה אויך אין די הייזער גופא וואס זיינען פון אבנים ועצים ועפר⁴² און וועלכע געפינען זיך אין חוץ־לארץ — און די קדושה פארבלייבט אין זיי, ביז אז סוכ\"ס נעמט מען זיי מיט קיין ארץ־ישראל.\nאון אזוי, לאידך גיסא: דורך דעם וואס יעדער איד איז איצט ממשיך קדושה בחלקו בעולם, ווערט אויפגעטאן די הכנה צו „עתידה ירושלים שתתפשט בכל ארץ ישראל⁴³ ועתידה א\"י להתפשט בכל הארצות\"⁴⁴ — און איבעראל, אין דער גאנצער וועלט, וועט נתפשט ווערן א מעין פון דער קדושה פון ביהמ\"ק⁴⁵; ענינו איז דאך „בית זבול לך\"⁴⁶ — וועט מען דאן זען ווי די גאנצע וועלט איז א",[["36","36","ואולי י\"ל דנפק\"מ האם במשכן אסורה חציצה בין רגלי הכהנים לקרקע."],["37","37","לב' הסברות דגדר קדושת קרקע המשכן — יש להעיר מב' הדעות בהקדים עפר (קרקע המשכן) למים (דסוטה) — סוטה טז, ב. ואף דשם גם במקדש כן הוא — הרי קרא קאי במשכן. ולסברא הא' דכאן פסול בהקדים עפר ובמילא ידעינן דהסדר בקרא הוא לעכב. ואכ\"מ."],["38","38","להעיר מתנחומא בהעלותך ב. ויק\"ר פל\"א, ז. במדב\"ר פס\"ו, ב. וראה גם מנחות פו, ב וברש\"י שם ד\"ה שקופים. רש\"י כת\"י שם ד\"ה ואטומים."],["39","39","וכמרז\"ל (נסמן בלקו\"ש ח\"ג ע' 906) בתוכו לא נאמר אלא בתוכם כאו\"א מישראל."],["40","40","שבת טו, ב. רמב\"ם רפי\"א מהל' טומאת מת."],["41","41","מגילה כט, א."],["42","42","ראה נגעים פי\"ב, מ\"ב."],["43","43","ראה ספרי דברים א, א. שהש\"ר פ\"ז, ד (ג). פס\"ר פ' שבת ור\"ח. ילקו\"ש ישעי' רמז תקג."],["44","44","ראה ספרי, פס\"ר וילקו\"ש שם."],["45","45","ראה זח\"ב רלד, א: למהוי אתפשטותא דביתא בכל סטרין. וראה אוהח\"מ — הובא בניצוצי זהר שם."],["46","46","מלכים א ח, יג. וראה פירש\"י ויצא (ל, כ) ד\"ה יזבלני „עיקר דירתו\"."]]],[1300061180,"דירה לו ית', ואדרבא עיקר דירה — בתחתונים⁴⁷.\nאון אזוי ווי אין ביהמ\"ק היו קוראין את השם ככתבו⁴⁸ — אז דער שם הוי' איז געווען אין אן אופן פון קריאה (בגילוי) — אזוי וועט זיין אויך בכל העולם „הי' אחד ושמו אחד — נקרא ביו\"ד ה\"י (כמו ש)נכתב ביו\"ד ה\"י\"⁴⁹ — אין דער גאולה האמיתית השלימה, דורך משיח צדקנו, יבוא ויגאלנו בקרוב ממש.\n(משיחת ש\"פ תרומה תשכ\"ה)",[["47","47","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא רפל\"ו</a>. מאמר דיום ההילולא — באתי לגני תש\"י בתחלתו. ובכ\"מ. וראה גם לעיל ע' 21 ואילך."],["48","48","משנה סוטה לז, סע\"ב ואילך. וראה בגמרא שם. ספרי נשא לט."],["49","49","זכרי' יד, ט. פסחים ספ\"ג. ובזח\"ג רל, א (וכ\"ה נוסחת הכ\"י לפסחים שם — הובא בדק\"ס) הגירסא: נכתב ביו\"ד ה\"י ונקרא ביו\"ד ה\"י."]]],[1300061181,"<h3>תצוה</h3>\nא. אין פסוק „ואתה הקרב אליך את אהרן אחיך גו' לכהנו לי\"¹, שטעלט זיך רש\"י אויף די ווערטער „ואתה הקרב אליך\" און איז מפרש: „לאחר שתגמור מלאכת המשכן\".\nדארף מען פארשטיין:\nא) פון וואנעט נעמט עס רש\"י אז דער ציווי למשה צו מאכן אהרן ובניו פאר כהנים מיינט, אז ער זאל דאס טאן (ניט גלייך, נאר) „לאחר שתגמור מלאכת המשכן\"?\nדי קשיא איז נאך שטארקער: דעם ציווי „ועשית בגדי קדש גו'\" פון קומענדיקן פסוק, און אזוי אויך דעם ציווי „ואתה תדבר אל כל חכמי לב גו'\" וואס שטייט מיט א פסוק ווייטער, האט דאך משה געדארפט טאן פריער (ווארום דאס איז דאך א חלק פון מלאכת המשכן). היינט פארוואס זאל מען לערנען אז דער ציווי „ואתה הקרב אליך\" איז אנדערש פון די אנדערע ציוויים; און זיין קיום זאל זיין שפעטער, ערשט „לאחר שתגמור מלאכת המשכן\"² ?\nב) מיט זיין פירוש „לאחר שתגמור כו'\", איז דאך רש\"י נאר מפרש ווען עס זאל זיין דער „הקרב\". פארוואס איז ער מעתיק (פארן פירוש) נוסף אויף דעם ווארט „הקרב\" אויך די ווערטער „ואתה\"³ און „אליך\"? איז משמע דערפון אז רש\"י'ס הוכחה צו מפרש זיין „לאחר שתגמור מלאכת המשכן\" איז טאקע פון די ווערטער — „ואתה הקרב אליך\".\nב. מפרשים זאגן⁴, אז רש\"י מוז לערנען אז דער קיום הציווי „ואתה הקרב אליך\" קומט „לאחר שתגמור כו'\" — ווייל די הקרבה פון אהרן ובניו „לכהנו לי\" איז געווען דורך די בגדי כהונה (ווי עס שטייט מיט צווי פסוקים ווייטער⁵ „ועשו את בגדי אהרן לקדשו לכהנו לי\"); ווי אויך דורך דעם חינוך אין די ימי המילואים (ווי עס שטייט ווייטער אין דער סדרה⁶ — „וזה הדבר אשר תעשה גו' לקדש אותם לכהן לי\") — און דאס איז דאך געווען ערשט לאחר גמר מלאכת המשכן⁷.",[["1","1","פרשתנו כח, א."],["2","2","בגו\"א כאן, שהחידוש שברש\"י הוא „שאין ואתה דבוק אל הפרשה שלפנ\"ז\" (וכנראה שמפרש שציווי זה (ואתה תצוה) הוא על עשיית המשכן, שהיא חלק ממלאכת המשכן). אבל ראה רש\"י אמור (כד, ב) שהמשמעות ד„ואתה תצוה\" הוא „סופך לצוות כו'\" (ושהציווי הוא על העלאת הנרות — שלאחרי גמר מלאכת המשכן). ואף שהתלמיד לא למד עדיין פרש\"י שבפ' אמור — הרי כותב שם רש\"י „וכן משמע\", היינו שיכולים לדעת זאת גם בלי פירושו (ומה שאמרו שם, היינו רק בכדי לתרץ קושיא, עיי\"ש)."],["3","3","ולפי פירוש הגו\"א (שבהערה הקודמת) י\"ל, שזה שרש\"י מעתיק תיבת „ואתה\" הוא בכדי להשמיענו, שהגם שמתיבת „ואתה\" (בוא\"ו המוסיף) משמע שדבוק להפרשה שלפני', בכ\"ז הפירוש הוא „לאחר שתגמור כו'\"."],["4","4","רא\"ם כאן. וראה גם גו\"א כאן."],["5","5","כח, ג."],["6","6","כט, א."],["7","7","ומה שרש\"י אינו מעתיק התיבות „לכהנו לי\", ואינו מרמזם אפילו ב„וגו'\" — אף שדרכו של רש\"י בכ\"מ הוא להעתיק (או לרמז עכ\"פ ב„וגו'\") גם התיבות שמהן היא ההוכחה לפירושו — י\"ל (לפי פי' זה)"]]],[1300061182,"ס'איז אבער שווער אזוי צו זאגן. ווייל [נוסף לזה וואס דאס פארענטפערט ניט די קשיא: פארוואס איז רש\"י מעתיק אויך דעם ווארט „אליך\"⁸] לויט רש\"י'ס שיטה, איז דער „לכהנו לי\" פון אונזער פסוק און דער „לכהנו לי\" ביי עשיית בגדי כהונה (און אזוי אויך דער „לכהן לי\" פון פרשת המילואים), זיינען צווי באזונדערע ענינים, וכדלקמן.\nג. אויף די ווערטער „לקדשו לכהנו לי\" וואס שטייען ביי „ועשו את בגדי אהרן\"⁹, איז רש\"י מפרש: „לקדשו להכניסו בכהונה ע\"י הבגדים שיהא כהן לי ולשון כהונה שירות הוא. שנטריאה בלעז\".\nזאגן מפרשים⁹, אז רש\"י איז דא מפרש צווי ענינים: א) אז „לקדשו\" און „לכהנו לי\" זיינען ניט קיין צווי ענינים, נאר „לכהנו לי\" איז דער אפ־טייטש פון „לקדשו\"¹⁰. ב) אז „לכהנו לי\" מיינט ניט צו מאכן אים פאר א כהן (שם התואר) — ווארום „לשון כהונה שירות הוא\", און דערויף לייגט זיך ניט דער אויספראך „צו מאכן אים פאר א משרת\" — נאר דער פירוש איז „להכניסו בכהונה\", אריינ־בריינגען עם אין (דער פעולה פון) כהונה (שירות).\nאון די מפרשים זיינען מבאר אז דעם פירוש פון „לכהנו לי\" זאגט רש\"י ערשט אין פסוק „ואתה תדבר גו'\" — כאטש דער זעלבער לשון שטייט שוין פריער אין פסוק „ואתה הקרב אליך\" — ווייל דער עיקר וואס רש\"י וויל דא זאגן איז ניט דעם פירוש פון „לכהנו לי\", נאר אז דאס איז אין ענין מיט „לקדשו\": אז אין וואס באשטייט דער „לקדשו\" — אין „להכניסו בכהונה\"; און זאגנדיק דעם לשון „להכניסו בכהונה\" (וואס דאס איז דער טייטש פון „לכהנו לי\"), איז רש\"י מוסיף „ולשון כהונה שירות הוא\", וואס דערמיט באווייזט ער אז „לכהנו לי\" מיינט ניט מאכן אים פאר א כהן, נאר „להכניסו בכהונה\", כנ\"ל.\nס'איז אבער ניט מובן:\nא) דערפון גופא וואס רש\"י דארף מוסיף זיין „ולשון כהונה שירות הוא\", בכדי צו באווייזן אז „לכהנו לי\" מיינט „להכניסו בכהונה\", איז דאך מוכח, אז ער נעמט עס אן פאר א חידוש¹¹ — האט ער במילא געדארפט זאגן דעם פירוש „להכניסו בכהונה\" מיט דער הוכחה „ולשון כהונה שירות הוא\" ביי די ווערטער „לכהנו לי\" וואס שטייען פריער — בכדי דער תלמיד זאל ניט",[["","","שכוונתו ב„ואתה הקרב אליך\" שמעתיק לפני פירושו הוא (לא לתיבות אלו, אלא) לכללות הענין. וע\"ד פרש\"י לקמן (כח, ו) „ועשו את האפוד\" — דכוונתו לכללות הענין (דעשיית האפוד ואפילו — דהחושן!). ובכ\"מ."],["8","8","בנוגע ל„ואתה\" — י\"ל כבהערה הקודמת (או כנ\"ל הערה 3)."],["9","9","רא\"ם שם. וראה גם ש\"ח."],["10","10","ועפ\"ז מובן מה שרש\"י כותב ב־פירושו „לקדשו\" — אף שלכאורה אינו מחדש בזה מאומה (שהרי זהו לשון הכתוב) — כי תיבת „לקדשו\" (שבפירושו) נמשכת ל„להכניסו בכהונה\", וכוונתו בזה היא לבאר ש„לקדשו\" הוא ע\"י שיכניסו לכהונה, כבפנים."],["11","11","ובפרט שמתיבת „לי\" הדבוקה ל„לכהנו\", משמע שפירוש „לכהנו\" הוא לעשותו לכהן, שלכן הוזקק רש\"י להוסיף „שיהא כהן לי\", כברא\"ם שם. וכן משמע ממ\"ש „לכהנו\" (בוא\"ו) — ראה לקמן הערה 17."]]],[1300061183,"האבן קיין טעות¹² אין דעם פירוש פון די ווערטער ווען ער לערנט זיי צום ערשטן מאל?\nב) אמת טאקע אז „לשון כהונה שירות הוא\" — איז דאך אבער דער ווארט „כהן\" אומעטום א שם התואר אויפן מענטשן¹³. היינט פארוואס זאל מען ניט לערנען¹⁴ אז „לכהנו (לי)\" מיינט — צו מאכן אים¹⁵ פאר א כהן¹⁶?\nאיז דערפון מוכח, אז די ווערטער „לכהנו לי\" כשלעצמם, קען מען טאקע אויך טייטשן צו מאכן אים פאר א כהן¹⁷. און דערפאר איז רש\"י ניט מפרש „לכהנו לי\" אין פסוק „ואתה הקרב אליך\", ווארום דארט איז דער פירוש פון די ווערטער כפשוטם. און דאס וואס ווייטער דארף רש\"י יע מפרש זיין אז „לכהנו לי\" מיינט „ל־הכניסו בכהונה כו' שירות הוא כו'\", איז עס מצד דעם ווייל דאס שטייט צוזאמען מיט „לקדשו\", כדלקמן.\nד. אין „לקדשו לכהנו לי\" וואס שטייט ביי „ועשו את בגדי אהרן\" איז רש\"י'ן שווער:\nאויך אין פסוק „ואתה הקרב אליך גו' לכהנו לי\" איז שוין משה נצטווה געווארן צו מאכן אהרן ובניו פאר כהנים — און דארט פארבינדט ניט דער פסוק דעם „לכהנו לי\" מיט עשיית בגדי כהונה. ד.ה. אז אויך אן די בגדים האט משה (געקענט און) געמאכט זיי פאר כהנים. היינט וואס איז דער פירוש פון „ועשו את בגדי אהרן גו' לכהנו לי\", אז בכדי צו מאכן אהרן'ען פאר א כהן האט מען געמוזט האבן די בגדים?\nבדוחק האט מען געקענט פארענטפערן, אז אויך „ואתה הקרב גו' לכהנו לי\" פון אונזער פסוק מיינט אז דאס זאל זיין דורך די בגדים. נאר צום ערשטן זאגט דער פסוק דעם עצם הענין (אז ער זאל מאכן אהרן ובניו פאר כהנים), און דערנאך, ווען ער רעדט וועגן דעם ציווי אויף עשיית בגדי כהונה, איז ער מפרש ווי אזוי דער ענין ווערט אויפגעטאן, אז דער „לכהנו לי\" ווערט דורך די בגדים.\nרש\"י וויל אבער אזוי ניט לערנען [נוסף לזה וואס דאס איז א „דוחק\"]. ווייל אויב שפעטער איז דער פסוק מפרש בלויז ווי אזוי עס ווערט אויפ־געטאן דער „לכהנו לי\", אבער דער „לכהנו לי\" גופא איז דא דער זעלבער ווי אין פריערדיקן פסוק, האט דאן דער פסוק דא געדארפט שרייבן דעם זעלבן לשון ווי פריער. פארוואס־זשע שטייט ביים ציווי ואתה הקרב בלויז „לכהנו לי\" און ביי בגדי כהונה שטייט „לקדשו לכהנו לי\"?",[["12","12","והרי הדברים ק\"ו: אם גם לאחר שמפרשו צריך הוכחה ע\"ז, הרי מכ\"ש שכאשר אינו מפרש כלל, הרי בודאי יטעה התלמיד."],["13","13","ראה ויגש מז — כב, כו. יתרו יט — כב, כה. (וצע\"ק בקרא לך (יד, יח) ובת\"א שם — דכהן שם קאי על שם — רש\"י וישב לח, כד), וראה לקמן הערה 19."],["14","14","ובפרט שכן משמע (לפי הרא\"ם) גם מתיבת „לי\" (ומ„לכהנו\" בוא\"ו), כנ\"ל הערה 11."],["15","15","וכמו „יהי' כהן\" (רש\"י שמות ד, יד)."],["16","16","וגם: מה מחדש רש\"י במ\"ש „ע\"י הבגדים\", והרי מפורש בכתוב ש„לקדשו לכהנו לי\" הוא ע\"י „ועשו בגדי קדש\"?"],["17","17","כפשטות הלשון „לכהנו\" (בוא\"ו), ולא „לכהן\". וראה חזקוני (כח, א), שהוא\"ו ד„לכהנו\" הוא וא\"ו יתירא."]]],[1300061184,"איז דערפון געדרונגען, אז דורך די בגדים טוט זיך אויף א נייע, א גרע־סערע זאך ווי דורך „הקרב גו' לכהנו לי\". דעריבער איז רש\"י מפרש „לקד־שו להכניסו בכהונה ע\"י הבגדים כו'\", אז דורך די בגדים¹⁸ טוט זיך אויף — „לקדשו להכניסו בכהונה\", כדלקמן.\nה. כאמור לעיל (ס\"ג), איז דער ווארט „כהן\" (ניט קיין שם ע\"ש ה־פעולה¹⁹ וואס זאל מיינען: דער וואס איז משרת, נאר) א שם התואר וואס באצייכנט א געווייסן סוג מענטשן וואס האבן אין זיך א געוויסע מעלה צוליב וועלכע זיי זיינען שייך צו כהונה, שירות (ער איז א משרת): לאחרי ווי אהרן ובניו זיינען נמשח געווארן ל־כהונה, ווערן זיי און זייערע קינדער עד סוף כל הדורות גערופן מיטן נא־מען „כהנים\", און פאר דעם — האט מען די בכורים גערופן „כהנים\".\nאון כשם ווי דער נאמען „כהנים\" פאר זרעו של אהרן איז ניט קיין שם הפעולה, נאר א שם התואר והמעלה [וואס דערפאר ווערן אלע בני אהרן גערופן „כהנים\", אויך די וואס זיינען ניט נתחנך געווארן²⁰ לעבודה²¹, און אפילו אזעלכע וואס זיינען פסול צו עבודה²²], אזוי איז אויך דער פריער־דיקער נאמען „כהנים\" פאר בכורים געווען א שם התואר והמעלה²³.\nאון דאס איז דער חילוק פון „לכהנו לי\" וואס שטייט ביי „ואתה הקרב אליך\" צו „לקדשו לכהנו לי\" וואס ווערט אויפגעטאן דורך „בגדי אהרן\": צום ערשטן איז משה נצטווה געווארן צו אויסטיילן אהרן ובניו פון אלע אנ־",[["18","18","ועפ\"ז מובן מה שרש\"י מוסיף „ע\"י הבגדים\"."],["19","19","ומ\"ש רש\"י לעיל (ויגש מז, כב) „כל לשון כהן משרת לאלקות הוא\", בהכרח לומר, שהשם משרת כאן הוא שם התואר דהאדם * (האדם הוא מסוג משרת) ועד שגם הקטנים, שמצד מצבם בהוה אינם ראויים לשרת [מכיון שלאחר שיגדלו יהיו ראויים לשירות] נקראים (הם גם עכשיו) „כהנים\" (רש\"י ר\"פ אמור). ויתירה מזו מצינו, שגם נשים נקראו „כהנות\" [ברכות מד, א. משנה סוף יבמות. ועוד — אלא שי\"ל ש„לשון תורה לעצמה כו'\" (ע\"ז נח, ב. חולין קלו, ב)], אף שלעולם לא יהיו ראויות לשרת — כי לאחר שנבחרו אהרן ובניו לשרת כו', נעשה השם „כהן\" תואר לכל זרע אהרן (גם בנות אהרן). *) ועפ\"ז יומתק ההמשך בפרש\"י „חוץ מאותן שהם לשון גדולה כו'\" — דהחילוק הוא רק בזה שהוא ל' גדולה (ולא שירות), אבל לא דשם התואר ושם הפעולה."],["20","20","ראה רמב\"ם הל' כלי המקדש פ\"ה הט\"ז (ממנחות נא, ב): אין הכהן עובד תחלה . . עד שיביא עשירית האיפה כו'. וראה גם רש\"י צו ו, יג."],["21","21","ובמכ\"ש מקטנים (ראה לעיל הערה 19) אף שאינם שייכים לשרת, משא\"כ גדולים, שגם טרם שנתחנכו יכולים הם (להתחנך —) להביא עשירית האיפה וכו'. ונוסף לזה (בדרך ההלכה): כהן שעבד טרם שהביא עשירית האיפה עבודתו כשרה (רמב\"ם שם), משא\"כ טרם שהביא ב' שערות (רמב\"ם שם הט\"ו)."],["22","22","ראה פרש\"י ר\"פ אמור, שרק חללים מתמעטין מ„הכהנים\", אבל בעלי מומין, אף שבאם הי' נאמר רק „הכהנים\" לא היו במשמע, מ\"מ לאחר שנאמר גם „בני אהרן\" אינם מתמעטין מ„הכהנים\". וראה לקמן הערה הב' (בשוה\"ג) להערה 28 (ואפילו בנוגע לחללים, כתב הרמב\"ם הל' ביאת מקדש פ\"י ה\"י, שעבודתו כשרה לשעבר. ואכ\"מ)."],["23","23","ומ\"ש רש\"י יתרו (יט, כב) „שהעבודה בהם\", י\"ל שזוהי רק הוכחה למה שהם כהנים בעצם, כנ\"ל הערה 19. גם י\"ל, שכוונת רש\"י שם היא לפרש החידוש שב„וגם הכהנים גו' יתקדשו\" — דלכאורה: מהיכי תיתי לומר שהבכורות (הכהנים) יהיו מותרים לעלות — וע\"ז מפרש: „שהעבודה בהם\", דמכיון שהם"]]],[1300061185,"דערע אידן²⁴ און מאכן זיי פאר (א סוג פון) כהנים; און דערנאך איז ער אנגעזאגט געווארן „לקדשו לכהנו לי\", אז (לאחרי ווי זיי וועלן שוין זיין „כהנים\"²⁵), זאל ער זיי (דורך די בגדים¹⁶) הייליקן און אריינברענגען אין כהונה²⁶, אין „שירות\", ד. ה. אריינפירן זיי אין דער עבודה פון כהונה.\nו. ע\"פ הנ\"ל, אז דער פירוש פון „לכהנו לי\" אין פסוק „ואתה הקרב אליך\" איז צו מאכן אהרן ובניו פאר כהנים — ניט ווי „לקדשו לכהנו לי\" ביי די בגדים [ועד\"ז „לקדש אותם לכהן לי\" וואס שטייט ביי די מילואים] וואס מיינט אריינפירן זיי אין דער עבו־דה פון כהונה, איז פארשטאנדיק, אז מצד דעם „הקרב גו' לכהנו לי\" אליין, האט מען געקענט לערנען אז משה איז נצטווה געווארן צו מאכן זיי גלייך פאר כהנים; און רש\"י'ס הכרח צו לערנען „לאחר שתגמור מלאכת ה־משכן\" איז פונעם לשון „ואתה הקרב אליך\", און ווי דער דיוק לעיל ס\"א.\nאיז דער ביאור אין דעם:\nפארוואס שטייט ביים ציווי צו משה'ן (ער זאל מאכן אהרן ובניו פאר כה־נים) „ואתה הקרב אליך\"²⁷, אז משה",[["","","עובדים את עבודת המקום*, הי' מקום לחשוב שמותרים כו'. ועפ\"ז יובן מה שרש\"י מעתיק גם תיבת „וגם\", וכן ב־פירושו — „ואף\"."],["24","24","כלשון הכתוב „מתוך בני ישראל\". וע\"פ מ\"ש בפנים, יומתק מה שבפסוק ג' (וכן לקמן כט, א) לא נאמר „מתוך בנ\"י\" — כי ההבדלה מבנ\"י היתה כבר לפנ\"ז."],["25","25","ע\"פ מ\"ש בפנים, יומתק לשון רש\"י (כט, לה) „לא נתמלאו ידיהם להיות כהנים ועבודתם פסולה\" — דלכאורה: זה שעבו־דתם פסולה, תוצאה ומסובב הוא מזה שאינם כהנים, ומכיון שכבר כתב „לא נתמלאו כו' כהנים\" הרי במילא שמעינן שעבודתם פסולה, ול\"ל לרש\"י להוסיף זאת בפירושו — אלא בזה מבאר שכוונתו ב„לא נתמלאו כו' להיות כהנים\" הוא לענין השירות, מה שעבודתם פסולה. ומ\"ש „להיות כהנים\" — ראה הערה הבאה."],["26","26","וי\"ל, שגם ענין הכהונה „לשון שירות\" [שנעשתה ע\"י הבגדים (וע\"י ה־חינוך למילואים)], היא [לא רק ענין של פעולה (בדוגמת מעלת „הנגשים אל ה' להקריב קרבנות\" על „הבכורות שהעבודה בהם\" — ראה לעיל הערה 23 בשוה\"ג) אלא שעי\"ז ניתוספה ג\"כ מעלה בהאדם] דרגא בהאדם — „לקדשו\"; גם כהונה זו היא (לאחרי שנכנס לכהונה) שם התואר לזרעו של אהרן לאחר החינוך בימי המי־לואים (ע\"ד המבואר לעיל הערה 19 בנוגע לכהונה בכלל), וקודם שנתחנכו אינם נק־ראים „כהנים\" בנוגע לענין זה. וראה לקמן הערה הב' (בשוה\"ג) להערה 28. ועפ\"ז יומתק לשון „לכהנו\" (בוא\"ו) — שמשמעותו הוא (כנ\"ל הערה 17) שהאדם יהי' כהן, אף שלשון כהונה (כאן) ענינה שירות — כי גם זה נעשה דרגא וענין באדם. וכלשון רש\"י „שיהא כהן לי\". וכן לקמן כט, לה „להיות כהנים\". ולהכניסו בכהונה (ולא לעשותו כהן) — כי החידוש בלקדשו לכהנו לי הו\"ע השירות, אלא שעי\"ז בא במילא גם שם תואר לאדם (משא\"כ לכהנו לי שבפסוק הקודם, שכל ענינה הוא תואר בהאדם — ראה לעיל הערה 19)."],["27","27","דלכאורה „אליך\" — מיותר. יתרה מזו — בסתירה לההמשך „לכהנו לי\". *) ואף שלכאורה הכתוב עצמו מבאר זה „הנגשים אל ה'\" — י\"ל, שהוקשה לי' לרש\"י: הרי גם מתיבת „הכהנים\" עצמה מובן שהם משרתים ונגשים לה', ומאי קמ\"ל בההוספה „הנגשים אל ה'\"? ולכן מפרש שהכתוב מחדש ב' ענינים (ובסדר דלא זו אף זו): וגם הכהנים (שם התואר, הם) הבכורות (שמעלתם היא רק זה) „שהעבודה בהם\" (גם שאינם עובדים בפועל), ואח\"כ מוסיף חידוש גדול יותר) הנגשים אל ה' להקריב קרבנות (גם אלו הנגשים להקריב בפועל) אף הם לא יסמכו כו'."]]],[1300061186,"זאל זיי דערנענטערן צו זיך — איז עס ווייל משה איז שוין דאן געווען א כהן²⁸. און דערפאר האט עם דער אויבערשטער געזאגט „ואתה הקרב אליך את אהרן אחיך ואת בניו גו' לכהנו לי\", אז ער זאל דערנענטערן אהרן ובניו צו זיך, אז אויך זיי זאלן זיין כהנים²⁹.\nס'איז אבער נאך ניט מובן:\nא) אויך ווען עס זאל ניט שטיין „ואתה הקרב אליך\", נאר בלויז „לכ־הנו לי\", וואלט לכאורה געווען קלאר דער פירוש פון ציווי. צוליב וואס איז דער פסוק מדגיש „ואתה הקרב אליך\"?\nב) די קשיא איז נאך שטארקער: די מעלה המיוחדת פון משה'ן איז דאך באשטאנען (ניט אין דעם ענין הכהונה, נאר) אין אנדערע ענינים, צו וועלכע האבן כהנים לכאורה קיין שייכות ניט. [און ווי געלערנט פרי־ער אין פרשת יתרו³⁰, אז בלויז משה האט געקענט עולה זיין בהר, אבער „הכהנים גו' יתקדשו גו'\"]. איז פאר־וואס זאל אויף „לכהנו לי\" געזאגט ווערן „ואתה הקרב אליך\", וואס ווייזט אז דורך זייער ווערן כהנים וועלן זיי ווערן נאענט צו מדריגת משה?\nדערויף איז רש\"י מפרש „לאחר שתגמור מלאכת המשכן\":\nווען אהרן ובניו וואלטן געווארן כהנים פארן גמר מלאכת המשכן, אפי־לו אויב זיי וואלטן מקריב געווען קרבנות (ווי די בכורים וואס האבן געטאן די עבודה, כאטש ביי זיי איז ניט געווען קיין בגדי כהונה), וואלט טאקע דערויף ניט געקענט געזאגט ווערן „ואתה הקרב אליך\", ווארום אויך די „כהנים הנגשים אל ה' — להקריב קרבנות\"³¹ זיינען געווען א „מחיצה לעצמם\" און האבן ניט גע־טארט צוגיין (ניט נאר צום ארט וואו משה איז געשטאנען, נאר) אפילו צום",[["28","28","ראה רש\"י פרשתנו כט, כד: „ומשה כהן\". ולא מסתבר לומר (ע\"ד הפשט) שנעשה כהן רק למשך ימי המילואים (היינו שנענש ולא ניתנה לו כהונה — רש\"י שמות ד, יד — ואח\"כ ניתנה לו למשך ימי המילואים ואח\"כ שוב נלקחה ממנו!) — ומסתבר שלאחר ימי המילואים פסקה ממנו כהונה. ובלאה\"כ משמע כן — שהרי נטילת כהונה ממשה קשורה ב„הוא (אהרן) יהי' כהן\" — רש\"י שם, וזה התחיל בסוף ימי המילואים. או י\"ל דס\"ל כהמ\"ד (זבחים קב, א) שלא פסקה כהונה אלא מזרעו של משה. ומ\"ש רש\"י (שמות שם) „ואתה לוי\", כוונתו בנוגע לסיומו שם „בניו יקראו על שבט הלוי\" *. ומ\"ש רש\"י (אמור כא, כב) „שהותרו לזר שאכל משה בשר המילואים\" — כבר עמדו על זה מפרשי רש\"י שם, עיי\"ש **. וראה לקו\"ש חל\"ב ע' 28 ואילך."],["29","29","ראה עד\"ז ראב\"ע כאן. *) ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261002\" data-slug=\"likkutei-sichot\" data-id=\"1300261002\">לקו\"ש חכ\"ו ע' 2</a> (הערה 16), בביאור פרש\"י (שמות א, כא) „בתי כהונה ולוי'\" — ששניהם (כהונה ולוי') קאי על משה (שהרי אהרן נולד לפני ש„ותחיין את הילדים\"). וכוונתו ב„כהונה ולוי'\" הוא — למשה ולבניו, או לשני זמנים שהיו במשה עצמו, וממה שמקדים כהונה ללוי' מוכח שהי' כהן גם לפני ימי המילואים. **) ואולי י\"ל, שכהונת משה, מכיון ששימש בחלוק לבן, לא הי' בה הענין ד„לקדשו לכהנו לי\" ולכן נחשב לזר לגבי כהונה זו (ראה לעיל הערה 22). ועפ\"ז יומתק הקס\"ד שבעל מום מותר באכילת קדה\"ק (אף שפשוט שזר שאינו מזרע אהרן אסור בהם), כי גם בע\"ם, אף שהוא פסול לעבודה (שירות), יש בו התואר דכהונה, ולא לקדשו לכהנו לי לשון שירות."],["30","30","יט — כב, כד."],["31","31","ראה רש\"י שם, כב. וראה לעיל הערה 23 בשוה\"ג."]]],[1300061187,"ארט וואו אהרן איז געשטאנען³². אבער „לאחר שתגמור מלאכת המשכן\", וואס די כהנים וועלכע טוען די עבו־דה גייען דאך אריין אין משכן, אין דעם ארט וואו משה פלעגט אריינגיין הערן דעם דיבור השם³³; איז הגם אז צום ווערן ראוי צו טאן די עבודה בפועל האט מען געמוזט אנקומען צו די בגדי כהונה (כנ\"ל ס\"ה), וויבאלד אבער אז אויך דער „לכהנו לי\" פאר דעם איז דאך ענינו ומעלתו³⁴ צו טאן די עבודה אין משכן (מער ניט וואס ס'האט געפעלט דער ענין בפועל — ובדוגמת כהנים איצטער, אדער — איידער זיי זיינען נתחנך געווארן ל־עבודה), ווערט דערפאר געזאגט אויף דעם „ואתה הקרב אליך\".\nז. ע\"פ הנ\"ל, אז אויך דער „לכ־הנו לי\" — וואס מיינט דער עצם ענין הכהונה — איז געווארן ערשט „לאחר שתגמור מלאכת המשכן\", וועט ווערן פארענטפערט א קשיא בדין:\nדער דין איז, אז א כהן ששימש לע\"ז טאר ניט משמש זיין אין מק־דש³⁵. ווערט דא די שאלה: אהרן האט דאך געבויט א מזבח פאר דעם עגל³⁶ [וואס שיטת רש\"י³⁷ איז, אז ביים בויען א מזבח פאר דעם אוי־בערשטן דארף זיין „תחלת עשייתו לשמי\", און לויט דעם קומט אויס, אז דאס בויען א מזבח איז אן ענין פון „שימש\"³⁸]. איז אמת טאקע, אז אהרן'ס כוונה ביי „ויבן מזבח\" איז געווען בכדי „לדחותם\"³⁹, אבער בפועל האט ער דאך געבויט דעם מזבח „לפניו\", פאר דעם עגל — היינט ווי האט ער דערנאך געמעגט טאן די עבודה אין משכן⁴⁰?\nאבער לפי הנ\"ל, אז אהרן ובניו זיינען געווארן כהנים ערשט לאחרי גמר מלאכת המשכן, ווערט עס פאר־ענטפערט בפשטות: דער דין פון כהן ששימש לע\"ז כו' איז דוקא אויב אין דער צייט ששימש איז ער געווען א כהן, און ווי ויבאלד אז בעת'ן בויען דעם „מזבח לפניו\" איז נאך אהרן קיין כהן ניט געווען, איז ער ניט געווען אין כלל פון „כהן ששימש כו'\".\nח. פון די ענינים פון „יינה של תורה\" וואס אין דעם פרש\"י:\nכשם ווי משה רבינו, כאטש ער איז געווען דער רועה פון אלע אידן פון זיין דור, און אויך פון אלע שפעטער־דיקע דורות⁴¹, איז ער פונדעסטוועגן נצטווה געווארן „ואתה הקרב אליך",[["38","38","בדוגמת שחיטה, דאף שכשירה בזר, מ\"מ לדעת רב ששת (מנחות שם) גם כששחט לע\"ז אין קרבנו ריח ניחוח. ואפילו לדעת ר\"נ שם, הרי כתב הרמב\"ם (הל' ביאת מקדש פ\"ט הי\"ג) שגם השוחט לע\"ז ואפילו בשוגג — לכתחלה לא יעבוד."],["39","39","רש\"י תשא שם."],["40","40","ואף שהדין דלא ישמש כו' מדברי קבלה, שנתחדש לאחר זמן — הרי פשוט שת\"ו לומר שהכהן ההוא שהי' בו ענין כזה שלאחר זמן יהי' כהן נפסל על ידו. ולהעיר ממחז\"ל ש„מלבישין לעת\"ל\" (יומא ה, ב) וראה ג\"כ סנה' (צ, ב), ועוד."],["41","41","ראה זח\"ג רעג, א. וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310049\" data-slug=\"tanya\" data-id=\"3401310049\">תניא פמ\"ד</a>: אפס קצהו . . מאיר לכללות ישראל בכל דור ודור כו'."],["32","32","רש\"י שם, כד."],["33","33","תרומה כה, כב. רש\"י שם."],["34","34","ראה לעיל הערה 19."],["35","35","מנחות קט, א. וכ\"ה גם בדרך הפשט, שהרי דין זה יליף שם מקראי. וראה רש\"י מ\"ב כג, ט."],["36","36","תשא לב, ה."],["37","37","יתרו כ, כא."]]],[1300061188,"את אהרן גו' מתוך בני ישראל לכהנו לי\" — „מתוך בני ישראל\" גופא האט ער (ע\"פ ציווי ה') דערנענטערט צו זיך אהרן ובניו, אז זיי זאלן טאן (שפעטער, נאכן נתחנך ווערן בכהונה) די עבודה אין משכן פאר אלע⁴² אידן.\nעד\"ז איז אויך ביי „אתפשטותי' דמשה שבכל דרא ודרא\"⁴³, די נשיאי ישראל⁴⁴ פון יעדן דור, ביז צו כ\"ק מו\"ח אדמו\"ר נשיא דורנו, וואס הגם אז דער ענינו של נשיא איז צו משפיע זיין פאר אלע אידן⁴⁵, ובלשון רש\"י⁴⁶ „הנשיא הוא הכל\" [וואס דערפאר ווערן זיי אנגערופן „ראשי אלפי ישראל\", בדוגמת א ראש, וואס ער איז משפיע חיות צו אלע אברים, ביז אפילו צו צפרנים⁴⁷].\nאיז אבער פאראן די הנהגה פון „ואתה הקרב אליך גו' מתוך בני יש־ראל\", אז צו די וואס גייען „בדרך ישרה אשר הורנו מדרכיו כו'\"⁴⁸ האט דער רבי זיך אפגעגעבן ביחוד⁴⁹, ער האט זיי מקרב געווען און דערהויבן ביז „אליך\", געגעבן זיי זיינע כחות און זיי אריינגענומען אין דעם „חיל ה'\"⁵⁰, בכדי זיי זאלן מפיץ זיין תורתו וכו' צו אלע אידן (ווי די כהנים, וואס דורך „הקרב אליך\", האבן זיי באקו־מען דעם כח פון משה'ן צו טאן די עבודה פאר כל ישראל).\nאון וויבאלד אז אלע ענינים זי'נען בהשגחה פרטית, ובמיוחד ווען עס האנדלט זיך וועגן בני ישראל, און די השגחה פרטית האט אויסדערוויילט אט די אידן צו ווערן דעם רבי'נס תלמידים וכו', מיט וועלכע ער דארף זיך אפגעבן ביחוד ע\"פ תורה⁵¹, קומט דאך במילא אויס, אז דער „ואתה הקרב אליך\" איז ע\"פ ציווי ה' (ב־דוגמת „ואתה הקרב\" ביי משה רבינו).\nט. זיינען אבער פאראן אזעלכע וואס טענה'ן, אז זיי האלטן נאך פאר דער עבודה פון „בגדי כהונה\" און „חינוך למילואים\" — ובפרט אז „ידע אינש בנפשי'\", און ס'קען זיין אז ער איז דורכגעפאלן אין כו\"כ ענינים און האט זיך ניט געפירט ווי עס פאסט פאר א תלמיד פון א נשיא ישראל — היינט ווי קען ער האבן א שייכות וקירוב צו משה שבדורו, בעת ער איז ר\"ל „מחולל מן הכהונה\"?\nאויף דעם זאגט רש\"י, אז אפילו א כהן וואס בפועל קען ער איצטער ניט טאן די עבודה [צי ווייל אים פעלט דער חינוך לכהונה, אדער ווייל ער איז א „בעל מום\" צי א „חלל\"],",[["42","42","ראה רש\"י במדבר ג, יב: שיהיו ישראל שוכרין אותן כו'."],["43","43","זהר שם. תקו\"ז תס\"ט. ועוד."],["44","44","ראה תקו\"ז שם: בכל צדיק וחכם. וראה גם ב\"ר פנ\"ו, ז. — ומ\"מ ישנו ה„אתפשטותא כו'\" גם בכאו\"א מישראל (ראה בהנסמן בהערה 41), וכמ\"ש בתקו\"ז שם — „עד שתין רבוא\" (היינו כללות הדור — ראה שם ובזהר שם). וי\"ל שע\"י ה„צדיק וחכם\" נמשך אח\"כ בכל ישראל."],["45","45","ראה בארוכה לקו\"ש ח\"ד ע' 1050 ואילך ע' 1315."],["46","46","חקת כא, כא. — להעיר מרמב\"ם הל' מלכים (פ\"ג ה\"ו): לבו (דמלך) הוא לב כל קהל ישראל — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081144\" data-slug=\"likkutei-sichot\" data-id=\"1300081144\">לקו\"ש ח\"ח ע' 133</a> הערה 59. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191165\" data-slug=\"likkutei-sichot\" data-id=\"1300191165\">לקו\"ש חי\"ט ע' 165</a> ואילך. חל\"ג ע' 135 ואילך."],["47","47","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא פ\"ב</a>."],["48","48","אגה\"ק סכ\"ז."],["49","49","ראה לקו\"ד ח\"ב רצא, א. וראה גם אגה\"ק סו\"ס זך וביאורו."],["50","50","לשון הרמב\"ם סוף הל' שמיטה ויובל. וראה שם: ולא שבט לוי בלבד אלא כל איש ואיש כו'. וראה שיחת שמח\"ת תרס\"ש (נדפסה בסה\"ש תש\"ב ע' 141 ואילך) ע\"ד היוצא למלחמת בית דוד. עיי\"ש."],["51","51","ראה לקו\"ד שם."]]],[1300061189,"איז ער סיי ווי א כהן, און משה גיט אים זיינע כחות, ווארום אויך לגבי אים שטייט „ואתה הקרב אליך\".\n— ווערן אויס „כהן\" קען ער ניט; דאס איז לגמרי ניט תלוי אין זיין בחירה. זיין בחירה באשטייט נאר אין דעם, צי ער זאל ממלא זיין תפקידו, אדער ח\"ו ניט. אבער זיין תפקיד ליגט אויף עם!\nובמילא האט ער דעם זכות און די אחריות צו [מתקן זיין זיינע „מומים\", אראפנעמען דעם „חילול\", אנטאן די „בגדי כהונה\" וכו', און] טאן די עבודה — ביז צו טאן די עבודה פאר אלע אידן, דורך ברענגען צו זיי דעם אור פון תומ\"צ צוזאמען מיטן מאור שב־תורה, און מאכן אויך זיי פאר „כהנים\".\nי. דער יצה\"ר איז דאך אבער א „קלוגינקער\"⁵², טוט ער זיך אן אין אן איצטלא פון „ענוה\" און הויבט אן אין'טענה'ן: דו זאגסט דאך אליין אז דו האסט נאך גענוג ארבעט מיט זיך אליין — סיי אין „סור מרע\", אויס־היילן די מומים און באפרייען זיך פון חילול; און סיי אין „ועשה טוב\", אנ־טאן די בגדי כהונה און נתחנך ווערן לכהונה — איז אויב „סמוך לפלטין שלך לא כבשת\"⁵³, היינט ווי קענסטו טראכטן וועגן א צווייטן אידן? ווי\nוועסטו — ווייסנדיק ווער דו ביסט — קענען פועל זיין אויף עם?!\nדערויף זאגט רש\"י „לאחר שתגמור מלאכת המשכן\": משה רבינו האט שוין פארענדיקט די מלאכת המשכן פאר יעדער אידן און אויפגעטאן דעם „ושכנתי בתוכם, בתוך כאו\"א מיש־ראל\"⁵⁴; וואס מען מאנט פון דיר איז אויפצוטאן אין דעם צווייטן אידן ניט א נייעס ענין, נאר מגלה זיין דעם „משכן\" וואס איז שוין פארטיק בתוכו (און אויך דאס, דעם גילוי ה־משכן, דארפסטו טאן ניט מיט דיינע כחות נאר בכחו של משה, כנ\"ל ס\"ח).\nאון דעריבער איז א דבר ברור, אז אויב נאר דו וועסט זיך ניט לאזן פארפירן פון די פיתויי היצר און טאן דיין תפקיד, וועסטו זיכער מצליח זיין, אין דיין ארבעט, ביז צום מגלה זיין דעם משכן דאקרי מקדש⁵⁵ וואס ביי יעדער אידן.\nוואס דאס וועט ממהר זיין און מקרב זיין דעם גילוי פון דעם מקדש (הכללי) כפשוטו (דער בית המקדש השלישי), וואס אויך דער מקדש איז שוין פארטיק און ער דארף בלויז אראפקומען און נתגלה ווערן למטה⁵⁶, בביאת משיח צדקנו, בקרוב ממש.\n(משיחת ש\"פ תצוה תשכ\"ז)",[["52","52","ראה היום יום ע' סד."],["53","53","תוד\"ה כיבוש יחיד — ע\"ז כא, א. מספרי ס\"פ עקב. וראה גם סנה' יח, א וש\"נ (בנוגע להלכה): קשוט עצמך ואח\"כ קשוט אחרים."],["54","54","נסמן בלקו\"ש ח\"ג ע' 906."],["55","55","עירובין ב, א."],["56","56","רש\"י ותוס' סוכה מא, סע\"א. רש\"י ר\"ה ל, סע\"א. זח\"א כח, א, ועוד. וראה גם תנחומא נח, יא, ועוד."]]],[1300061190,"<h3>תצוה ב</h3>\nא. בסיום הסדרה — וואו עס רעדט זיך וועגן דעם מזבח הפנימי, און דער פסוק זאָגט „קודש קדשים הוא לה׳”¹ — שטעלט זיך רש״י אויף „קודש קדשים הוא”² און איז מפרש: „המזבח מקודש לדברים הללו בלבד ולא לעבודה אחרת”.\nבפשטות לערנט מען די רש״י, אַז רש״י וויל דאָ באַוואַרענען: דער מזבח הזהב איז דאָך געשטאַנען אין היכל* און ניט אין קדשי קדשים, און ממילא איז אויך זיין קדושה ניט געווען די קדושה פון קדשי קדשים — איז ווי זאָגט מען אויפן מזבח „קדש קדשים”³?\nדערפאַר לערנט רש״י „המזבח מקודש לדברים הללו”, אַז קדש קדשים מיינט ניט אַז דער מזבח האָט די קדושה פון קדש קדשים, נאָר דער פירוש איז: „קדש”, אַז די קדושה פון מזבח איז — פאַר די „קדשים” וואָס ווערן אויסגערעכנט פריער אין פרשה.\nהיות ווי עס שטעלט זיך אָבער דערויף די שאלה: וואָס איז דער חידוש אין דעם; דאָס איז דאָך מובן מעצמו אַז דער מזבח איז מקודש צו ברענגען אויף אים די קרבנות וועלכע מ׳דאַרף אויף אים מקריב זיין? דעריבער איז רש״י מוסיף „בלבד, ולא לעבודה אחרת”, אַז מיט „קדש קדשים” מיינט ניט דער פסוק צו זאָגן דעם חיוב וואָס אין דעם, נאָר די שלילה, אַז ער איז מקודש נאָר פאַר די קדשים, און ניט פאַר אַן אַנדער עבודה.\nואעפ״י אַז אויך אין דעם איז קיין חידוש ניטאָ; אויך דאָס געפינט מען שוין פריער⁴ — און בפירוש: „לא תעלו עליו קטרת זרה וגו׳” — פונדעסטוועגן חזר״ט עס איבער דער פסוק נאָכאַמאָל, בכדי צו מוסיף זיין נאָך אַן עשה אויף דעם וואָס וועט מקריב זיך אויפן מזבח הפנימי אַנדערע קרבנות, אַז ער זאָל עובר זיין ניט בלויז אויפן לאו „לא תעלו גו׳”, נאָר אויך נאָך אויף אַ ציווי (אויף דער עשה „קדש קדשים”, לאו הבא מכלל עשה⁵ עשה).\nב. לויט דעם פירוש איז אָבער ניט מובן:\nא) פון דעם לשון הפסוק „קדש קדשים הוא לה׳” איז משמע, אַז אויך דער וואָרט „קדשים” באַציט זיך צום מזבח אַליין (אַז דער מזבח איז קדש קדשים צום אויבערשטן), אָבער לויט רש״י׳ס פירוש „קדש — קדשים”, אַז דער מזבח איז מקודש צו „קדשים”, איז דאָך ניט גלאַטיק דער סיום הכתוב „לה׳”?\nב) וויבאַלד אַז מיט זיין פירוש „המזבח מקודש כו׳” איז רש״י מפרש די ווערטער „קדש קדשים”, אַז דער",[["1","1","כ״ה בדפוס ראשון. וכן הובא גם ברא״ם."],["2","2","פרשתנו ל, ו."],["3","3","והרי פשטות הל׳ מכריחה ההפרש בין הקדושה שב„קדש” להקדושה שב„קדש הקדשים”. ונאמר והבדילה הפרוכת לכם בין הקודש ובין קדש הקדשים (תרומה כו, לג). ועד כדי כך שאפילו כהן גדול אסור להכנס בו כ״א ביוהכ״פ ובתנאים מיוחדים (ר״פ אחרי ובפרש״י. וראה גם פרש״י לעיל כט, ל)."],["4","4","פרשתנו ל, ט."],["5","5","ראה פרש״י שמיני יא, ג."]]],[1300061191,"מזבח איז מקודש בלויז פאַר די קדשים וואָס שטייען פריער — האָט דאָך רש״י געדאַרפט שרייבן „המזבח מקודש לקדשים הללו כו׳”, פאַרוואָס איז ער משנה און זאָגט „לדברים הללו”?\nג) רש״י׳ס חידוש איז דאָך בלויז בנוגע צום פירוש פון „קדש קדשים”, אָבער אַז אָט־די ווערטער באַציען זיך צום מזבח — וועגן וועמען עס רעדט די גאַנצע פרשה — איז דאָך אַ דבר הפשוט. האָט ער לכאורה געדאַרפט מפרש זיין בלויז דעם מיין פון „קדש קדשים” („מקודש לדברים הללו כו׳”) — אָבער רש״י זאָגט „המזבח מקודש כו׳”. וואָס איז ער מוסיף מיטן וואָרט „המזבח”?\nג. בנוגע צו דער דריטער שאלה, האָט מען געקענט לכאורה פאַרענטפערן:\nעס זיינען פאַראַן מפרשים⁶ וואָס לערנען אַז „קדש קדשים הוא לה׳” גייט ניט אויפן מזבח, נאָר אויף אהרן: התחלת הפסוק איז דאָך „וכפר אהרן גו׳”, און אויף אים (אויף אהרן) איז ער מסיים „קדש קדשים הוא לה׳”. און ווי עס שטייט אין דברי הימים⁷ „ויבדל אהרן להקדישו קדש קדשים”.\nקען מען אָבער ניט זאָגן אַז רש״י׳ס כוונה מיטן „המזבח” איז צו שולל זיין אָט־דעם פירוש⁸ — ווייל⁹\nא) לפי פשוטו של מקרא איז מובן אויך אָן רש״י׳ס פירוש אַז „קדש קדשים גו׳” גייט אויפן מזבח און ניט אויף אהרן, וואָרום די גאַנצע פרשה¹⁰ רעדט דאָ וועגן דעם מזבח¹¹, ניט וועגן אהרן. און „וכפר אהרן גו׳”, איז דאָ בלויז אַ פרט אין דיני מזבח — האָט דאָך ניט קיין אָרט אין פשוטו של מקרא אַז די תורה זאָל דאָ, אין פרשת המזבח, מבאר זיין די מעלה פון אהרן¹².\nב) ווען רש״י זאָגט „מקודש לדברים הללו כו׳” — אויך אָן דעם וואָרט „המזבח”, וויס מען שוין ממילא אַז „קדש קדשים” גייט אויפן מזבח און ניט אויף אהרן, איז דאָך הדרא קושיא לדוכתא: וואָס איז רש״י אויסן מיטן צוגעבן דעם וואָרט „המזבח”?\nד. נוסף צו די דיוקים הנ״ל וואָס בפירוש רש״י דאָ אויפן אָרט, איז דאָ איין שווער פון אַנדערע ערטער:\nדער לשון „קדש קדשים” שטייט שוין פריער אין דער סדרה¹³ בשייכות צום מזבח החיצון (וואָס זיין קדושה איז, כמובן, אַ קלענערע ווי די קדושה פון מזבח הפנימי), און דאָך שטעלט זיך דאָרט",[["6","6","מלבי״ם עה״פ."],["7","7","א כג, יג."],["8","8","או: לשלול הפירוש (דברי שאול — הובא בתו״ש עה״פ) ש„קדש הקדשים הוא” קאי על יוהכ״פ — „אחת בשנה”."],["9","9","נוסף לזה: לפי הפירוש ש„קדש קדשים” קאי על אהרן, מוכרח לומר ש„קדש קדשים” קאי על קדושת כה״ג, שהרי „אין עבודת יוהכ״פ כשרה אלא בו” (רש״י לעיל כט, ל), ובפשטות, „ויבדל אהרן גו׳ הוא ובניו עד עולם” קאי על כל בני אהרן שנבדלו לכהונה, וכהמשך הפסוקים (דה״י שם, יד) ולא כבני משה ש„יקראו על שבט הלוי”. וראה גם רש״י קרח טז, ג׳ וה׳. וכן בנוגע ליוה״כ (ראה הערה שלפנ״ז), לא נמצא בכתובים שנקרא „קדש קדשים”."],["10","10","גם בפסוק זה עצמו, פי׳ „קרנותיו” הוא קרנות המזבח וכן „עליו” קאי על המזבח."],["11","11","וכהתחלתה „ועשית מזבח” — ע״ד „ועשו ארון” (תרומה כה, י) ובכל „אהל מועד וכליו”."],["12","12","או המעלה דיוה״כ, כי כל ענין יו״כ נזכר כאן רק בדרך אגב בנוגע לדיני המזבח. ובפרט שבכתוב נאמר רק „אחת בשנה” ואינו מפרש זמנו."],["13","13","כט, לז. וראה גם פ׳ תשא ל, כט: „והיו קדש קדשים” וקאי על כל כלי המשכן (גם מזבח העולה וכיור שהיו בחצר המשכן)."]]],[1300061192,"ניט רש״י צו מפרש זיין דעם לשון „קדש קדשים”.\nאון אפילו אַז מען וועט בדוחק איינלערנען אַז רש״י מיט זיין פירוש דאָרט „ומה היא קדושתו — כל הנוגע במזבח יקדש כו׳”, מיינט צו מפרש זיין אויך דעם לשון „קדש קדשים” — אַז דער „קדש” (קדושה) פון מזבח איז פאַר „קדשים”, ד. ה. צו הייליק מאַכן „כל הנוגע גו׳”¹⁴\n— איז אָבער ווייטער אין פ׳ במדבר*¹⁴, זאָגט רש״י בפשטות אַז אַלע כלי המשכן (וואָס זיינען געווען במשא בני קהת), אַריינגערעכנט אויך „המזבחות” (מזבח הפנימי און מזבח החיצון), הייסן „קדש הקדשים” המקודש בכולן (וואָס דער טעם דערפון איז פאַרשטאַנדיק: מצד דעם וואָס זיי זיינען הייליקער פון די יריעות און קרשים וכו׳ — די משא פון בני גרשון און בני מררי).\nאיז דאָך ניט מובן: וואָס קוועטשט רש״י׳ן דער לשון „קדש קדשים” פון אונזער פסוק וואָס שטייט ביי מזבח הפנימי, בשעת אַז דער לשון שטייט שוין אפילו ביים מזבח החיצון? אויך: באַ ביידן קען מען דאָך טייטשן מקודש פון די יריעות כו׳¹⁵?\nה. איז דער ביאור אין דעם:\nוואָס רש״י׳ן איז שווער אין „קדש קדשים הוא” פון אונזער פסוק איז (ניט ווי אַזוי ס׳איז שייך צו זאָגן אויפן מזבח „קדש קדשים”, נאָר אדרבה): צוליב וואָס דאַרף דער פסוק זאָגן אַז ער איז „קדש קדשים” — דאָס איז דאָך מובן מעצמו, ובמכש״כ פון מזבח החיצון?\nאון אויף דעם ענטפערט רש״י, אַז מיט די ווערטער „קדש קדשים” גיט דער פסוק אַ טעם אויף דעם איסור „לא תעלו גו׳”: ווייבאַלד אַז ער איז „קדש קדשים” (צווישן „קדשים” גופא איז ער „קדש” — ער איז הייליקער פון אַנדערע קדשים, אפילו פון דעם מזבח החיצון), דעריבער איז ער מקודש נאָר „לדברים הללו” (קטרת און מתן דמים פון חטאת הכפורים) און מען טאָר ניט טאָן אויף אים קיין אַנדער עבודה, בכדי ניט צו מוריד זיין אים פון זיין קדושה.\nאון דערפאַר זאָגט רש״י „לדברים הללו” און ניט „לקדשים הללו” — ווייל דער וואָרט „קדשים” פון פסוק באַציט זיך (ניט אויף קטרת און מתן דמים ווי מ׳קען לערנען בהשקפה ראשונה, נאָר) אויפן מזבח, אַז ער איז „קדש קדשים”.\nאון דערפאַר זאָגט רש״י „המזבח מקודש כו׳”, בכדי צו מדגיש זיין דעם חידוש וואָס דער פסוק טוט אויף מיט זיין געבן דעם טעם „קדש קדשים” אויפן איסור „לא תעלו גו׳”: דאָס איז ניט אַ טעם בעלמא, נאָר דער טעם איז אויך אַ גדר אין דעם איסור „לא תעלו”, אַז",[["14","14","ודוחק גדול לפרש כן, כי נוסף על זה שבפרשתנו שם מעתיק רש״י (לפי רוב הדפוסים, מה שאין כן בדפוס ראשון) רק „והי׳ המזבח קדש” ואינו מעתיק „קדשים” (ובפ׳ תשא שם מפרש הוא את פירושו (לפי כל הדפוסים) על „וקדשת אותם”) — באם כוונת רש״י היתה ש„(קדש) קדשים” קאי לא על המזבח עצמו (ורק שהוא קודש לקדש את כל הנוגע בו), הו״ל לרש״י לכתוב זה בפירוש. ובפרט שמפשטות לשונו (בפ׳ תשא שם) „משיחה זו מקדשתם להיות קדש קדשים” משמע ש„קדש קדשים” קאי על הכלים עצמם (ומה שמפרש „ומה היא קדושתם כל הנוגע כו׳”, הוא לפרש במה קדושתם מתבטאת — דאל״כ, מהו החידוש שבכתוב (וע״ד המבואר לקמן סעיף ה׳)). *14) ד, ד. וראה גם רש״י שם פסוק טז."],["15","15","דפשיטא שאין לחלק בזה בין „קדש קדשים” לבין „קדש הקדשים”."]]],[1300061193,"ער איז פאַרבונדן (ניט מיט דער העלאה פון קטרת זרה, עולה א.א.וו. נאָר) מיט קדושת המזבח*¹⁵: מען טאָר ניט מוריד זיין דעם מזבח פון זיין קדושה.\nו. אין רש״י זיינען דאָך פאַראַן אויך „ענינים מופלאים”¹⁶, אויך פון אַנדערע חלקים שבתורה — זעט מען עס דאָ, ווי דורך רש״י׳ס פירוש „המזבח מקודש כו׳” ווערט פאַרענטפערט אַ קשיא אין חלק ההלכה שבתורה, ובהקדים:\nדער לאו „לא תוכל לאכול בשעריך מעשר דגנך תירושך ויצהרך”¹⁷ ווערט גערעכנט אין מנין המצות פאַר דריי באַזונדערע לאוין¹⁸: מען טאָר ניט עסן חוץ לירושלים — מעשר שני של דגן; מעשר שני של תירוש; און מעשר שני של יצהר. און ווען איינער עסט מעשר שני פון דגן, תירוש און יצהר (חוץ לירושלים), קומט אים דריי מאָל מלקות¹⁹.\nאַנדערש איז דער לאו „את כספך לא תתן לו בנשך ובמרבית לא תתן אכלך”²⁰: וואָס ער ווערט גערעכנט²¹ במנין המצות נאָר פאַר איין לאו (און ווען ער וואָלט ניט געווען קיין „לאו שניתן להשבון” און עס וואָלט אויף אים געקומען מלקות²² — וואָלט געקומען אויף אים בלויז איין מאָל מלקות²³).",[["","","*15) לכאורה אפשר להקשות: א) מכיון שהאיסור בכולם הוא לפי שהם „עבודה אחרת” — זרים למזבח, למה נאמר „זרה” גבי קטרת דוקא, והול״ל „זרה” לאחרי „נסך” או קודם „קטרת”? ב) למה הוצרך הכתוב לפרט — קטרת (זרה), עולה ומנחה ונסך — דהו״ל לקצר „לא תעשו עליו קרבנות זרים” (או כיו״ב) ויתאים למ״ש במזבח החיצון: וזה אשר תעשה גו׳ כבשים גו׳ ועשרון גו׳ ונסך גו׳? אבל — כבר תירץ רש״י קושיות אלו בפירושו בפסוק שלפנ״ז במש״כ „לא תעלו עליו — על מזבח זה. קטרת זרה — שום קטורת של נדבה כולן זרות לו חוץ מזו. ועולה ומנחה — ולא עולה ומנחה, עולה של בהמה ועוף ומנחה היא של לחם”. דלכאורה מאי קמ״ל רש״י בכו״ז? ולמה העתיק גם „ולא תעלו” אף שמפרש רק „עליו”? ולמה לא פי׳ מה זה עולה ומנחה — כשהוזכרו לפני זה? ועוד. וכוונת פרש״י (עכ״פ בקיצור): לא תעלו עליו — על מזבח זה. קטרת זרה (וקשה כיון דזרה היא בודאי בכמ״מ אסורה. ומתרץ דאדרבה קודש היא אלא שהיא דנדבה ולכן) זרות לו. ועפ״ז קשה דא״כ כל המנויים בכתוב „זרה” הם. ומתרץ שהכוונה ב„זרה” הוא (לא לטעם האיסור, כ״א) להקטורת עצמה. דמכיון שישנה קטורת שמותרת להעלות עליו, הוצרך הכתוב לפרש „קטרת זרה”. וזהו גם הטעם מה שהכתוב אינו כולל „קטרת” יחד עם עולה ומנחה — כי חלוקים הם: האיסור בקטרת הוא דוקא ב„זרה”, משא״כ „עולה ומנחה” אין בהם צד היתר. וכיון שמוכרח לפרט קטרת (סמים) בפ״ע, מפרט ג״כ שאר הסוגים* בפ״ע: עולה** (בהמה ועוף) ומנחה (לחם) ונסך. *) ואינו מפרט חטאת וכו׳ — כי אינו סוג בפ״ע. ואיסורי׳ פשוט — במכש״כ מעולה. **) ועוד ענין בזה: מכיון שגם על „עולה” נאמר (לעיל כט, יח) „והקטרת”, וכן לאידך גיסא, גם על „קטרת” נאמר כאן „לא תעלו” — לכן מפרש ש„עולה” היא רק של בהמה ועוף."],["16","16","של״ה במס׳ שבועות שלו (קפא, א)."],["17","17","ראה יב, יז."],["18","18","בספהמ״צ להרמב״ם שרש ט׳ ובלאוין קמא־ג. (ולדעת הרמב״ן (בשרש ט׳) — בלאו אחד)."],["19","19","כריתות ד, סע״ב. רמב״ם בספהמ״צ שרש ט׳, ל״ת קמג ובהל׳ מע״ש פ״ב ה״ה."],["20","20","בהר כה, לז."],["21","21","בספהמ״צ להרמב״ם ל״ת רלה."],["22","22","ראה רמב״ם הל׳ מלוה ולוה פ״ד ה״ג."],["23","23","ראה ספהמ״צ הנ״ל שרש ט׳: ומה שביארו שהוא חייב אחת על הכל נמנה אותו מצוה אחת."]]],[1300061194,"ולכאורה, אדרבה: ביי „מעשר דגנך תירושך ויצהרך” שטייט בלויז איין מאָל „לא”; און ביי נשך ותרבית שטייט צוויי מאָל „לא” („את כספך לא תתן לו בנשך ובמרבית לא תתן אכלך”), היינט פאַרוואָס ווערט ער גערעכנט בלויז ווי איין לאו? — שטייט דער טעם דערויף²⁴: ווייל „אי אתה מוצא נשך בלא תרבית ולא תרבית בלא נשך” זיינען נשך ותרבית איין ענין²⁵, ובמילא זיינען די צוויי אזהרות (די צוויי מאָל „לא”) איין ציווי, נאָר דער זעלבער ציווי ווערט איבערגע׳חזר׳ט צוויי מאָל לחיזוק הענין²⁶. און ווי דער כלל²⁷ ביי „לא תעשה” (ועד״ז ביי מצות עשה) אַז ווען איין און דער זעלבער איסור שטייט אין תורה כמה פעמים, כאָטש אַז ביים עובר זיין אויף אים איז מען עובר „על אזהרות רבות”, רעכנט ער זיך (במנין המצות) פאַר איין לאו, ווייל ס׳איז דער זעלבער ענין.\nז. קען מען דערויף לכאורה פרעגן: אמת טאַקע אַז „נשך” און „תרבית”, ווייבאַלד זיי קענען ניט זיין איינער אָן דעם אַנדערן, זיינען זיי „חדא מילתא” — ווייבאַלד אָבער אַז דער פסוק רעכנט אויס אויך די פרטים האסורים בנשך ותרבית און זיי זיינען פאַרשידן — „כספך” און „אכלך” — אויף כסף ואוכל איז דאָך ניט שייך צו זאָגן „אי אתה מוצא זה בלא זה” — דאַרף דאָך דער איסור פון נשך ותרבית איינגעטיילט ווערן אין צוויי לאוין: איין לאו אויף כסף און איין לאו אויף אוכל — ווי דאָס איז ביים איסור „לא תוכל לאכול בשעריך מעשר דגנך תירושך ויצהרך” וואָס רעכנט זיך פאַר דריי לאוין, אויף דגן, אויף תירוש און אויף יצהר?\nאיז די הסברה אין דעם:\nדער איסור „לא תוכל לאכול בשעריך גו׳” איז (ניט אויף דער כללות הפעולה פון אכילת מעשר שני חוץ לחומה, נאָר) אויף אכילת מעשר דגן, מעשר תירוש און מעשר יצהר. [וכדמוכח פון דעם וואָס דער פסוק רעכנט אויס „דגנך תירושך ויצהרך” און ער איז זיי ניט כולל צוזאַמען מיטן לשון „לא תוכל לאכלם”²⁸] און דערפאַר זיינען זיי דריי באַזונדערע לאוין²⁹.\nמשא״כ דער איסור „את כספך לא תתן לו בנשך ובמרבית לא תתן אכלך” איז ניט אויף דער הלואה פון כסף און אוכל [וואָרום מיט „את כספך לא תתן לו בנשך” ווערט דאָך געמיינט ניט בלויז כסף, און מיט „במרבית לא תתן אכלך” ווערט דאָך געמיינט ניט בלויז אוכל, נאָר ביידע מיינען „כל דבר”³⁰], נאָר",[["24","24","ספהמ״צ הנ״ל ל״ת רלה (מב״מ ס, ב)."],["25","25","ובדוגמת „שעטנז לא יעלה עליך” ו„לא תלבש שעטנז” (קדושים יט, יט. תצא כב, יא), שאף שהם פעולות מתחלקות, מ״מ מכיון שא״א ללבישה בלי העלאה — אין ההעלאה נמנית ללאו בפ״ע ואין לוקין עלי׳ (בג״א בשרש ט׳ ד״ה נראה לי שהנכון כדברי הרב שאין לוקין בו)."],["26","26","ובדוגמת „לא תפאר אחריך” ו„לא תעולל אחריך” (תצא כד, כ־כא), שהם לאו אחד ורק ש„האזהרה נכפלת במלות מתחלפות” (רמב״ם בשרש הנ״ל)."],["27","27","ראה בארוכה בשרש הנ״ל."],["28","28","מכות יח, רע״א. כריתות שם ואילך. רמב״ם בספהמ״צ שרש ט׳ ומל״ת קמג ובהל׳ מע״ש שם."],["29","29","ברמב״ם שרש הנ״ל: „ואותן הלאוין שביארו שהוא חייב על כל אחד ואחד, הם שנמנו כל דבר מהם מצוה בפני עצמה”. וכנראה שכוונתו היא, שממה שביארו שחייב על כאו״א אנו יודעים שהאיסור הוא על הדברים הפרטים, וכמ״ש ברמב״ם שם „ידענו שהם שמות הרבה”."],["30","30","ב״מ שם ואילך. רמב״ם הל׳ מלוה ולוה רפ״ד."]]],[1300061195,"דער איסור איז אויך אויף דער כללות ההלואה בריבית³¹. און ווייבאַלד אַז אין דער פעולה האסורה פון הלואה בריבית איז דאָך קיין נפקא מינה ניט צי זי קומט דורך כסף, דורך אוכל אָדער דורך כל דבר, רעכנט מען עס דעריבער פאַר איין לאו³².\nח. עפ״י כל הנ״ל האָט לכאורה געדאַרפט אויסקומען לגבי דעם איסור „לא תעלו עליו קטורת זרה ועולה ומנחה ונסך לא תסכו עליו”, וואָס דער פסוק זאָגט ניט דעם איסור אין אַן אופן כללי „לא תעלו עליו קרבן זר”, נאָר ער איז מפרט פרטים: קטורת, עולה, מנחה און נסך — אַז מען זאָל דאָס איינטיילן אין פיר³³ באַזונדערע לאוין (בדוגמת מעשר דגנך, תירושך און יצהרך).\nאון אפילו אַז מען וועט שוין זאָגן בנוגע צו די ערשטע דריי פרטים, אַז היות ווי זיי גייען אַלע אַריין אין „לא תעלו עליו”, איז דער איסור דערביי די כללות הפעולה פון העלאה על המזבח און ניט די העלאה פון קטורת, פון עולה און פון מנחה\n— איז דאָך אָבער בנוגע צו „נסך”, וואָס ער גייט ניט אַריין אין „לא תעלו” נאָר מען זאָגט אויף אים באַזונדער „לא תסכו עליו”³⁴, דאַרף דאָך אַ ודאי אויסקומען לכאורה, אַז ער איז אַ באַזונדער לאו: איין לאו — העלאה על המזבח און אַ צווייטער לאו — ניסוך על המזבח [ובלשון המנחת חינוך³⁵: אכילת מזבח און שתיית מזבח],\nאון לפועל זעען מיר, אַז אַלע מוני המצות — דער רמב״ם³⁶, דער סמ״ג³⁷, (וכן משמע דעת הרמב״ן³⁸) — רעכענען עס פאַר איין לאו³⁹?\nאיז די קשיא פרעגט דער מנחת חי־",[["31","31","משא״כ ב„לא תוכל לאכול בשעריך מעשר דגנך תירושך ויצהרך”, י״ל, שהלאו הוא רק בג׳ מינים אלו. ראה מנ״ח סוף מצוה תמד, שנסתפק בזה."],["32","32","ועפי״ז תתורץ קושיית הלח״מ (בהל׳ מלוה ולוה שם) „איך למד רבינו מדברים אלו (שיש איסור נשך באוכל וריבית בכסף) דנשך ותרבית אחד” — כי באם איסור הנשך הי׳ רק בכסף ואיסור הרבית רק באוכל, הי׳ בהכרח לומר שהם ב׳ לאוין שונים (גם במנין המצות), כבפנים. וי״ל, שזהו ג״כ מה שלאחרי שכתב הרמב״ם „שנאמר את כספך . . כל דבר אשר ישך”, מוסיף: „ולמה נקרא שמו נשך מפני שהוא נושך כו׳”, ורק לאח״ז מסיים (העניין ד„נשך ומרבית אחד הוא”) „ולמה חלקן הכתוב כו׳” — כי אף שב׳ האיסורים דנשך ומרבית הם ב„כל דבר”, אכתי י״ל שהם ב׳ לאוין שונים מצד ה„נשך” וה„מרבית”? ולכן מוסיף: שמה שנקרא נשך הוא „מפני שהוא נושך שמצער את חבירו ואוכל את בשרו”, שמזה מובן שא״א לנשך בלא תרבית ולתרבית בלא נשך."],["33","33","או עכ״פ בג׳ לאוין, דמכיון ש„עולה ומנחה” הוא מין מיוחד (שאין בו היתר כבקטורת — ראה לעיל הערה *15) ה״ז כאילו כפל „ולא עולה כו׳”. ועפי״ז י״ל מש״כ רש״י „עולה ומנחה — ולא עולה ומנחה” — היינו שכאילו כתוב עוה״פ ולא*."],["34","34","ובפרט שנאמר בו עוד פעם „לא”."],["35","35","מצוה קד."],["36","36","מל״ת פב. וראה גם בהל׳ כלי המקדש פ״ב הי״א."],["37","37","לאוין סי׳ רצה."],["38","38","שהרי בהשגותיו ובמל״ת לדעת הרמב״ן (שבסוף ספהמ״צ להרמב״ם) אינו חולק בזה על הרמב״ם."],["39","39","הרלב״ג בפירושו עה״ת עה״פ מונה אותם לשתי לאוין ומביא דעת הרמב״ם, ומסיים: ודעתו רחבה מדעתנו. *) ברא״ם וש״ח כאן, שכוונת רש״י „שמלת לא דרישי׳ דקרא משמש גם על עולה ומנחה”. אבל לפי״ז א״מ: א) מאי קמ״ל? ב) א״כ הו״ל לרש״י לומר „ולא תעלו עליו עולה ומנחה”?"]]],[1300061196,"נוך³⁹* און בלייבט ביי אַ „צע״ג”. אָבער לויט פירוש רש״י „המזבח מקודש כו׳” ווערט עס פאַרענטפערט בפשטות:\nווי געזאָגט, לערנט רש״י אַז דער פסוק גופא איז מסביר דעם טעם האיסור פון „לא תעלו גו׳ לא תסכו גו׳”, אַז דאָס איז ווייל דער מזבח איז „קדש קדשים”, ער איז „מקודש לדברים הללו בלבד ולא לעבודה אחרת”. איז דאָך פאַרשטאַנדיק, אַז דער איסור באַשטייט דאָ [ניט אין די פרטים — פון קטורת עולה ומנחה און נסך, אָדער אפילו אין די פרטים פון אכילת מזבח און שתיית מזבח — נאָר] וואָס מען טוט אויף אים אַן ענין צו וואָס ער איז ניט מקודש. און ווייבאַלד אַז אין דער פעולה האסורה פון טאָן אויף אים אַן „עבודה אחרת” איז דאָך ניטאָ קיין נפקא מינה צי זי ווערט געטאָן דורך קטורת צי דורך נסך, רעכנט מען עס דעריבער פאַר איין לאו⁴⁰ (בדוגמת דעם איסור פון הלואה בריבית).\nועפי״ז יובן וואָס דעם איסור „ולא לעבודה אחרת” זאָגט דער פסוק ניט בפירוש, נאָר ער זאָגט עס אין די ווערטער „קדש קדשים” וואָס פון דעם לערנט מען אָפּ — לפרש״י — „ולא לעבודה אחרת” אין אַן אופן פון „מכלל⁴² הן אתה שומע לאו”:\nוואָלט דער גדר האיסור געווען דאָס וואָס מען טאָר ניט טאָן אויף אים קיין אַנדערע עבודות, איז דאָ אַן אָרט צו זאָגן, אַז יעדער עבודה איז אַ באַזונדער איסור; ווייבאַלד אָבער אַז דער גדר האיסור באַשטייט אין ניט משנה זיין דעם הן — דעם מזבח פון דעם וואָס ער איז „מקודש לדברים הללו בלבד”, איז דאָך קיין נפקא מינה ניט דורך וועלכער עבודה מען איז מוריד דעם מזבח מקדושתו⁴¹.\nט. פון די ענינים פון „יינה של תורה”⁴³ וואָס אין אונזער פירש״י:\nדער חילוק צווישן מזבח הפנימי און מזבח החיצון איז מבואר אין חסידות⁴⁴, אַז מזבח החיצון איז בחי׳ מלכות דאצילות ווי זי קומט אַראָפּ אין עולמות בי״ע, וואָס דערפאַר איז ער געשטאַנען ניט אין היכל נאָר אין חצר (און אין בית המקדש — אין דער עזרה), און מזבח הפנימי איז בחי׳ תפארת דאצילות וואָס איז העכער פון צו יורד זיין אין בי״ע, און דערפאַר איז דער מזבח געווען אין היכל.\nאון דאָס איז אויך דער טעם וואָס אויפן מזבח החיצון האָט מען מקריב געווען קרבנות און אויפן מזבח הפנימי",[["","","39*) שם. — עוד ספרים הדנים בזה, נסמנו בברית משה לסמ״ג שם."],["40","40","ולהעיר מל׳ הרמב״ם בהל׳ כלי המקדש שם: „מזבח הזהב . . מקטירין הקטרת . . ואין מקריבין עליו דבר אחר ואם הקטיר כו׳” (וכאן מפרט פרטים)."],["41","41","רש״י לעיל יתרו כ, יב."],["42","42","עוד י״ל בהלכה — ע״ד הפשט וע״פ פרש״י זה: א) קטורת זרה ועולה כו׳ שהקריבם על יוהכ״פ — דינם כאילו הקריבם במקום שאינו מקודש (ובפרט שרש״י מדגיש „בלבד”). ולכאורה זוהי סברת הקס״ד בזבחים (כו, סע״ב). וי״ל דכן היא גם להמסקנא שם עפמש״ב בשטמ״ק שם דידו אלא כו׳. ב) מכאן בירור להחקירה האם יש בקדשי קדשים גם מקדושת קדשים קלים (ונפק״מ בנודר מקדושת קדשים קלים (את״ל שאין בזה הבחינה דהלך אחר לשון בנ״א) וכיו״ב). ובכל אופן — עדיין בספק האם יש בכהן מקדושת לוי (כיון שהכהונה בכלל נבדלה מלוי) ועאכו״כ — היש בתרומת מעשר מקדושת מעשר. ויש להאריך בכ״ז ואכ״מ."],["43","43","היום יום ע׳ כד."],["44","44","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550132\" data-slug=\"torat-chaim\" data-id=\"2300550132\">תו״ח שמות</a> ד״ה ועשו לי מקדש (תמג, א ואילך — בארוכה). דרמ״צ פו, ב."]]],[1300061197,"האָט מען בלויז מקטיר געווען קטורת (און קיין קרבנות האָט מען אויף אים ניט געטאָרט מקריב זיין), ווייל קרבנות איז דער ענין פון בירורים, וואָס דאָס איז שייך נאָר אין עולמות בי״ע (ווייל דאָרט איז דאָ די מציאות פון רע — דאַרף מען דעריבער מברר זיין דעם טוב פון דעם רע), אָבער אין אצילות איז ניט שייך קיין בירורים, ווייל דאָרט איז „לא יגורך רע”⁴⁵. און וואָס איז יע באַשטאַנען די עבודה אויפן מזבח הפנימי — אין קטורת וואָס ענינה איז (ניט בירורים נאָר) התקשרות, מלשון „בחד קטירא אתקטרנא”⁴⁶ — אויף צו מוסיף זיין אין דער התקשרות צום אויבערשטן.\nאון אַזוי איז אויך אין די צוויי מדריגות פון „מזבח החיצון” און „מזבח הפנימי” שבאדם [וואָס אַלע ענינים פון משכן און מקדש זיינען אויך פאַראַן בנפש האדם⁴⁷]: מזבח החיצון איז בחי׳ חיצוניות הלב⁴⁸ און דאָרט איז שייך (און עס דאַרף זיין) די עבודה פון בירורים. משא״כ מזבח הפנימי איז בחי׳ פנימיות הלב⁴⁸, וואו ס׳איז ניט שייך דער ענין הבירורים, און די עבודה שמצד פנימיות הלב איז — פאַרבינדן זיך טיפער מיטן אויבערשטן.\nיו״ד. אין איינפאַכע אותיות הייסט עס: אַ איד, אַ נשמה בגוף, דאַרף זיך דאָך עוסק זיין ניט נאָר אין לימוד התורה וקיום המצות נאָר אויך אין דברי רשות ווי אכילה ושתי׳, אָבער די דברי הרשות דאַרפן זיין ווי די משנה⁴⁹ זאָגט „וכל מעשיך יהיו לשם שמים” אָדער נאָך העכער⁵⁰ — „בכל⁵¹ דרכיך דעהו”.\nקען מען דאָך מיינען, אַז ווייבאַלד אויך די דברי הרשות טוט ער „לשם שמים” (וואָס די אמיתית הפירוש פון „לשם שמים” איז, אַז זיין כוונה אין טאָן די דברי הרשות איז אינגאַנצן לשם שמים און ביי אים זיינען אין דעם ניט אַריינגעמישט קיין שום אַנדערע כוונות). און עאכו״כ ווען אין די דברי הרשות גופא⁵² איז ביי אים דאָ דער „דעהו” (ידיעת אלקות) מעג ער במילא שוין טאָן די ענינים הגשמיים אויך בפנימיות הלב — זאָגט מען אויף דעם, אַז נאָך אַלעם דעם, ווייבאַלד זיי זיינען פאָרט „מעשיך” און „דרכיך” (מעשי",[["45","45","תהלים ה, ה. — וקאי על עולם האצילות (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380322\" data-slug=\"likkutei-torah\" data-id=\"4001380322\">לקו״ת במדבר ג, ג</a>. רש״נ)."],["46","46","אד״ז (בזח״ג רפח, א)."],["47","47","כמובן ממרז״ל (נסמן בלקו״ש ח״ג ע׳ 906) בתוכו לא נאמר אלא בתוכם בתוך כל אחד ואחד מישראל. וראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550132\" data-slug=\"torat-chaim\" data-id=\"2300550132\">תו״ח שם (תמג, א</a>) שמ״ש בתוכם לשון רבים קאי על ב׳ הבחי׳ שבלב כאו״א מישראל — פנימיות הלב וחיצוניות הלב."],["48","48","תו״ח שם ואילך. דרמ״צ שם. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381039\" data-slug=\"likkutei-torah\" data-id=\"4001381039\">לקו״ת סוכות עח, ד</a>. שמע״צ פו, ד. ועוד."],["49","49","אבות פ״ב מי״ב."],["50","50","ראה בארוכה לקו״ש ח״ג ע׳ 907. 932."],["51","51","משלי ג, ו."],["52","52","וכלשון הכתוב (משלי שם) בכל דרכיך. וראה רמב״ם הל׳ דיעות רפ״ה: „כשם שהחכם ניכר בחכמתו כו׳ כן צריך שיהי׳ ניכר (ה„חכם”) במעשיו כו׳”, שבהמעשים עצמם [וכל העשר סוגים* שמונה שם] יהי׳ ניכר ה„חכם” שבו, שאמיתית ענין החכמה הוא ידיעת אלקות — „דעהו”**. *) כנגד עשר כחות שבאדם, שנשתלשלו (<a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא</a> רפ״ג) מהעשר ספירות. **) עפ״י המבואר בלקו״ש שם ע׳ 932 שבהעבודה ד„בכל דרכיך דעהו” מתבטא אמיתית ענין האחדות ש„אין עוד” — י״ל, שפירוש „החכם ניכר כו׳ במעשיו” הוא ההרגש ש„הוא לבדו הוא ואין זולתו” (ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא פל״ה</a> בהגה״ה)."]]],[1300061198,"דרכי האדם), דאַרפן זיי דערפאַר געטאָן ווערן „בלא לב ולב”⁵³, ניט מיט ביידע מדריגות שבלב — חיצוניות הלב און פנימיות הלב — נאָר בלויז מיט חיצוניות הלב: פנימיות הלב דאַרף מען נוצן נאָר אויף ענינים פון קדושה⁵⁴.\nאון דאָ איז רש״י מוסיף אַז דער גדר האיסור פון „לא תעלו עליו עולה ומנחה גו׳”, וואָס אין עבודה רוחנית בנפש האדם מיינט עס אַז מען טאָר ניט נוצן פנימיות הלב אויף עניני העולם, איז — „המזבח מקודש לדברים הללו בלבד (ובמילא) ולא לעבודה אחרת”. אַז די עניני העולם (אפילו ווען זיי זיינען „לשם שמים” און אפילו אין אַן אופן פון „דעהו”), דאַרפן זיין אַזוי „ווייט” פון פנימיות הלב, ביז אַז מען זאָל זיי גאָרניט דאַרפן שולל זיין — ע״ד ווי מ׳דאַרף ניט שולל זיין אַז אַ חכמה קען מען ניט אָנטאַפּן מיט די הענט⁵⁵ (וואָס דער עצם שולל זיין אַ געוויסע זאַך, דאָס גופא ווייזט דאָך אַז די זאַך האָט עפעס אַ שייכות, נאָר מ׳דאַרף זי שולל זיין⁵⁶), נאָר אַז זיי זאָלן ממילא זיין מושלל פון פנימיות הלב: דורך דעם וואָס די פנימיות זיינע איז „מקודש לדברים הללו בלבד”, ער איז פאַראייניקט מיט תורה ומצות בתכלית היחוד (אין אַן אופן פון „בלבד”), — איז ער ממילא ניט שייך צו עפעס אַנדערש — אפילו ניט צו אַ זאַך וואָס רופט זיך „עבודה” — ווייל דאָס איז אַן „עבודה אחרת”.\nיא. עפ״י הנ״ל איז אויך פאַרשטאַנדיק דער טעם — בפנימיות הענינים — וואָס די צוויי אזהרות „לא תעלו עליו גו׳” און „לא תסכו עליו” ווערן גערעכנט במנין המצות פאַר איין לאו — כאָטש (מצד חומר האיסור⁵⁷) „חלקן הכתוב לעבור עליו בשני לאוין”:\nדי התחלקות אין מצות, דאָס וואָס זיי זיינען במנין תרי״ג, איז אין דער דרגא פון מצות ווי זיי ווערן נמשך בבחינת גילוי, וואָס דאַן זיינען זיי „ארחות הוי׳”⁵⁸ לשון רבים — „תרי״ג ארחין”. אַנדערש איז ווי מצות זיינען מצד המצווה, בעל הרצון, דאָרט זיינען זיי „אורח צדיקים”⁵⁹ לשון יחיד — „חד ארחא”⁶⁰.\nעס זיינען אָבער פאַראַן מצות וואָס אויך נאָך דעם וואָס זיי ווערן נמשך אין בחי׳ גילוי הרצון, ווערט אין זיי נרגש מער בגילוי דער כח המצווה.\nויש לומר אַז דאָס איז דער טעם",[["53","53","לשון הכתוב דה״א יב, לג. וראה ד״ה כי עמך הסליחה תש״ט פ״ז."],["54","54","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370411\" data-slug=\"torah-or\" data-id=\"3901370411\">ראה בארוכה ד</a>״ה וירד תרס״ב וד״ה בראשית ברא תש״ה (פ״ל), שהבירור שמדברי הרשות מגיע רק בבחי׳ „לבוש מלכות”, ודוקא ע״י המצות ממשיכים בחי׳ „כתר מלכות” (ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370286\" data-slug=\"torah-or\" data-id=\"3901370286\">תו״א צא, סע״ב</a>. שערי אורה סד, א), שמכיון ששרש הנשמות הוא בהעצמות (בחי׳ כתר מלכות) לכן עבודתם (ובעיקר מצד פנימיות הלב) צ״ל לא בבירור דברי הרשות, כ״א בתומ״צ. אלא שמ״מ צריך גם לעבודת הבירורים [בחי׳ מזבח החיצון, שממנו דוקא היו מביאים גחלים לחתות והיו נותנים ע״ג מזבח הפנימי (רמב״ם הל׳ תמידין ומוספין פ״ג ה״ד)], כי זהו הקדמה שעי״ז מתעלה אח״כ הנשמה לשרשה האמיתי ממש (ראה אוה״ת שמע״צ ע׳ א׳תתע)."],["55","55","שער היחוד והאמונה פ״ט (פו, ב)."],["56","56","ובדוגמת הידוע (ראה ד״ה תכלית חכמה תרפ״ט פ״ב) שידיעת השלילה שייכת דוקא בבחי׳ הסובב, ולא בעצמות אוא״ס. וראה שער היחוד והאמונה שם: „לא שייך כלל לומר בו שאי אפשר להשיגו”. עיי״ש."],["57","57","ראה ספהמ״צ להרמב״ם שרש ט׳: „וכדי שיודע ג״כ שזה הענין עון גדול מאד אחר שבאה בו אזהרה אחר אזהרה”."],["58","58","תהלים כה, יו״ד."],["59","59","משלי ד, יח."],["60","60","אד״ר (בזח״ג קכט, א). הובא ומבואר בד״ה תקעו תרצ״א פ״ז (סה״מ קונטרסים ח״א קכה, א). הוי׳ יחתו מריביו תש״י פ״ד."]]],[1300061199,"וואָס „לא תעלו” און „לא תסכו” ווערן ניט צעטיילט אין צוויי באַזונדערע מצות — ווייל אויך ווי זיי ווערן נמשך בגילוי זיינען זיי פאַרבונדן מיט פנימיות הלב וואו ס׳איז שורה דער עצם הנשמה, בחי׳ יחידה, וואָס איז פאַראייניקט מיט עצמות.\nבנוגע צו שכר ועונש ברוחניות, וואָס די רוחניות איז פאַרבונדן מיט גילויים, איז טאַקע „חלקן הכתוב לעבור עליו בשני לאוין” (וואָס באַווייזט אַף מער חומר בהאיסור — ובמילא מער בשכר ועונש רוחני), אָבער אין מנין המצות (וואָס איז נוגע צום ציווי גופא) און אַזוי אויך בנוגע מלקות (שמייסן אַ אידישן גוף, וואָס אַ אידישער גוף איז פאַרבונדן מיט עצמות⁶¹) — איז עס בלויז איין לאו — למעלה מהתחלקות.\nיב. ווייבאַלד אַז אַלע ענינים פון נגלה דתורה (ניט בלויז די הלכות גופא, נאָר אויך די דרכי הלימוד) ווערן נשתלשל פון זייער ענין אין פנימיות התורה, איז דערפון פאַרשטאַנדיק, אַז דער גילוי רצון עצמי — למעלה מהתחלקות, ווערט נמשך דוקא בשעת די שלילה פון עניני העולם מצד פנימיות הלב אין עבודת האדם, איז אין אַן אופן פון בדרך ממילא\n— אַזוי ווי אין נגלה, אַז דאָס וואָס „לא תעלו” און „לא תסכו” ווערן גערעכנט פאַר איין לאו איז עס מצד דעם וואָס דער גדר האיסור ביי זיי איז אַ תוצאה פון „מקודש לדברים הללו בלבד”, כנ״ל סעיף ח׳.\nדער ביאור אין דעם איז:\nאין פנימיות הלב גופא זיינען פאַראַן צוויי מדריגות⁶²:\nא) „הארת נקודת הלב” — ובכללות, בחי׳ חי׳ — וואָס האָט נאָך אַ שייכות צו כחות הגלויים. איז אין דער מדריגה, כאָטש זי איז העכער פון עבודת הבירורים, האָבן אָבער די עניני העולם (וועלכע מען דאַרף מברר זיין) עפעס אַ תפיסת מקום, און מען דאַרף זיי שולל זיין.\nב) „עצמיות נקודת הלב” — ובכללות, בחי׳ יחידה — וואָס האָט קיין שום שייכות ניט צו כחות הגלויים. ובמילא זיינען די עניני העולם מושלל דאָרט בדרך ממילא.\nאון דאָס איז דער ביאור אין דעם וואָס דער רצון עצמי שלמעלה מהתחלקות ווערט נתגלה דוקא בשעת די עניני העולם זיינען מושלל בדרך ממילא: כל זמן די עניני העולם האָבן נאָך ביי אים עפעס אַ תפיסת מקום אַז ער דאַרף זיי שולל זיין, איז אַ ראי׳ אַז ביי אים איז נתגלה געוואָרן בלויז בחי׳ חי׳ וואָס זי איז נאָך ניט פאַראייניקט בתכלית היחוד מיט עצמות;\nאון דוקא ווען ביי אים זיינען אויסער אלקות אַלע ענינים — בבחי׳ „עבודה אחרת” — און מושלל בדרך ממילא מצד גילוי בחי׳ היחידה (וואָס אין איר זיינען ניטאָ קיין נטיות כו׳⁶³), דאַן קומט ער צום גילוי רצון עצמי, ווייל יחידה איז פאַראייניקט מיט „יחיד” — „חבוקה ודבוקה בך כו׳ יחידה ליחדך”⁶⁴.\n(משיחת ש״פ תצוה תשכ״ה)",[["61","61","תורת שלום ע׳ 11. 120."],["62","62","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380861\" data-slug=\"likkutei-torah\" data-id=\"4001380861\">לקו״ת תצא לו, א</a>."],["63","63","ראה מאמר דפ׳ ויק״פ עדר״ח קרוב לסופו."],["64","64","נוסח התפלה בהושענות."]]],[1300061200,"<h3>פורים</h3>\nא. ס׳איז ידוע¹ דער פירוש פון בעל־שם־טוב אויף „הקורא את המגילה למפרע לא יצא“²: ווען איינער לייענט די מגילה און ער מיינט אַז דער סיפור וואָס ווערט דאָרט דערציילט האָט פּאַסירט (נאָר) אַמאָל, „למפרע“, און ניט איצטער איז דער נס, איז — „לא יצא“. דער תכלית פון קריאת המגילה איז אָפּצולערנען זיך פון איר ווי אַ איד דאַרף זיך פירן איצטער.\nדאָס איז אַזוי בנוגע אַלע ענינים (און פסוקים³) פון דער מגילה, אַז מען דאַרף זיי לייענען ניט אין אַן אופן פון „למפרע“. על אחת כמה וכמה בנוגע דעם כללות הסיפור פון דער מגילה, און מכ״ש בשייכות מיטן פסוק וואָס איז מבאר דעם נאָמען „פורים“\n— וואָרום וויבאַלד אַז דער נאָמען פון אַ זאַך ווייזט אויף איר מהות⁴, הייסט עס דאָך, אַז דער פסוק איז מבאר דעם מהות פון „פורים“, וואָס דאָס איז די נקודה העיקרית פון דער מגילה —\nאיז אין דעם פאַראַן אַ הוראה נצחית בכל זמן ובכל מקום, סיי פאַרן כלל ישראל און סיי פאַר יעדער אידן אלס יחיד.\nב. דער פסוק⁵ זאָגט „על כן קראו לימים האלה פורים — על שם הפור“.\nאיז אין דעם ניט מובן:\nדער וואָרט „פור“ איז ניט קיין לשון־הקודש׳יקער וואָרט, נאָר לשון פרסי⁶; און ווען דער פסוק⁷ זאָגט „הפיל פור“ איז ער מוסיף „הוא הגורל“, וואָס דערמיט פאַרטייטשט ער דעם וואָרט „פור“ אין לשון־קודש, אין וועלכן די מגילה איז געשריבן.\nאיז ניט מובן: פאַרוואָס הייסט דער יו״ט „פורים“ (על שם הפור⁸) אין לשון פרסי און ניט „גורלות“ (על שם הגורל) אויף לשון־קודש, ווי אַלע ימים־טובים (אויך חנוכה — אַ יו״ט מדרבנן) וואָס ווערן גערופן בלשון־הקודש?\nאויך איז ניט פאַרשטאַנדיק: דער נאָמען פון יו״ט האָט דאָך געדאַרפט אויסדריקן (ווי אין אַלע אַנדערע יו״ט) דעם נס און הצלה (פון גזירת המן). אָבער דער נאָמען „פורים“ „על שם הפור“ ווייזט גאָר אויפן היפך דערפון, אויף דעם „פור“ וואָס המן הרשע האָט געוואָרפן מיט דער כוונה „להומם ולאבדם“ — ח״ו היל״ת?\nג. נאָך אַן ענין איז פאַראַן אין מגילת אסתר וואָס איז פאַרבונדן מיט כללות המגילה, און דאָס איז — וואָס אין דער גאַנצער מגילה ווערט ניט דערמאָנט דעם אויבערשטנס נאָמען, אַנדערש פון אַלע אַנדערע כתבי ה־",[["1","1","הובא בס׳ דברי שלום פ׳ בא."],["2","2","רפ״ב דמגילה."],["3","3","וכמו הדין ד„למפרע“ בפשטות, שאפילו אם קרא למפרע רק פסוק אחד [ואפי׳ באופן שהענין אינו משתנה עי״ז] — לא יצא (שו״ע או״ח סתר״צ ס״ו. ט״ז שם)."],["4","4","ראה בארוכה לעיל ע׳ 35 ואילך ובהערות שם."],["5","5","אסתר ט, כו."],["6","6","ראב״ע שם ג, ז."],["7","7","אסתר שם, ט, כד."],["8","8","בד״ה ליהודים היתה אורה ושמחה תרכ״ו, שמה שאמרו (מגילה טז, ב) שמחה זה יו״ט, הוא לפי שהמועד דפורים לא יתבטל. וראה בארוכה שיחת פורים וש״פ תשא תשכ״ח."]]],[1300061201,"קודש וואו אין יעדן ספר ווערט דערמאָנט דעם אויבערשטנס נאָמען כמה וכמה פעמים.\nוואָס דאָס ווייזט אויף אַ העלם והסתר גדול ביותר⁹:\nבכלל, יעדער איד, אפילו ווען ער רעדט¹⁰ בעניני הרשות, איז „שם שמים שגור¹¹ בפיו“¹²; און ווער רעדט ווען עס קומט צו שרייבן („מעשה רבה“), איז דאָך איינגעפירט בכל תפוצות ישראל (וואָס „מנהג ישראל תורה הוא“¹³), אַז אפילו ווען מ׳שרייבט אַ\nבריוו וועגן עניני חול, פאַנגט מען אים אָן מיט „ב״ה“ (אָדער כיו״ב)\n[וואָרום וויבאַלד אַז „מלא כל הארץ כבודו“¹⁴ און „לית אתר פנוי מיני׳“¹⁴*, איז דעריבער אָפּגעלייגט ביי אַ אידן בפשטות, אַז וועגן וואָס עס זאָל זיך ניט האַנדלען, איז דאָס פאַרבונדן מיטן אויבערשטן¹⁵].\n— און דאָ איז די גאַנצע מגילה, איינע פון די כ״ד כתבי הקודש, וואָס אין איר ווערט ניט דערמאָנט „שם שמים“ קיין איין מאָל¹⁶!\nד. ווי דערמאָנט פריער (סעי׳ א׳), ווערט דער תוכן פון יעדער זאַך אָנגעוויזן אין זיין נאָמען. און אויך דער העלם והסתר פון דער מגילה, ווערט אָנגעוויזן אין איר נאָמען:\nדער שם המגילה איז „מגילת אסתר“¹⁷ (אָדער „אסתר“¹⁸), און אסתר ווייזט דאָך אויף דעם ענין פון הסתר¹⁹,",[["9","9","בפתיחת הראב״ע למג״א: „וזאת המגילה חברה מרדכי . . והעתיקוה הפרסיים ונכתבה בדברי הימים של מלכיהם והם היו עובדי ע״ג והיו כותבין תחת השם הנכבד והנורא שם תועבותם . . והנה כבוד השם שלא יזכירנו מרדכי במגילה“. אבל [מזה ששלחה אסתר „כבר כתובה אני על ד״ה למלכי מדי ופרס“ (מגילה ז, א) מבואר, שהסיפור דאסתר וכו׳ הי׳ כתוב בדה״י של מלכיהם לפני כתיבת המגילה. וכ״מ גם בדרך הפשט, שהרי „על ספר דברי הימים למלכי מדי ופרס“ כתובים „כל מעשה תקפו וגבורתו ופרשת גדולת מרדכי“ (אסתר י, ב) — גם מה שלא נכתב במגילה, ובמילא א״א לומר שהפרסיים העתיקו זה מהמגילה. ונוסף לזה: גם לפירוש הראב״ע] מכיון שכל הענינים, ובפרט ענינים שבתורה, הם בהשגח״פ, הרי זה עצמו שהיו סיבות כאלו שבשבילן לא היו יכולים לכתוב במגילה את השם (ובפרט סיבה כזו — שהי׳ אפשר להיות שימירו את השם בשם תועבותם), מורה שהמגילה שייכת להסתר."],["10","10","אף שהיא רק מעשה זוטא (סנה׳ סה, א)."],["11","11","ועד, שהשלילה דהזכרה כו׳ מראה על תכונתו של עשו (רש״י תולדות כז, כא. מב״ר פס״ה, יט)."],["12","12","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370031\" data-slug=\"torah-or\" data-id=\"3901370031\">תו״א</a> יד, ריש ע״ב. שעה״ת לאדמו״ר האמצעי ח״א ח, ב. ד״ה חכמות בחוץ תרנ״ה תרצ״ד פ״ב (סה״מ קונטרסים ח״ב רצו, א). ולהעיר מסה״מ אידיש ע׳ 138־9."],["13","13","נסמן בלקו״ש ח״ד ע׳ 1080."],["14","14","ישעי׳ ו, ג. 14*) תקו״ז תנ״ז."],["15","15","יתרה מזו י״ל שזהו ענין בעבודת האדם לקונו ד„יחשוב בכל עסקיו ועניניו“ „שממה״מ הקב״ה חופף עליו וכו׳“ (שו״ע אדה״ז או״ח רס״א — מהדו״ק. ועיין ג״כ שם מהדו״ת)."],["16","16","ונוסף להתמי׳ שבעצם הענין, אינו מובן כלל: הרי גם ענין זה — שלא נזכר שמו של הקב״ה בכל המגילה היא הוראה (ובפרט שזה שייך לכללות המגילה, כנ״ל). ולכאורה: מהי ההוראה והלימוד מזה, והרי אדרבה — ההנהגה צ״ל שיהא ש״ש שגור בפיו?!"],["17","17","ב״ב יד, ב. טושו״ע יו״ד סו״ס רפג."],["18","18","מגילה שם."],["19","19","ראה חולין קלט, ב (הובא לקמן בפנים). וראה גם מגילה יג, א: על שם שהיתה מסתרת כו׳. וגם לפי דיעה השני׳ (שבמגילה שם) „על שום אסתהר“ שהו״ע של (גילוי ו)מעלה, מ״מ יש בזה גם ענין ההסתר, שהרי אוה״ע קורין אותה כן — בדוגמת ההסתר ד„פורים“ שהוא בלשון פרסי."]]],[1300061202,"און נאָך מער — אויף אַ דאָפלטן הסתר, ווי די גמרא²⁰ זאָגט: „אסתר מן התורה מנין ואנכי²¹ הסתר אסתיר“, צוויי מאָל הסתר²².\nאבער לאידך גיסא, ווייזט דער נאָמען „מגילת אסתר“ (ובפרט ווי זי ווערט אויך גערופן²³ „מגילה“ סתם) אויף גילוי — „מגילה“ פון לשון גילוי²⁴:\nאון פּונקט ווי אין דער מגילה זעט מען צוויי ענינים הפכים — העלם און גילוי, אַזוי זעט מען עס אויך אין דעם יו״ט פורים: פון איין זייט הייסט דער יו״ט מיטן נאָמען פורים — וואָס איז אַ לשון פרסי און וואָס ווערט גערופן על שם אַן ענין וואָס איז פאַרבונדן מיט דער גזירה — ווייזט עס אַז דער יו״ט איז פאַרבונדן מיט אַן ענין פון העלם והסתר; ולאידך גיסא, זיינען די ימי הפורים ימי משתה ושמחה, אַ סך מער ווי אַנדערע ימים טובים, ביז צו אַ שמחה גדולה ביותר למעלה מכל מדידה והגבלה, אין אַן אופן פון „עד דלא ידע כו׳“²⁵.\nה. צו פאַרשטיין דאָס, דאַרף מען פריער מקדים זיין אין הוראה (פון פילע אַנדערע) פון כללות סיפור המגילה און פון פורים (אַ הוראה וואָס איז מובנת גאָר אין פשטות)²⁶:\nאין דער צייט פון גזירת המן, האָבן אידן געהאַט גאָר חשוב׳ע פאַרשטייער אין דער מלוכה: מרדכי איז געווען אַ „יושב בשער המלך“²⁷, און דערצו האָט ער געראַטעוועט דעם מלך׳ס לעבן²⁸; און אסתר איז געווען אַ מלכה, ובפרט אַז „ותשא חן וחסד לפניו“²⁹.\nאיז לכאורה, בעת מען האָט זיך דערוואוסט פון דער גזירה, האָט מען לכל לראש געדאַרפט נוצן אָט די פאַרשטייער זיי זאָלן זיך משתדל זיין ביים מלך אחשורוש צו מבטל זיין די גזירה.\nדערציילט אָבער די מגילה, אַז די ערשטע פעולה וואָס מרדכי האָט געטאָן איז געווען — „וילבש שק ואפר ויצא בתוך העיר“: ער האָט זיך גענומען צו תשובה און גערופן אַלע אידן זיי זאָלן תשובה טאָן³⁰. און ערשט לאחרי זה האָט ער געשיקט אסתר׳ן „לבא אל המלך להתחנן לו ולבקש מלפניו על עמה“³¹;\nאון אויך אסתר האָט זיך געפירט אין דעם זעלבן סדר: בשעת זי האָט געדאַרפט גיין אל המלך, האָט זי צום אַלעם ערשטן איבערגעגעבן צו מר־",[["","","ולהעיר, שלפי ב׳ הדיעות — ש„היתה מסתרת כו׳ אין אסתר מגדת את עמה“ וש„היו אוה״ע כו׳“ — הוא הסתר בענין היהדות (תוכן ההוראה דלקמן ס״ט)."],["20","20","חולין שם."],["21","21","וילך לא, יח."],["22","22","וידוע (תולדות י״י ר״פ בראשית. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071041\" data-slug=\"likkutei-sichot\" data-id=\"1300071041\">לקו״ש ח״ז ע׳ 41</a> ואילך (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091193\" data-slug=\"likkutei-sichot\" data-id=\"1300091193\">ס״ד). ח״ט ע׳ 193</a>) פירוש הבעש״ט בזה, שההסתר גופא הוא בהסתר, היינו שאין יודעים כלל שהוא הסתר."],["23","23","בכל מס׳ מגילה (ועד שמטעם זה, גם המסכתא נק׳ מגילה). ונוסף לזה: גם ביחס לשאר המגילות (שה״ש כו׳) נקראת „מגילה“ סתם (רמב״ם הל׳ ס״ת פ״ז הט״ו)."],["24","24","תו״א קיט, רע״א (מפע״ח שער הפורים פ״ה)."],["25","25","מגילה ז, ב. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071020\" data-slug=\"likkutei-sichot\" data-id=\"1300071020\">לקו״ש ח״ז ע׳ 20</a> ואילך."],["26","26","בהבא לקמן (בסעיף זה ושלאחריו) ראה בארוכה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011227\" data-slug=\"likkutei-sichot\" data-id=\"1300011227\">לקו״ש ח״א ע׳ 213</a> ואילך."],["27","27","אסתר ב, יט. ועוד. וראה מגילה (יג, סע״א) שאחשורוש שקל עצה ממרדכי."],["28","28","אסתר שם, כא ואילך. ובפרט, אשר בפועל היתה התחלת ביטול הגזירה ע״י שאחשורוש זכר את זה (שם ו, ב ואילך)."],["29","29","אסתר ב, יז."],["30","30","שם ד, ג. תרגום שני שם, א."],["31","31","אסתר שם, ח."]]],[1300061203,"דכי³² — „לך כנוס את כל היהודים גו׳ וצומו עלי ואל תאכלו ואל תשתו שלשת ימים לילה ויום“, און דערמיט האָט זי זיך נאָך ניט באַגנוגנט, נאָר זי האָט מוסיף געווען „גם אני גו׳ אצום כן“.\nולכאורה: זי האָט דאָך דאַן געדאַרפט אָנקומען צו מציאת חן בעיני אחשורוש — ובפרט אַז איר קומען אל חצר המלך הפנימית איז געווען „לא כדת“³³ און פאַרבונדן מיט סכנת נפשות ממש — „אחת דתו להמית“³³ — און ס׳האָט זיך געפאָדערט אַ נשיאת חן ביחוד (ווייל „ואני לא נקראתי . . זה שלושים יום“³³) — היינט ווי איז ביי איר רעכט געווען³⁴ צו פאַסטן דריי מעל״ע נאָכאַנאַנד³⁵, אַ זאַך וואָס ברענגט (ע״פ טבע³⁶) צו פאַרלירן דעם חן?\nו. נאָר דער ביאור איז דאָ בפשטות: מרדכי ואסתר האָבן געוואוסט קלאָר, אַז די גזירה אויף אידן איז ניט „מנהגו של עולם אירע לנו וצרה זו נקרה נקרית“, נאָר „בגלל מעשיהם הרעים הורע להן“³⁷; און היות ווי דאָס איז אַ דבר פשוט, אַז מען קען ניט מבטל באמת זיין דעם „מסובב“ (די גזירה) כל זמן מען נעמט ניט אַראָפּ\nדי „סיבה“ (די מעשים רעים) — איז זייער ערשטע פעולה געווען — רופן אידן צו תשובה און גוזר זיין תענית\n[און ניט סתם גערופן צו תשובה, נאָר אויסגעטייטשט קלאָר דעם חטא אויף וועלכן מען דאַרף תשובה טאָן, ווי עס שטייט אין מדרש³⁸ אויפן פסוק „וצומו עלי ואל תאכלו ואל תשתו“: „אתם צמים על שאכלתם ושתיתם מסעודתו של אחשורוש“].\nאון לאחרי ווי דורך תשובה האָט מען אַראָפּגענומען די סיבת הגזירה, און דער אויבערשטער וויל דאָך דעם „בכל אשר תעשה“³⁹, מען זאָל טאָן עפּעס אויך אין דרכי הטבע, איז מען דעמאָלט געגאַנגען צו אחשורוש׳ן אָפּצושרייען די גזירה.\nאון וויל דער גיין צו אחשורוש׳ן איז געווען ניט מער ווי אַ לבוש (בכדי די הצלה מלמעלה זאָל האָבן אַן אחיזה אין טבע), אָבער די סיבה פון דער הצלה איז תשובה און תענית, איז שוין פאַרשטאַנדיק, אַז דעם עיקר אַכט האָט מען געלייגט ניט אויפן לבוש נאָר אויף דער סיבה⁴⁰.\nז. די הוראה דערפון איז מובן בפשטות:\nבעת עס קומט אַן עת צרה ר״ל, זיינען פאַראַן אַזוינע וואָס מיינען אַז די ערשטע און עיקר אַרבעט דאַרף זיין צו זוכן השתדלות אין דרכי הטבע — דערציילט אונז די מגילה, אַז דאָס",[["32","32","שם, טז."],["33","33","שם, יא."],["34","34","ולהעיר משו״ע או״ח (סו״ס תקעא) שאלו שצריכים להלחם אין רשאים להתענות אז כ״א לכשינצלו."],["35","35","בראב״ע כאן: „יתענו שני ימים ושני לילות“ (ומ״ש „שלשת ימים“ הוא „עד יום השלישי“). ובילק״ש כאן (רמז תתרנ״ו) „שהיו מפסיקין מבעוד יום“. אבל בש״ס יבמות (קכא, ב) מוכח כבפנים, שהרי המעשה דר״מ שם (ע״א) הוא שעלה לאחר שלשה ימים."],["36","36","ראה ראב״ע ד, טז."],["37","37","רמב״ם הל׳ תעניות פ״א ה״ב־ג."],["38","38","ילקו״ש אסתר רפ״ה (רמז הנ״ל)."],["39","39","ראה טו, יח."],["40","40","ואף שכנ״ל (הערה 34) עיר שהקיפוה עכו״ם „אינם רשאים להתענות שלא לשבר כחם“ — י״ל, דשאני בנדו״ד שהמדובר ביחיד (אסתר) — כיון שכל היהודים שבשושן צמו שלשה ימים, אין ליחיד לפרוש מהם. ועצ״ע."]]],[1300061204,"איז אַ שפּעטערדיקע זאַך: די ערשטע פעולה דאַרף זיין צו שטאַרקן דעם פאַרבונד מיטן אויבערשטן דורך לערנען זיין תורה און מקיים זיין מצותיו, און ערשט דאַן, זוכן פאַר דער הצלה אַ לבוש אין טבע. און אויב מ׳וועט אַזוי טאָן, איז וועלכן לבוש טבעי מען וועט נאָר מאַכן, וועט זיך אין אים אָנטאָן די הצלה הנסית שלמעלה מהטבע.\nאון פּונקט ווי דאָס איז בנוגע כלל ישראל, איז עס אַזוי אויך לגבי יעדן אידישן יחיד: אַ איד דאַרף וויסן⁴¹ אַז ער איז פאַרבונדן מיטן אויבערשטן, וואָס ער איז ניט באַגרענעצט ח״ו אין חוקי הטבע; עס דאַרף טאַקע אויך זיין דער „בכל אשר תעשה“ און וואָס עס זאָל זיך אָנטאָן דער „ובירך הוי׳ אלקיך“⁴², אָבער היות אַז דער „תעשה“ וואָס דער מענטש טוט איז ניט מער ווי אַ לבוש, איז דעריבער מובן בפשטות, אַז דער עיקר השתדלות דאַרף זיין ניט אין דעם לבוש⁴³, נאָר אין דעם באַקומען די ברכה פון אויבערשטן, וואָס דאָס טוט מען דורך לימוד התורה וקיום המצות.\nאָבער אויב מען „פאַרבייגט“ דעם עיקר צוליב שטאַרקן דעם לבוש, איז\nדאָס ענלעך צו איינעם וואָס גייט אין באַנק אַרויסצונעמען געלט ווען ער האָט ניט קיין טשעק מיט וואָס דאָס געלט צו באַקומען אָדער דער טשעק איז פון אַזאַ וואָס האָט ניט קיין רעכנונג אין באַנק.\n— די ערשטע זאַך דאַרף ער זיך באַוואָרענען מיט אַ „טשעק“, און אַז דער „טשעק“ זאָל זיין ניט פון „בורות נשברים אשר לא יכילו המים“⁴⁴, נאָר, להבדיל, פון דעם וואָס „לי הכסף ולי הזהב“⁴⁵; און לאחרי ווי ער האָט שוין דעם „טשעק“, זאָגט אים דער אויבערשטער אַז ער זאָל אים „אויסבייטן“ אין אַ לבוש טבעי דורך „בכל אשר תעשה“.\nח. קען מען מיינען, אַז כל הנ״ל איז נאָר אין אַ זמן ווען ס׳איז מאיר אלקות בגילוי; אָבער בזמן הגלות, ובפרט בעקבתא דמשיחא, ווען ס׳איז אַ „חושך כפול ומכופל“, איז וויבאַלד אַז דער אויבערשטער אַליין האָט געמאַכט דעם „חושך“, איז עס אַ הסתר אמיתי ח״ו, אַז די השפעה מלמעלה (פון ענינים גשמיים) איז איבערגעגעבן געוואָרן (ברצונו ית׳) צו חוקי הטבע⁴⁶,\nאויף דעם קומט דער ענטפער, אַז אויך בזמן פורים זיינען אידן געווען אין גלות, „מפוזר ומפורד בין העמים“⁴⁷, און דער מצב איז געווען",[["41","41","ראה דרמ״צ קז, א ואילך. ד״ה וידעת היום תרנ״ו. ובכ״מ. ויתרה מזו, שיש כמה דברים שהאדם צריך להניח על הנהגת ה׳ לבדו ושלא לעשות שום דבר כ״א לבטוח . . כאשר רואין שההנהגה צ״ל באופן כזה א״ז בכלל אין סומכין על הנס כו׳ (ד״ה בסוכות תער״ג — בהמשך תער״ב)."],["42","42","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071196\" data-slug=\"likkutei-sichot\" data-id=\"1300071196\">לקו״ש ח״ז ע׳ 184</a>. וש״נ."],["43","43","ואדרבה, המרבה בלבושים הוא מקלקל, בדוגמת אדם העושה לבוש ארוך ביותר מכפי מדת גופו שגורם שיכשל בו כו׳ (דרמ״צ קז, ב)."],["44","44","ירמי׳ ב, יג."],["45","45","חגי ב, ח."],["46","46","ובדוגמת טענת המרגלים, שאין בעה״ב יכול (ח״ו) להוציא כליו משם (סוטה לה, א. ערכין טו, א), דאף שהוא ה״בעה״ב״, בכ״ז, מכיון שברצונו ית׳ נפלו (ע״י שבה״כ) בהקליפות, אינו יכול להוציא אותם (ראה דרמ״צ קפה, ב. לקו״ש ח״ד ע׳ 1044)."],["47","47","אסתר ג, ח — וכן ברוחניות, שהם מפוזר ומפורד „בריבוי המחשבות"]]],[1300061205,"אויך לאחר הנס, ווי די גמרא⁴⁸ זאָגט „אכתי עבדי אחשורוש אנן“: און אעפ״כ איז אויך דעמאָלט געקומען די הצלה (ניט דורך דרכי הטבע, נאָר) דורך „צומו עלי גו׳ שלשת ימים“, דורך אומקערן זיך צום אויבערשטן.\nט. און דאָס איז די הוראה פון דעם וואָס דער יו״ט הייסט מיטן נאָמען „פורים“ (בלשון פרסי, און וואָס ווייזט אויף דער גזירה, כנ״ל ס״ב), און אויך דערפון וואָס אין דער מגילה ווערט ניט דערמאָנט (בגלוי⁴⁹) שם־שמים — ווייל אין דעם באַשטייט דער אויפטו פון „פורים“ און „מגילת אסתר“:\nאַז דאָס וואָס אידן זיינען ניט אונטערגעוואָרפן צו חוקי הטבע, איז עס ניט בלויז בנוגע למילי דשמיא, זייערע ענינים רוחניים (ווי הצלחה אין לימוד התורה אליבא דאמת, וואָס דאַרף האָבן סייעתא דשמיא וואָס קומט דורך יראת שמים), אָדער אפילו אין משא ומתן ווען דער מסחר ווערט געפירט צווישן אידן — ווייל צווישן זיך איז דאָך „לא שינו את לשונם וכו׳“⁵⁰ —\nנאָר אויך אין עניני מסחר וואָס אַ איד פירט מיט אַ ניט־אידן, להבדיל, ווען ער מוז צו אים ריידן בלשון פרסי, און היות אַז „הלכה בידוע שעשו שונא ליעקב“⁵¹, איז דאָך מעגלעך אַז דער גוי זאָל זוכן קעגן אים\nפאַרשידענע עצות און תחבולות — „הפיל פור“; און אפילו ווען ער שטייט אין אַזאַ מצב ווען ס׳איז דאָ אַ חשש⁵² אַז אַנשטאָט דערמאָנען שם־שמים וועט דער גוי דערמאָנען, להבדיל, שם ע״ז⁵³,\nקען ער דאָך מיינען: וויבאַלד אַז דער גוי איז יע אונטערגעוואָרפן צו חוקי הטבע; און די השפעה צום אידן גייט דאָך לכאורה צוזאַמען מיט דער השפעה צום גוי (וואָרום זיי האַנדלען צוזאַמען), איז במילא אויך דער איד אונטערגעוואָרפן צו טבע⁵⁴\nאויף דעם איז די הוראה פון „פורים“ און „מגילת אסתר“, אַז אויך בעת אַ איד האָט צו טאָן מיט „פורים“ בלשון פרסי און „אסתר“ מלשון הסתר אסתיר, דאַרף ער וויסן אַז אין דעם איז דאָ דער למעלה מהטבע: דער „פור“ איז „הוא הגורל“, וואָס גורל איז ענינו למעלה מהשתלשלות⁵⁵, און אין דעם „הסתר אסתיר“ איז דאָ דער „אנכי“⁵⁶, וואָס איז העכער פון אַלע שמות⁵⁷, אפילו פון שם הוי׳⁵⁸.",[["","","דעוה״ז“ (ד״ה בלילה ההוא ש״ת ספ״ד)."],["48","48","מגילה יד, א."],["49","49","משא״כ בר״ת וס״ת כו׳. ואדרבא „צריך לכוון בהם“ (פע״ח ש׳ הפורים פ״ו. ועיין ג״כ משנת חסידים במקומו)."],["50","50","ויק״ר פל״ב, ה. במדב״ר פ״כ, כב. וראה לקו״ד ח״ג (תו, א), שהכוונה היא לה„אידישע גלות־שפראך“."],["51","51","ספרי בהעלותך ס, י. רש״י וישלח לג, ד."],["52","52","ראה פתיחת הראב״ע למג״א (נעתק לעיל הערה 9)."],["53","53","ראה או״ח סקנ״ו."],["54","54","ובדוגמת הס״ד „הואיל ורבי עובד ע״ז אף אני כן“ (תו״כ ורש״י ס״פ בהר. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071195\" data-slug=\"likkutei-sichot\" data-id=\"1300071195\">לקו״ש ח״ז ע׳ 183</a> ואילך)."],["55","55","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370116\" data-slug=\"torah-or\" data-id=\"3901370116\">תו״א כד, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370549\" data-slug=\"torah-or\" data-id=\"3901370549\">קכג, ג</a>. וראה גם אגה״ק סוס״ז. דרושים עה״פ אך בגורל יחלק את הארץ (באוה״ת פנחס ועוד)."],["56","56","כמ״ש (וילך לא, יח) ואנכי הסתר אסתיר. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091195\" data-slug=\"likkutei-sichot\" data-id=\"1300091195\">לקו״ש ח״ט ע׳ 195</a> בסופה."],["57","57","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380641\" data-slug=\"likkutei-torah\" data-id=\"4001380641\">לקו״ת פנחס פ, ב</a> ובזח״ג רנז, ב „דאנכי“ הוא בחי׳ דלא אתפס בשם ולא אתרמיז כו׳."],["58","58","ראה גם חור״א (ק, ב. קכא, ג) שהטעם לזה שלא נזכר במגילה שום שם הוא — לפי שהאור המלובש בה הוא למעלה מבחי׳ השמות. עיי״ש."]]],[1300061206,"י. און בשעת אַ איד לייענט „מגילת אסתר“ — אַז אויך די ענינים פון „אסתר“ (דער הסתר כפול, „הסתר אסתיר“) לייענט ער (און נעמט אויף) אלס „מגילה“ פון לשון גילוי, ווייל ער ווייס אַז אויך דער „פור“ (ביז צום „פור“ וואָס המן האָט געוואָרפן) איז „הוא הגורל“ — און (דאָס אַלעס איז) ניט „למפרע“ נאָר עס איז באַ אים איצטער,\nדאַן קומט ער צום תכלית הגילוי — מגילה סתם, וואָס ברענגט צו אַ שמחה גדולה ביותר ביז אין אַן אופן פון „עד דלא ידע כו׳“, אַ שמחה בלתי מוגבלת,\nאון דורך דעם, איז סומכין גאולה לגאולה⁵⁹, אַז פון דער גאולה דפורים\nקומט מען צו דער גאולה העתידה (וואָס איז בדוגמא⁶⁰ צו דער גאולה פון יציאת מצרים),\nוואָס דאַן וועט זיין „ולילה כיום יאיר“⁶¹, אַז אויך דער חושך פון „לילה“ וועט לייכטן (כנ״ל בענין „מגילת אסתר“, אַז אויך דער הסתר ווערט גילוי),\nבביאת משיח צדקנו, יבוא ויגאלנו בקרוב ממש.\n(משיחת פורים תשכ״ו)",[["59","59","ראה מגילה ו, סע״ב."],["60","60","מיכה ז, טו."],["61","61","תהלים קלט, יב. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071041\" data-slug=\"likkutei-sichot\" data-id=\"1300071041\">לקו״ש ח״ז ע׳ 41</a> ואילך בפירוש „בלילה ההוא נדדה שנת המלך“ — תוקפו של הנס דפורים, שההסתר ד„בלילה ההוא“ — תכלית ההסתר — נעשה בחי׳ „נדדה שנת המלך“ — תכלית הגילוי. עיי״ש באריכות."]]],[1300061207,"<h3>תשא</h3>\nא. אין דער היינטיקער סדרה ¹) שטייט געשריבן דער ציווי אויף מאכן דעם כיור. וואס דערמיט איז דער כיור אפגעטיילט פון אלע אנדערע כלי המשכן, וועגן וועלכע עס רעדט זיך אין די פריערדיקע צוויי סדרות ²) — הגם אז אויך דער כיור איז אן „עיקר בבנין הבית״ ³), און בנוגע משיחה ב־שמן המשחה ווערט ער ווייטער אין דער סדרה גערעכנט צוזאמען מיט די אנדערע כלים און אויף זיי אלע צו־זאמען זאגט דער פסוק „והיו קודש קדשים״ ⁴). היינט פארוואס שטייט דער ציווי עשיית הכיור, באזונדער פון די אנדערע כלים?\nזאגן מפרשים ⁵), אז דאס איז דער־פאר וואס ער איז (ניט קיין ענין ל־עצמו, נאר) א הכנה צו „בבואם אל אהל מועד״ און „בגשתם אל המזבח״.\nאון אט דער חילוק צווישן דעם כיור און אלע אנדערע כלי המשכן קומט צום אויסדרוק (ניט בלויז אין דעם ארט פונעם ציווי על עשיית הכיור אין תורה, „ועשית כיור״, נאר אויך) אין דעם ארט וואו דער כיור איז געשטאנען אין משכן:\nדער ארט פון אלע כלי המשכן איז געווען אין אהל מועד. אויך דער מזבח הנחושת, וואס ער איז געווען אין חצר, איז ער אבער געשטאנען „פתח משכן אהל מועד״ ⁶). משא״כ דער כיור איז ניט געשטאנען בפתח המשכן נאר איז געווען אפגערוקט אין א זייט, ביז אז — „אין כיור לפני אהל מועד״ ⁷) (וואס דערפאר האט מען געקענט צו אים צוגיין צוליב רחיצת ידים ורגלים, כאטש „בין האולם למזבח״ האט מען (לכמה דיעות ⁸) ניט געטארט אריין־גיין פאר קידוש ידים ורגלים ⁹).\nב. אט דער ענין, אז כיור איז א הכנה צו כללות עבודת המשכן, דריקט זיך אויס אויך אין דעם שיעור פון דער מאס פון כיור:\nפון פסוק „ורחצו ממנו משה ואהרן ובניו״ ¹⁰) (וואו עס ווערן גערעכנט פיר מענטשן: „משה ואהרן תרין ובניו תרין״ ¹¹) לערנט אפ די גמרא ¹²): „כל כיור שאין בו כדי לקדש ארבעה כהנים ממנו אין מקדשין בו״.\nולכאורה: משה האט זיך געדארפט וואשן פון כיור נאר אין די ימי המי־לואים (לויט דער דעה ¹³) אז דערנאך",[["1","1","ל, יז ואילך."],["2","2","הטעם על זה שהציווי על מזה״פ הוא בפ׳ תצוה (ולא בפ׳ תרומה) — ראה רמב״ן וספורנו תצוה ל, א. אוה״ח תרומה כה, ט ד״ה ונראה."],["3","3","ראה רמב״ם הל׳ ביהב״ח פ״א ה״ה־ו. ולהעיר מספהמ״צ שלו שרש יב. מ״ע כ."],["4","4","ל, כט."],["5","5","חזקוני וספורנו ל, יח."],["6","6","פקודי מ — ו, כט."],["7","7","רש״י פרשתנו ל, יח (מזבחים נט, רע״א), ולהעיר מראב״ע עה״פ."],["8","8","כלים ספ״א, תוספתא שם (הובא ב־תוס׳ שבהערה הבאה ובר״ש כלים שם), פסקי תוס׳ תמיד סט״ז."],["9","9","ראה תוד״ה הא׳ מני זבחים נח, ב."],["10","10","פקודי מ, לא."],["11","11","רש״י זבחים יט, ב. ואף שהיו גם נדב ואביהוא — ראה מפרשי הש״ס שם, תורה תמימה פקודי (מ, לא) ועוד."],["12","12","זבחים שם. אבל ראה רמב״ם הל׳ ביאת מקדש (פ״ה הי״ג) ובנ״כ שם."],["13","13","זבחים קב, א. וראה לעיל ע׳ 175 הערה 28."]]],[1300061208,"לא שמש בכהונה), און שפעטער איז דער כיור נוגע בלויז צו אהרן ובניו, איז פארוואס זאל דער כיור לדורות מוזן קענען האלטן וואסער פאר פיר מענטשן, אויך כנגד משה (און ווי געבראכט די קשיא במפרשי הש״ס דארט) ?\nוי״ל דעם ביאור אין דעם ¹⁴): די ימי המילואים זיינען געווען א הכנה צו דער כללות העבודה פון אהרן ובניו שפעטער. און היות אז אויך דער כיור איז ענינו הכנה לכללות העבודה, כנ״ל, דארף שיעורו דערי־בער זיין „כדי לקדש ארבעה כהנים״, ניט נאר „כנגד אהרן ובניו״, וואס האבן מקדש געווען פון כיור נאך די ימי המילואים, נאר אויך „כנגד משה״, (אלע ¹⁵) כהנים אין דער צייט פון חנו־כת המשכן, אלע) וואס האבן מקדש געווען פון אים אין די ימי המילואים, זמן ההכנה.\nדערפון איז פארשטאנדיק, אז כאטש דער כיור איז געווען בלויז א הכנה לעבודה, איז אבער אין אים געווען א מעלה מיוחדת, העכער פון די אנ־דערע כלי המשכן, וואס מטעם דער מעלה איז דוקא אין אים געווען אן ענין וואס איז מרמז אויף משה׳ן, וואס ער איז דאך העכער אויך פון אהרן, ויתרה מזו: אויף משה׳ן צו־זאמען מיט אלע כהנים וואס זיינען דאמאלס געווען.\nג. אט די צוויי קצוות פון דעם כיור\n— אז פון איין זייט איז ער בלויז א הכנה, און מאידך גיסא איז דוקא אין אים פאראן ענינו של משה (וכל הכהנים) בגלוי (וואס דאס איז ניטא אין די אנדערע כלי המשכן) —\nזיינען מרומז אויך אין די „מראות הצובאות״, וואס פון זיי איז דער כיור געמאכט געווארן:\nפון איין זייט, זיינען די מראות הצובאות א גאר נידעריקער ענין, ביז אז אפילו משה רבינו, האטש ער איז „אוהב ישראל״ ¹⁶), האט אין זיי מואס געווען „מפני שעשוים ליצר הרע״ [און זיי ווערן ניט גערעכנט צווישן די אלע נדבות המשכן פון פ׳ פקודי, זיי זיינען גאר ניט אין כלל פון „פקודי המשכן״]; ואעפ״כ, איז דוקא אויף די „מראות הצובאות״ האט דער אויבערשטער גע־זאגט „אלו חביבין עלי מן הכל״ *¹⁶.\nד. דער ביאור אין דעם איז:\nשוין גערעדט פיל מאל ¹⁷), אז דער חידוש פון „ועשו לי מקדש ושכנתי בתוכם״ *¹⁷ באשטייט אין דעם, אז אידן זאלן נעמען דברים גשמיים און פון זיי מאכן א מקדש פאר דעם אוי־בערשטן, ביז אז אין די (דרייצן ¹⁸ צי פופצן ¹⁹) דברים גשמיים זאל זיין „ושכנתי בתוכם״, וואס דורך דעם וועט",[["16","16","מנחות סה, א. *16) רש״י ויקהל לה, ח. וראה גם תנחומא פקודי ט."],["17","17","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300031164\" data-slug=\"likkutei-sichot\" data-id=\"1300031164\">לקו״ש ח״ג</a> פ׳ תרו־מה. ובכ״מ. *17) תרומה כה, ח."],["18","18","שהש״ר פ״ה, יג. זח״ב קמח, א. תנחומא תרומה ה — הובא ברש״י ר״פ תרומה (וראה אוה״ת תרומה ע׳ א׳שפג. א׳שצ). ועוד."],["19","19","בחיי תרומה כה, ז. כלי יקר שם, ג. וראה זהר שם קלה, א."],["14","14","וראה כמה תירוצים: ברש״י, שיטה מקובצת וכו׳."],["15","15","למ״ד דלא נתכהן פנחס עד שהרגו לזמרי (זבחים קא, ב). וכדעת רש״י בפי׳ עה״ת (פנחס כה, יג)."]]],[1300061209,"נשלם ווערן דער ענין פון „נתאוה ²⁰) הקב״ה להיות לו ית׳ דירה בתחתונים״.\nאון וויבאלד אז די כוונה פון „דירה בתחתונים״ איז דאך ביז צום תחתון ביותר „שאין תחתון למטה ממנו״ ²¹), האט דעריבער געדארפט זיין אין משכן אויך אן ענין פון „מראות הצובאות״, וואס זיינען „עשוים ליצר הרע״, בכדי אז אויך דער תחתון זאל ווערן א דירה לו ית׳.\nאבער פונדעסטוועגן האט משה מואס געווען אין דעם, וארום משה „נתנבא בזה״ ²²), דאס מיינט, אז בי׳ אים איז געווען ראיית מהות אלקות, האט ער געוואלט אז דער גילוי פון „ושכנתי בתוכם״ זאל זיין אין אן אופן פון ראיית המהות. און וויבאלד אז די זאכן וועלכע זיינען פארבונדן מיטן נה״ב און יצה״ר, אפילו לאחרי ווי זיי ווערן נתברר, זיינען מעלים ומס־תיר אויף ראיית המהות\n[וכידוע ²³) בענין „אספקלריא שאינה מאירה״ (א זכוכית מיט א כיסוי פון א „דבר דק וקלוש״ — א שפיגל), וואס הגם אז דוקא דורך דער פאר־מיטלונג פון דעם צודעק וואס אויף איר, קען דער מענטש זען מאחוריו, וואס דורך אן „אספקלריא המאירה״ קען מען עס ניט זען — איז אבער דאס געזעענע דורך אן אספקלריא ש־אינה מאירה ניט די זאך גופא, נאר א „דמות״, און „אפשפיגלונג״ פון דער זאך.\nועד״ז איז אויך בנוגע דעם בירור פון נפש הבהמית: אע״פ אז דוקא דורכן בירור פון נה״ב (בחי׳ אספק־לריא שאינה מאירה) ווערט נמשך אן אור חדש וואס איז העכער פון דעם אור הנמשך דורך מעשה המצות (בחי׳ אספקלריא המאירה), איז אבער דער אור ניט בגילוי כ״כ און ער איז מאיר בלויז אין אן אופן פון „דמות״],\nהאט דעריבער משה (וואס „נסתכל באספקלריא המאירה״ ²⁴) ניט געוואלט אז אין משכן זאלן זיין די מראות הצובאות (בחינת אספקלריא שאינה מאירה ²⁵), בכדי אז דער „ושכנתי בתוכם״ זאל זיין אין אן אופן פון „זה״, גילוי המהות ²⁶).\nאי וואס די כוונה איז „דירה בתח־תונים״ — איז אבער לגבי מדריגת משה (וואס צו דער מדריגה האט ער געוואלט אויפהויבן אלע אידן), זיינען שוין אויך די אנדערע זאכן פון נדבת המשכן (ובפרט „נחושת״ ²⁷) גענוג",[["20","20","תנחומא נשא טז. וראה לעיל ע׳ 17 הערה 42."],["21","21","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל״ו</a>."],["22","22","ספרי ורש״י ר״פ מטות. וראה רמב״ם (הל׳ יסוה״ת פ״ז ה״ו ועוד. נסמן לעיל ע׳ 38 הערה 26). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו״ת מטות פב, סע״א</a> ואילך."],["23","23","ראה בכ״ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370153\" data-slug=\"torah-or\" data-id=\"3901370153\">תו״א לג, א</a>־ב."],["24","24","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380909\" data-slug=\"likkutei-torah\" data-id=\"4001380909\">יבמות מט, ב</a>. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381242\" data-slug=\"likkutei-torah\" data-id=\"4001381242\">לקו״ת (נצבים מז, ג</a>. שמע״צ צב, ב. שה״ש כח, ב) שהו״ע אחד עם מה שנתנבא ב״זה״."],["25","25","בתו״א שם [הובא ונתבאר באוה״ת פרשתנו ס״ע א׳תתקלט ואילך. ויקהל ע׳ ב׳רכה ואילך], שמראות (הצובאות) ל׳ רבים קאי על ב׳ המראות — אספה״מ ואספשא״מ. אבל מזה שבפשטות, מראות הצובאות היו אספשא״מ, משמע שגם ברוחניות בחי׳ זו היא עיקר ענינם. וראה גם אוה״ת ויקהל שם (רס״ב) : בחי׳ הראיני את מראיך דאו״ח נק׳ מראות הצובאות. וראה גם אוה״ת בא (נעתק בהערה הבאה)."],["26","26","ראה גם אוה״ת בא ס״ע שכט : ומשה רבינו ע״ה נסתכל באספקלריא המאיר־רה . . . וא״צ למראות הצובאות."],["27","27","ראה לעיל ע׳ 158 ואילך."]]],[1300061210,"„תחתון״, דורך וועלכע עס וועט נשלם ווערן די כוונה פון „דירה בתחתו־נים״ ²⁸).\nאויף דעם האט אים דער אויבער־שטער געענטפערט, אז אין משכן דארף מען האבן אויך אזא „תחתון״ וואס איז „עשוי ליצר הרע״, ואדרבה ²⁹): ווען מען נוצט אויס דעם תחתון ב־יותר אויף צו אויפשטעלן „צבאות ה׳ ״ — ווי דורך די „מראות הצוב־אות״ האט מען אויפגעשטעלט „צבאות\nרבות במצרים״ ³⁰) — וואס צבא ווייזט אויף דער עבודה פון „קבלת עול״ ³⁰), וואס די עבודה איז מאיר בגילוי, דוקא ווען ס׳איז דא יצר הרע וכו׳ און דאן שטארקט מען זיך ³¹) אויף אים בדרך קבלת עול ³²) — דאס איז „חביבין עלי מן הכל״.\nה. כשם ווי די „מראות הצובאות״, כאטש בגילוי זיינען זיי נידעריקער פון די נדבות המשכן (וכנ״ל ס״ג אז זיי ווערן ניט גערעכנט צווישן די „פקודי המשכן״), זיינען זיי אבער „חביבין מן הכל״ ;\nאזוי איז אויך דער כיור (וואס איז פון דעם געמאכט געווארן) : כאטש ער איז בלויז א הכנה, וואס מצד דעם איז ער בגלוי נידעריקער פון אלע אנדערע כלי המשכן (און דער ציווי פון עשיית כיור ווערט ניט גערעכנט צוזאמען מיט די ציווים אויף די אנ־",[["28","28","ובדוגמת האופן ד„דירה בתחתונים״ קודם (או באם לא הי׳) חטא עה״ד — שלא הי׳ שייך אז הענין ד„דעשוים ליצה״ר״, שהרי לא ידעו כלל שיש בזה תאוה (תו״א ה, ריש ע״ד). ועפ״ז הידוע שהענין ד„ועשו לי מקדש ושכנתי בתוכם״ הוא כפרה על חטא העגל (תנחומא תרומה ח) * שאז נתעוררה הזוהמא דחטא עה״ד (זח״א נב, ב. וראה לעיל ע׳ 160 הערה 61) — י״ל, שמשה רצה שע־שיית המשכן תבטל לגמרי את הפגם שנעשה ע״י חטא העגל, ועד שיהיו ישראל במדריגה דקודם חטא עה״ד (וכמו במ״ת — שפסקה זוהמתן (שבת קמו, רע״א. זהר שם)), ולכן מאס בהמראות שעשוין ליצה״ר בחי׳ אספשא״מ (וראה זהר שם, שבשעת מ״ת כשפסקה זוהמתן „מתנהרין באספקלריא דנ־הרא״, משא״כ אחר חטא העגל)."],["29","29","ראה בארוכה ד״ה באתי לגני תשל״א (סה״מ מלוקט ח״ה ע׳ קנד ואילך) בביאור העילוי ד„דירה בתחתונים״ שע״י העבודה עכשיו (לאחרי החטא והתשובה) לגבי כמו שהי׳ קודם (או באם לא הי׳) חטא עה״ד. *) ובפרט הכיור שענינו הי׳ „לרחוץ אותו עון״ (ש״ך עה״ת פרשתנו ל, יח), אלא שמשה רצה שרחיצת העון תהי׳ באופן שלא יהיו שייכים להזוהמא (וכמו „פסקה זוהמתן״ בשעת מ״ת). וע״ז אמר לו הקב״ה שאמיתית העילוי הוא — הפיכת (היצה״ר ו)החטא עצמו לזכיות (ראה הערה הבאה והערה 33)."],["30","30","ראה המשך דיום ההילולא פ״י ואי־לך. וראה גם ד״ה בעצם היום הזה תש״א (נדפס בקונט׳ עז — בסמיכות להקונטרסים דהמשך הנ״ל). ולהעיר מזה שבתחלת המאמר בעצם היום הנ״ל, מובאה הוכחה להפי׳ צבא מהכתוב „אשר צבאו פתח אהל מועד״ שנאמר גבי מראות הצובאות. וראה הערה 32."],["31","31","וגם הנחשת שבכיור רומז לענין התוקף — מצחך נחושה (ישעי׳ מח, ד), העבודה דעז כנמר (אוה״ת פרשתנו ע׳ א׳תתקלח (בשוה״ג). ויקהל ע׳ ב׳רכח)."],["32","32","ולהעיר, שגם הבאת מראות הצוב־אות לנדבת המשכן, הי׳ באופן דאתכפיא וקב״ע, וכל׳ רש״י (לח, ח) „ואף אותן לא עכבו״. ובזה יומתק מה שהענין ד„צבא״ נאמר — (לא רק בענין „מראות הצובאות״, אלא) גם גבי הבאת המראות לנדבת המשכן — „אשר צבאו פתח אהל מועד״."]]],[1300061211,"דערע כלי המשכן ³³),\nאיז אבער די הכנה פון „ורחצו את ידיהם ואת רגליהם״ — וואס א איד וואשט זיך אפ פון די ענינים הבלתי־רצויים — איז אט די רחיצה חביב ביי דעם אויבערשטן מער ווי די עבודה גופא וואס ער טוט שפעטער אויפן מזבח אדער אין אהל מועד ³⁴),\nווייל דוקא אין דער רחיצה איז דא דער ענין פון „אתכפיא סט״א״ — בדוגמת די „צבאות הוי׳ ״ (קבלת עול) וואס קומט ארויס דורך די „מראות הצובאות״.\nאון דאס איז אויך דער טעם וואס דוקא ביים כיור איז מרומז ³⁵) אויך ענינו של משה (וכל הכהנים) ³⁶) —\nווייל דוקא אין דעם ענין פון אתכפיא וקב״ע ווערט נתגלה די אמיתיות (ושלימותו בכל הפרטים — ד)ענין הביטול ³⁷), ענינו של משה ³⁸) (ובצירוף אהרן וכל הכהנים — דעבודתם ב־חשאי ³⁹) — ביטול — ויבדל אהרן קד״ק ⁴⁰) — דקאי על כל הכהנים).\n(ממאמר ושיחות ש״פ ויקהל תשי״ט)",[["33","33","השייכות דכיור לפרשתנו ושמה (— תוכנה) תשא — י״ל, כי ענינו הוא העילוי ד„ושכנתי בתוכם״ כמו שהוא לאח־רי חטא העגל והתשובה ע״ז (ראה לעיל הערה 29)."],["34","34","ראה לעיל ע׳ 161 הערה 64. ולהעיר גם מהמשך וככה תרל״ז פט״ו, בענין המעלה שיש בדבר הגורם."],["35","35","ראה גם אוה״ת ויקהל ס״ע ב׳רכט, שהמים דכיור שייכים לבחי׳ „מן המים משיתיהו״ דמשה."],["36","36","ואף שבתחלה לא רצה משה לקבלן — הרי לאחרי שאמר לו הקב״ה „קבל״ — ובפרט שביאר לו הטעם (ע״פ חכמה ושכל) ע״ז „כי אלו חביבין עלי מן הכל״ — הרי זה נעשה ענינו של משה (ובדוגמת המבואר לעיל ע׳ 39 ואילך, שאחר שאמר הקב״ה „חבל על דאבדין כו׳״, נמ־שך במשה גם ענין זה — אף שלפנ״ז הקשה „למה הרעותה גו׳״). וראה הערה הבאה."],["37","37","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091073\" data-slug=\"likkutei-sichot\" data-id=\"1300091073\">לקוטי שיחות ח״ט ע׳ 73־74</a> ובהערות שם, שאמיתית מהות הביטול הוא בביטול היש דוקא. עיי״ש באריכות. וי״ל, שע״י שמשה קיבל מהן את מראות הצובאות, נעשה בזה ב׳ המעלות (ע״ד המבואר ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091010\" data-slug=\"likkutei-sichot\" data-id=\"1300091010\">לקוטי שיחות שם ע׳ 75</a> ס״ז) : המעלה דמהות הביטול שב„ביטול היש״ ו„אתכפיא״ ; ושביטול זה יהי׳ בגילוי (לא כבביטול היש שהביטול אינו חודר בעצם המציאות, לפי שהיש מעלים ומסתיר)."],["38","38","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370444\" data-slug=\"torah-or\" data-id=\"3901370444\">תו״א (צט, ג</a>), שהביטול דמשה הוא בחי׳ מ״ה דמ״ה והביטול דאהרן ב״ן דמ״ה."],["39","39","זח״ג לט, א. וראה ביאורי הזהר ר״פ ויצא. לקו״ת ואתחנן, ד״ה וידעת (הש־ני) פ״ב. ושם ד״ה ושאבתם (השני) פ״א."],["40","40","דה״א כג, יג."]]]]});
